/* Tamil — தமிழ்
   Question bank translation. Keyed by question id; options are
   pipe-separated and stay in the English source order.
   UK proper nouns, institutions and official terms are left in
   English, glossed in Tamil on first use where it helps. */

export default {

  /* ---------- CHAPTER 1-3 (core) ---------- */
  1: ["இவற்றுள் எது பிரிட்டிஷ் வாழ்வின் அடிப்படைக் கோட்பாடு?", "சட்டத்தின் ஆட்சி|கட்டாய இராணுவப் பணி|அனைவருக்கும் ஒரே தேசிய மதம்|பத்திரிகைகள் மீதான அரசுக் கட்டுப்பாடு", "அடிப்படைக் கோட்பாடுகளில் ஜனநாயகம், சட்டத்தின் ஆட்சி, தனிமனித சுதந்திரம், வெவ்வேறு நம்பிக்கைகள் மீதான சகிப்புத்தன்மை, சமூக வாழ்வில் பங்கேற்பு ஆகியவை அடங்கும்."],
  2: ["யுகேயில் வாழ்பவர்களிடம் எதிர்பார்க்கப்படும் இரண்டு விஷயங்கள் எவை? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "உங்களையும் உங்கள் குடும்பத்தையும் கவனித்துக்கொள்வது|மற்றவர்களை நியாயமாக நடத்துவது|வாரந்தோறும் வழிபாட்டுத் தலத்திற்குச் செல்வது|ஓர் அரசியல் கட்சியில் சேர்வது", "பொறுப்புகளில் சட்டத்தைக் கடைப்பிடித்தல், பிறரின் உரிமைகளை மதித்தல், மக்களை நியாயமாக நடத்துதல், தன்னையும் குடும்பத்தையும் கவனித்தல், வாழும் பகுதியைப் பராமரித்தல் ஆகியவை அடங்கும்."],
  3: ["Life in the UK தேர்வை எந்த மொழிகளில் எழுதலாம்?", "ஆங்கிலம், Welsh அல்லது Scottish Gaelic|ஆங்கிலம் மட்டும்|ஏதேனும் அதிகாரப்பூர்வ EU மொழி|ஆங்கிலம் அல்லது பிரெஞ்சு", "இத்தேர்வை ஆங்கிலம், Welsh அல்லது Scottish Gaelic மொழியில் எழுதலாம்."],
  4: ["குடியுரிமை விழாவில், விசுவாசப் பிரமாணத்துடன் புதிய குடிமக்கள் வேறு என்ன செய்கிறார்கள்?", "யுகேயின் உரிமைகள், சுதந்திரங்கள், சட்டங்களை மதிப்பதாக உறுதிமொழி|ஆயுதப் படையில் சேருவதாக வாக்குறுதி|தொண்டு நிறுவனத்திற்கு நன்கொடை|பிற அனைத்து குடியுரிமைகளையும் துறப்பதாக அறிவிப்பு", "புதிய குடிமக்கள் மன்னருக்கு விசுவாசப் பிரமாணம் எடுத்து, யுகேயின் உரிமைகள், சுதந்திரங்கள், சட்டங்களை மதிப்பதாக உறுதியளிக்கிறார்கள்."],
  5: ["இக்கூற்று சரியா தவறா? யுகே நம்பிக்கை மற்றும் மத சுதந்திரத்தை வழங்குகிறது.", "சரி|தவறு", "நம்பிக்கை மற்றும் மத சுதந்திரம் யுகேயில் அனைவரும் பெறும் உரிமைகளில் ஒன்று."],
  6: ["யுகேயில் அனைவரும் பெறும் உரிமை அல்லது சுதந்திரம் அல்லாதது எது?", "வரி செலுத்தாமல் தவிர்க்கும் உரிமை|நியாயமான விசாரணைக்கான உரிமை|அநீதியான பாகுபாட்டிலிருந்து விடுதலை|பேச்சுரிமை", "வரி செலுத்துவது ஒரு பொறுப்பு, சுதந்திரம் அல்ல. உரிமைகளில் பேச்சுரிமை, நம்பிக்கைச் சுதந்திரம், நியாயமான விசாரணை, அநீதியான பாகுபாட்டிலிருந்து விடுதலை ஆகியவை அடங்கும்."],
  7: ["குடியுரிமை விழாக்கள் பொதுவாக எங்கே நடைபெறுகின்றன?", "உள்ளாட்சி அமைப்பால் (local authority) ஏற்பாடு செய்யப்படுகிறது|Houses of Parliamentஇல்|ஓர் அரண்மனையில்|விண்ணப்பதாரரின் வீட்டில்", "உள்ளாட்சி அமைப்புகள் குடியுரிமை விழாக்களை ஏற்பாடு செய்கின்றன, பொதுவாக விண்ணப்பம் ஒப்புதல் பெற்ற மூன்று மாதங்களுக்குள்."],
  8: ["நிரந்தரக் குடியிருப்பு அல்லது குடியுரிமைக்கு விண்ணப்பிப்போர் பொதுவாக எந்த இரண்டைக் காட்ட வேண்டும்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "அவர்கள் ஆங்கிலம் பேசவும் படிக்கவும் முடியும்|யுகே வாழ்க்கை குறித்து அவர்களுக்கு நல்ல புரிதல் உள்ளது|யுகேயில் அவர்களுக்குச் சொத்து உள்ளது|அவர்கள் Londonஇல் வாழ்ந்துள்ளனர்", "விண்ணப்பதாரர்கள் ஆங்கிலம் பேசவும் படிக்கவும் முடியும் என்பதையும், யுகே வாழ்க்கை குறித்து நல்ல புரிதல் உள்ளது என்பதையும் காட்ட வேண்டும்."],
  9: ["சமூக வாழ்வில் பங்கேற்பதை எவ்வாறு சிறப்பாக விவரிக்கலாம்?", "பிரிட்டிஷ் வாழ்வின் ஓர் அடிப்படைக் கோட்பாடு|அனைத்து குடியிருப்பாளர்களுக்கும் சட்டக் கடமை|குடிமக்கள் மட்டுமே செய்யக்கூடியது|வேலைவாய்ப்பிற்கான நிபந்தனை", "சமூக வாழ்வில் பங்கேற்பு பிரிட்டிஷ் வாழ்வின் அடிப்படைக் கோட்பாடுகளில் இடம்பெறுகிறது."],
  10: ["இக்கூற்று சரியா தவறா? யுகேயில் உள்ள அனைவருக்கும் சட்டத்தை மதித்து கடைப்பிடிக்கும் கடமை உள்ளது.", "சரி|தவறு", "சட்டத்தை மதித்து கடைப்பிடிப்பது யுகேயில் வாழும் அனைவரின் அடிப்படைப் பொறுப்பாகும்."],
  11: ["யுகே ஒரு ஜனநாயகம். இதன் பொருள் என்ன?", "அதிகாரம் மக்களிடம் அல்லது அவர்கள் தேர்ந்தெடுத்த பிரதிநிதிகளிடம் உள்ளது|அதிகாரம் மன்னரிடம் மட்டுமே உள்ளது|அதிகாரம் நீதிமன்றங்களிடம் உள்ளது|அதிகாரம் இராணுவத்திடம் உள்ளது", "ஜனநாயகத்தில் அதிகாரம் மக்களிடம் உள்ளது — நேரடியாகவோ தேர்ந்தெடுக்கப்பட்ட பிரதிநிதிகள் வழியாகவோ."],
  12: ["இவற்றுள் உரிமை அல்ல, பொறுப்பு எது?", "நீங்கள் வாழும் இடத்தின் சுற்றுச்சூழலைப் பராமரிப்பது|ஓர் அரசைத் தேர்ந்தெடுப்பதில் பங்கேற்பது|அநீதியான பாகுபாட்டிலிருந்து விடுதலை|நியாயமான விசாரணை", "நீங்கள் வாழும் பகுதியையும் சுற்றுச்சூழலையும் பராமரிப்பது யுகேயில் வாழ்வதன் பொறுப்புகளில் ஒன்று."],
  13: ["United Kingdom எத்தனை நாடுகளால் ஆனது?", "நான்கு|இரண்டு|மூன்று|ஐந்து", "யுகே England, Scotland, Wales, Northern Ireland ஆகியவற்றால் ஆனது."],
  14: ["எந்த நாடுகள் சேர்ந்து Great Britain ஆகின்றன?", "England, Scotland, Wales|England, Scotland, Northern Ireland|England, Wales மட்டும்|யுகேயின் நான்கு நாடுகளும்", "Great Britain என்பது England, Scotland, Wales மட்டுமே. யுகேயில் Northern Irelandஉம் அடங்கும்."],
  15: ["இவற்றுள் எந்த இரண்டு Crown dependencies ஆகும், யுகேயின் பகுதி அல்ல? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "The Channel Islands|The Isle of Man|The Isle of Wight|Anglesey", "Channel Islands, Isle of Man ஆகியவற்றுக்குத் தனி அரசுகள் உள்ளன; அவை Crown dependencies, யுகேயின் பகுதி அல்ல."],
  16: ["இவற்றுள் எது ஒரு British overseas territory?", "The Falkland Islands|The Isle of Man|Jersey|Guernsey", "Falkland Islands, St Helena போன்ற கடல்கடந்த பகுதிகள் யுகேயுடன் தொடர்புடையவை, ஆனால் அதன் பகுதி அல்ல."],
  17: ["Walesஇன் தலைநகரம் எது?", "Cardiff|Swansea|Newport|Bangor", "Cardiff Walesஇன் தலைநகரம்; Senedd (வெல்ஷ் நாடாளுமன்றம்) Cardiff Bayஇல் கூடுகிறது."],
  18: ["Northern Irelandஇன் தலைநகரம் எது?", "Belfast|Londonderry|Dublin|Armagh", "Belfast Northern Irelandஇன் தலைநகரம். Northern Ireland Assembly Belfastஇல் உள்ள Stormontஇல் கூடுகிறது."],
  19: ["இக்கூற்று சரியா தவறா? Northern Ireland Great Britainஇன் பகுதி.", "தவறு|சரி", "Northern Ireland யுகேயின் பகுதி, ஆனால் Great Britain என்பது England, Scotland, Wales மட்டுமே."],
  20: ["யுகேயின் எந்த மூன்று பகுதிகளுக்கு devolved நிர்வாகங்கள் உள்ளன?", "Scotland, Wales, Northern Ireland|England, Scotland, Wales|Scotland, England, Northern Ireland|Wales, England, Northern Ireland", "Scotland, Wales, Northern Ireland ஒவ்வொன்றுக்கும் Westminsterஇலிருந்து சில அதிகாரங்கள் மாற்றப்பட்ட devolved அரசு உள்ளது."],
  21: ["Britainஇல் வாழ்ந்த முதல் மக்கள் யார்?", "வேட்டையாடி உணவு சேகரிப்பவர்கள்|விவசாயிகள்|வணிகர்கள்|வீரர்கள்", "Britainஇன் முதல் குடியிருப்பாளர்கள் வேட்டையாடி உணவு சேகரிப்பவர்கள், காலநிலைக்கேற்ப வந்து சென்றவர்கள்."],
  22: ["Britain நிலப்பாலம் வழியாகக் கண்டத்துடன் இணைந்திருந்தது சுமார் எத்தனை ஆண்டுகளுக்கு முன்பு நின்றது?", "10,000 ஆண்டுகளுக்கு முன்பு|1,000 ஆண்டுகளுக்கு முன்பு|100,000 ஆண்டுகளுக்கு முன்பு|500 ஆண்டுகளுக்கு முன்பு", "சுமார் 10,000 ஆண்டுகளுக்கு முன்பு கண்டத்திற்கான நிலப்பாலம் நீரில் மூழ்கியது, Britain நிரந்தரமாகத் தீவானது."],
  23: ["Orkneyஇல் உள்ள எந்த வரலாற்றுக்கு முந்தைய தளம் வட ஐரோப்பாவின் சிறந்த முறையில் பாதுகாக்கப்பட்ட கற்கால கிராமங்களில் ஒன்று?", "Skara Brae|Stonehenge|Maiden Castle|Sutton Hoo", "Orkneyஇல் உள்ள Skara Brae தொல்லியலாளர்களுக்குக் கற்கால வாழ்வின் விரிவான சித்திரத்தைத் தருகிறது."],
  24: ["Dorsetஇல் உள்ள Maiden Castle எதற்கு எடுத்துக்காட்டு?", "இரும்புக் கால மலைக்கோட்டை|ரோமானிய villa|நார்மன் கோட்டை|வைக்கிங் குடியிருப்பு", "Maiden Castle ஒரு பெரிய இரும்புக் கால மலைக்கோட்டை. வெண்கலக் கால மக்கள் வட்ட வீடுகளையும் புதைமேடுகளையும் கட்டினர்."],
  25: ["Julius Caesar Britain மீது தோல்வியுற்ற படையெடுப்பை நடத்திய ஆண்டு எது?", "55 BC|AD 43|AD 122|AD 410", "Caesarஇன் 55 BC தாக்குதல் தோல்வியடைந்தது. வெற்றிகரமான ரோமானியப் படையெடுப்பு AD 43இல் பேரரசர் Claudius தலைமையில் நிகழ்ந்தது."],
  26: ["ரோமானியருக்கு எதிராகக் கிளர்ச்சி நடத்திய, Westminster Bridgeஇல் சிலை உள்ள பழங்குடித் தலைவர் யார்?", "Boudicca|Caratacus|Kenneth MacAlpin|Alfred the Great", "கிழக்கு Englandஇன் Iceni பழங்குடியின் அரசி Boudicca ரோமானிய ஆட்சிக்கு எதிராகப் புகழ்பெற்ற கிளர்ச்சியை நடத்தினார்."],
  27: ["Hadrian's Wall ஏன் கட்டப்பட்டது?", "வடக்கிலிருந்து Picts போன்ற பழங்குடிகளைத் தடுக்க|Wales எல்லையைக் குறிக்க|வைக்கிங் தாக்குதல்களிலிருந்து பாதுகாக்க|Londonஐப் பாதுகாக்க", "ரோமானிய Britainஇன் வடக்கு எல்லையைப் பாதுகாக்க AD 122இல் பேரரசர் Hadrian இச்சுவரைக் கட்ட ஆணையிட்டார்."],
  28: ["ரோமானியப் படை Britainஐ விட்டு வெளியேறிய ஆண்டு எது?", "AD 410|AD 43|AD 789|AD 1066", "தங்கள் பேரரசின் பிற பகுதிகளைப் பாதுகாக்க ரோமானியர்கள் AD 410இல் திரும்பிச் சென்றனர்."],
  29: ["ரோமானியர்கள் சென்ற பிறகு Britain மீது படையெடுத்த மக்கள் யார்?", "Jutes, Angles, Saxons|Normans, Franks|Picts, Scots மட்டும்|ஸ்பானியர், போர்த்துகீசியர்", "Anglo-Saxons — Jutes, Angles, Saxons — வட ஐரோப்பாவிலிருந்து வந்து Britainஇல் குடியேறினர்."],
  30: ["East Angliaஇல் உள்ள Sutton Hoo யாருடைய புதைவிடம்?", "ஓர் Anglo-Saxon மன்னரின்|ஒரு ரோமானியத் தளபதியின்|ஒரு வைக்கிங் தலைவரின்|ஒரு நார்மன் வீரரின்", "Sutton Hooஇல் உள்ள கப்பல் புதைவிடம் ஓர் Anglo-Saxon மன்னர் அல்லது பெரும் வீரருடையது என நம்பப்படுகிறது."],
  31: ["Anglo-Saxonsஐக் கிறித்தவ மதத்திற்கு மாற்றிய, முதல் Archbishop of Canterbury ஆன, ரோமிலிருந்து வந்த பணியை வழிநடத்தியவர் யார்?", "St Augustine|St Columba|St Patrick|St David", "St Augustine 597இல் வந்து முதல் Archbishop of Canterbury ஆனார். St Columba Ionaஇல் ஒரு மடத்தை நிறுவினார்."],
  32: ["வைக்கிங்குகள் Britain மீது முதன்முதலில் தாக்குதல் நடத்திய ஆண்டு எது?", "AD 789|AD 410|AD 1066|AD 1215", "வைக்கிங்குகள் AD 789இல் கடற்கரை நகரங்களைத் தாக்க முதலில் வந்து, பின்னர் Britainஇன் சில பகுதிகளில் குடியேறினர்."],
  33: ["வைக்கிங்குகளைத் தோற்கடித்து Anglo-Saxon அரசுகளை ஒன்றிணைத்த மன்னர் யார்?", "Alfred the Great|Harold|Cnut|Ethelred", "மன்னர் Alfred the Great வைக்கிங்குகளைத் தோற்கடித்தார், எனினும் அவர்கள் கிழக்கிலும் வடக்கிலும் Danelawஐக் கட்டுப்பாட்டில் வைத்திருந்தனர்."],
  34: ["ஸ்காட்டிஷ் அரசுகளை ஒன்றிணைத்து Scotlandஇன் முதல் மன்னரானவர் யார்?", "Kenneth MacAlpin|Robert the Bruce|William Wallace|Macbeth", "Kenneth MacAlpin Picts மற்றும் Scots மக்களை ஒரே அரசாக ஒன்றிணைத்தார்."],

  /* ---------- CHAPTER 3 (core, continued) ---------- */
  35: ["1066இல் நடந்த போர் எது?", "The Battle of Hastings|The Battle of Bosworth Field|The Battle of Bannockburn|The Battle of Agincourt", "1066இல் Hastings ஆற்றில் Normandy பிரபு William மன்னர் Haroldஐத் தோற்கடித்தார் — England மீதான கடைசி வெற்றிகரமான வெளிநாட்டுப் படையெடுப்பு."],
  36: ["Bayeux Tapestry என்றால் என்ன?", "Englandஇன் நார்மன் வெற்றியைக் காட்டும் ஒரு பின்னலாடை|நில உரிமைப் பதிவேடு|உரிமைகளுக்கான அரச சாசனம்|இடைக்கால Britainஇன் வரைபடம்", "Franceஇல் இன்றும் காட்சிக்கு வைக்கப்பட்டுள்ள Bayeux Tapestry, Battle of Hastings மற்றும் நார்மன் வெற்றியை நினைவுகூர்கிறது."],
  37: ["Domesday Book என்றால் என்ன?", "Englandஇன் நகரங்கள், கிராமங்கள், நில உடைமைகளின் கணக்கெடுப்பு|மதச் சட்ட நூல்|ஆங்கில மன்னர்களின் பட்டியல்|கவிதைத் தொகுப்பு", "England முழுவதும் யார் நிலமும் கால்நடையும் வைத்திருந்தனர் என்பதைப் பதிவு செய்ய 1086இல் William Domesday Bookஐ ஆணையிட்டார்."],
  38: ["Conwy, Caernarfon போன்ற கோட்டைகளைக் கட்டி Walesஐக் கைப்பற்றிய ஆங்கில மன்னர் யார்?", "Edward I|Henry V|William I|Richard III", "1284க்குள் Edward I Statute of Rhuddlan மூலம் Walesஐ இணைத்து, பெரும் கோட்டைகளின் வளையத்தைக் கட்டினார்."],
  39: ["1314இல் Robert the Bruce ஆங்கிலேயரைத் தோற்கடித்த போர் எது?", "Bannockburn|Culloden|Agincourt|Naseby", "1314இல் Robert the Bruce தலைமையில் Scots Bannockburnஇல் வெற்றி பெற்றனர், Scotland பல நூற்றாண்டுகள் சுதந்திரமாக இருந்தது."],
  40: ["1415இல் Battle of Agincourtஇல் வென்ற ஆங்கில மன்னர் யார்?", "Henry V|Henry VIII|Edward III|Richard II", "Franceக்கு எதிரான Hundred Years War காலத்தில் Henry Vஇன் Agincourt வெற்றி நிகழ்ந்தது."],
  41: ["Franceஉடனான Hundred Years War 1453இல் முடிந்தபோது England எந்த நகரத்தை வைத்திருந்தது?", "Calais|Paris|Rouen|Bordeaux", "Calais துறைமுகத்தைத் தவிர England தனது அனைத்து பிரெஞ்சுப் பகுதிகளையும் இழந்தது; Calaisஉம் 1558இல் இழக்கப்பட்டது."],
  42: ["1348இன் Black Deathஇல் Englandஇன் மக்கள்தொகையில் சுமார் எவ்வளவு பங்கு இறந்தது?", "மூன்றில் ஒரு பங்கு|பத்தில் ஒரு பங்கு|பாதி|முக்கால் பங்கு", "Black Death Englandஇன் மக்கள்தொகையில் சுமார் மூன்றில் ஒரு பங்கைக் கொன்றது, Scotland, Walesஐயும் பாதித்தது."],
  43: ["Magna Carta என்றால் என்ன?", "1215இல் ஒப்புக்கொள்ளப்பட்ட, மன்னரின் அதிகாரத்தை வரம்பிட்ட சாசனம்|முதல் ஆங்கில பைபிள்|Franceஉடனான ஒப்பந்தம்|நில உடைமைகளின் பதிவேடு", "1215இல் மன்னர் John Magna Cartaவை ('பெரும் சாசனம்') ஏற்க நிர்ப்பந்திக்கப்பட்டார், இதனால் மன்னரும் சட்டத்திற்கு உட்பட்டவர் என நிலைநாட்டப்பட்டது."],
  44: ["Wars of the Roses எந்த இரு குடும்பங்களுக்கு இடையே நடந்தது?", "Lancaster, York|Tudor, Stuart|Normandy, Anjou|Wessex, Mercia", "1455 முதல் 1485 வரை Lancaster (சிவப்பு ரோஜா) குடும்பம் York (வெள்ளை ரோஜா) குடும்பத்துடன் அரியணைக்காகப் போரிட்டது."],
  45: ["1485இல் Wars of the Rosesஐ முடித்த போர் எது?", "The Battle of Bosworth Field|The Battle of Hastings|The Battle of the Boyne|The Battle of Marston Moor", "Bosworth Fieldஇல் Richard III கொல்லப்பட்டார், Henry Tudor Henry VII ஆகி Tudor வம்சத்தை நிறுவினார்."],
  46: ["1476இல் Englandஇல் முதல் அச்சகத்தை நிறுவியவர் யார்?", "William Caxton|Geoffrey Chaucer|Thomas Cromwell|Robert Burns", "William Caxton Englandஇற்கு அச்சுத்தொழிலைக் கொண்டுவந்து, புத்தகங்களை மிகவும் பரவலாகக் கிடைக்கச் செய்தார்."],
  47: ["The Canterbury Tales எழுதியவர் யார்?", "Geoffrey Chaucer|William Shakespeare|John Milton|Robert Burns", "Chaucerஇன் Canterbury Tales, Canterbury செல்லும் யாத்திரிகர் குழு பற்றிய கவிதைத் தொகுப்பு."],
  48: ["Henry VIIIக்கு எத்தனை மனைவியர்?", "ஆறு|நான்கு|இரண்டு|எட்டு", "Catherine of Aragon, Anne Boleyn, Jane Seymour, Anne of Cleves, Catherine Howard, Catherine Parr — விவாகரத்து, தலைவெட்டு, இறப்பு, விவாகரத்து, தலைவெட்டு, தப்பிப்பிழைப்பு."],
  49: ["Henry VIII ஏன் ரோம் திருச்சபையிலிருந்து பிரிந்தார்?", "Catherine of Aragonஉடனான திருமணத்தை ரத்து செய்ய போப் மறுத்தார்|France மீது படையெடுக்க விரும்பினார்|வரிகளை உயர்த்த விரும்பினார்|யூத மதத்திற்கு மாறினார்", "மீண்டும் திருமணம் செய்ய Henry தன்னையே தலைவராகக் கொண்டு Church of Englandஐ நிறுவினார், இதுவே ஆங்கில சீர்திருத்தத்தின் தொடக்கம்."],
  50: ["புராட்டஸ்டன்ட்களை ஒடுக்கியதால் 'Bloody Mary' என அறியப்பட்ட அரசி யார்?", "Mary I|Mary Queen of Scots|Elizabeth I|Queen Anne", "Henry VIIIஇன் மகள் Mary I ஒரு பக்திமிக்க கத்தோலிக்கர், பல புராட்டஸ்டன்ட்களைத் தூக்கிலிட்டார்."],
  51: ["Spanish Armada தோற்கடிக்கப்பட்ட ஆண்டு எது?", "1588|1485|1666|1215", "England மீது படையெடுக்க Philip II அனுப்பிய Spanish Armadaவை ஆங்கிலக் கப்பற்படை 1588இல் தோற்கடித்தது."],
  52: ["William Shakespeare எங்கே பிறந்தார்?", "Stratford-upon-Avon|London|Canterbury|Edinburgh", "Shakespeare Stratford-upon-Avonஇல் பிறந்தார், பின்னர் Londonஇல் Globe அரங்கில் பணியாற்றினார்."],
  53: ["1603இல் Scotland மன்னராகவும் இருந்தபடி England, Wales, Ireland மன்னரானவர் யார்?", "Scotlandஇன் James VI (Englandஇன் James I)|Charles I|Henry VII|William III", "1603இன் Union of the Crowns England, Scotlandஐ ஒரே மன்னரின் கீழ் கொண்டுவந்தது, எனினும் அவை தனி நாடுகளாகவே இருந்தன."],
  54: ["English Civil War காலத்தில் மன்னரின் ஆதரவாளர்கள் எவ்வாறு அறியப்பட்டனர்?", "Cavaliers|Roundheads|Jacobites|Whigs", "1642 முதல் அரசவாத Cavaliers, நாடாளுமன்றவாத Roundheadsஉடன் போரிட்டனர்."],
  55: ["Charles I தூக்கிலிடப்பட்ட ஆண்டு எது?", "1649|1660|1666|1688", "1649இல் Charles I தூக்கிலிடப்பட்டார், England Commonwealth எனும் குடியரசானது."],
  56: ["Oliver Cromwell எந்தப் பட்டத்தை ஏற்றார்?", "Lord Protector|Englandஇன் மன்னர்|Lord Chancellor|Prime Minister", "Cromwell 1658இல் இறக்கும் வரை Lord Protectorஆக ஆட்சி செய்தார்; அவரது மகன் Richard ஆட்சி செய்ய இயலவில்லை."],
  57: ["Charles II தலைமையில் முடியாட்சி திரும்பிய ஆண்டு எது?", "1660|1649|1688|1707", "1660இல் நாடாளுமன்றம் Charles IIஐத் திரும்ப அழைத்தது, இது Restoration என அறியப்படுகிறது."],
  58: ["1660களில் Londonஐத் தாக்கிய இரண்டு பேரிடர்கள் எவை? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "The Great Plague|The Great Fire|The Black Death|The Spanish Armada", "Great Plague 1665இலும் Great Fire of London 1666இலும் நிகழ்ந்தன."],
  59: ["1688இன் Glorious Revolution எந்த ஆட்சியாளரை அரியணைக்குக் கொண்டுவந்தது?", "William of Orange|Charles II|George I|Oliver Cromwell", "William of Orangeஉம் அவரது மனைவி Mary, James IIஇன் மகளும், Englandஇல் போரின்றி அரியணை ஏற்றனர்."],
  60: ["1689இன் Bill of Rights எதை நிலைநாட்டியது?", "மன்னரின் அதிகாரத்திற்கான வரம்புகளும் வழக்கமான நாடாளுமன்றத்தின் தேவையும்|அனைத்துப் பெரியவர்களுக்கும் வாக்குரிமை|வரியிலிருந்து விடுதலை|The Church of England", "Bill of Rights, மன்னருக்கு நாடாளுமன்றத்தின் ஒப்புதல் தேவை என்பதை உறுதி செய்து, வழக்கமான நாடாளுமன்றங்களைக் கோரியது."],
  61: ["1707இன் Act of Union எந்த அரசை உருவாக்கியது?", "The Kingdom of Great Britain|The United Kingdom of Great Britain and Ireland|The Commonwealth|England, Wales அரசு", "Scotland, England ஒரே நாடாளுமன்றத்தின் கீழ் இணைந்து Kingdom of Great Britain ஆயின."],
  62: ["Great Britainஇன் முதல் Prime Minister எனப் பொதுவாகக் கருதப்படுபவர் யார்?", "Sir Robert Walpole|William Pitt|Winston Churchill|The Duke of Wellington", "Sir Robert Walpole 1721 முதல் 1742 வரை பதவி வகித்தார், முதல் Prime Ministerஆகக் கருதப்படுகிறார்."],
  63: ["1746இல் Jacobites தோற்கடிக்கப்பட்ட போர் எது?", "Culloden|Bannockburn|Naseby|Bosworth Field", "Bonnie Prince Charlieஇன் படைகள் Cullodenஇல் நசுக்கப்பட்டன; அவர் ஐரோப்பாவுக்குத் தப்பிச் சென்றார்."],
  64: ["Adam Smith, David Hume எதன் முன்னணி ஆளுமைகள்?", "The Scottish Enlightenment|தொழிற்புரட்சி|சீர்திருத்தம்|The Restoration", "அறிவொளிக் காலம் அரசியல், தத்துவம், அறிவியலில் புதிய கருத்துகளை உருவாக்கியது, பல ஸ்காட்டிஷ் சிந்தனையாளர்களிடமிருந்து."],
  65: ["தொழிற்புரட்சிக்கு ஆற்றல் அளித்த நீராவி இயந்திரத்தை மேம்படுத்தியவர் யார்?", "James Watt|Richard Arkwright|Isaac Newton|George Stephenson", "ஸ்காட்லாந்தைச் சேர்ந்த James Watt, தொழிற்சாலைகளிலும் சுரங்கங்களிலும் இயந்திரங்களை இயக்கும் வகையில் நீராவி இயந்திரத்தை மேம்படுத்தினார்."],
  66: ["பிரிட்டிஷ் கப்பல்களில் அடிமை வணிகத்தை நாடாளுமன்றம் ஒழித்த ஆண்டு எது?", "1807|1833|1776|1215", "வணிகம் 1807இல் ஒழிக்கப்பட்டது; 1833இன் Emancipation Act British Empire முழுவதும் அடிமைத்தனத்தை ஒழித்தது."],
  67: ["அடிமை வணிகத்திற்கு எதிராக வெற்றிகரமாகப் பிரச்சாரம் செய்த சாரி யார்?", "William Wilberforce|Robert Walpole|William Gladstone|Isambard Kingdom Brunel", "இவாஞ்சலிக்கல் கிறித்தவரான William Wilberforce அடிமைத்தனத்திற்கு எதிரான நாடாளுமன்றப் பிரச்சாரத்தை வழிநடத்தினார்."],
  68: ["Admiral Nelson 1805இல் எந்தக் கடற்போரில் இறந்தார்?", "Trafalgar|Jutland|The Nile|Dunkirk", "Nelson Trafalgarஇல் கொல்லப்பட்டார்; அவரது முதன்மைக் கப்பல் HMS Victory Portsmouthஇல் பாதுகாக்கப்படுகிறது, அவரது தூண் Trafalgar Squareஇல் உள்ளது."],

  /* ---------- CHAPTER 3/4 (core) ---------- */
  69: ["1815இல் Waterlooஇல் Napoleonஐத் தோற்கடித்த பிரிட்டிஷ் படைகளுக்குத் தலைமை தாங்கியவர் யார்?", "The Duke of Wellington|Admiral Nelson|Sir Robert Walpole|Oliver Cromwell", "பின்னர் Prime Minister ஆன Duke of Wellington, Iron Duke என அறியப்பட்டார்."],
  70: ["அரசி Victoria எத்தனை காலம் ஆட்சி செய்தார்?", "1837 முதல் 1901 வரை|1801 முதல் 1837 வரை|1901 முதல் 1936 வரை|1760 முதல் 1820 வரை", "Victoria 1837இல் 18 வயதில் அரியணை ஏறி 64 ஆண்டுகள் ஆட்சி செய்தார், இது பெரும் தொழில் மற்றும் பேரரசு விரிவாக்கக் காலம்."],
  71: ["Florence Nightingale எந்தப் போரில் ஆற்றிய பணிக்காகப் புகழ்பெற்றவர்?", "The Crimean War|The First World War|The Boer War|The Hundred Years War", "Crimean War காலத்தில் Scutariஇல் செவிலியராகப் பணியாற்றி, பின்னர் Londonஇல் St Thomas' Hospitalஇல் செவிலியர் பள்ளியை நிறுவினார்."],
  72: ["1889இல் Women's Franchise Leagueஐ நிறுவி, பின்னர் suffragettesஐ வழிநடத்தியவர் யார்?", "Emmeline Pankhurst|Florence Nightingale|Mary Seacole|Elizabeth Fry", "Emmeline Pankhurst பெண்களுக்கு வாக்குரிமை கோரிப் பிரச்சாரம் செய்தார்; இயக்கம் மேலும் மேலும் தீவிரமான உத்திகளைக் கையாண்டது."],
  73: ["ஆண்களுக்கு நிகரான வயதில் பெண்கள் வாக்குரிமை பெற்ற ஆண்டு எது?", "1928|1918|1945|1969", "சொத்துள்ள 30 வயதுக்கு மேற்பட்ட பெண்கள் 1918இல் வாக்குரிமை பெற்றனர்; 1928இல் ஆண்களைப் போலவே 21 வயதில் வாக்களிக்க முடிந்தது."],
  74: ["First World Warஐத் தூண்டிய நிகழ்வு எது?", "Archduke Franz Ferdinand படுகொலை|Poland மீதான படையெடுப்பு|Lusitania கப்பல் மூழ்கடிப்பு|ரஷ்யப் புரட்சி", "1914இல் Sarajevoஇல் ஆஸ்திரிய-ஹங்கேரிய Archduke படுகொலை செய்யப்பட்டார்."],
  75: ["1916இல் Battle of the Sommeஇன் முதல் நாளில் பிரிட்டிஷ் இழப்புகள் சுமார் எத்தனை?", "60,000|6,000|600|600,000", "Somme First World Warஇன் மிகக் கொடூரமான போர்களில் ஒன்று."],
  76: ["First World War எந்தத் தேதியில் காலை 11 மணிக்கு முடிந்தது?", "11 November 1918|8 May 1945|1 September 1939|6 June 1944", "பதினொன்றாம் மாதத்தின் பதினொன்றாம் நாளின் பதினொன்றாம் மணியில் போர்நிறுத்தம் அமலுக்கு வந்தது."],
  77: ["1922இல் Ireland பிரிக்கப்பட்டது. தெற்கில் என்ன உருவானது?", "The Irish Free State|The Republic of Ulster|The Kingdom of Ireland|The Irish Commonwealth", "வடக்கில் ஆறு கவுண்டிகள் யுகேயில் தங்கின, நாடு United Kingdom of Great Britain and Northern Ireland ஆனது."],
  78: ["1940இல் Prime Minister ஆகி Second World Warஇன் பெரும்பகுதியில் Britainஐ வழிநடத்தியவர் யார்?", "Winston Churchill|Neville Chamberlain|Clement Attlee|David Lloyd George", "Churchill 1940இல் Prime Minister ஆனார், போர்க்கால உரைகளுக்காகப் புகழ்பெற்றார்."],
  79: ["1940இல் Dunkirkஇல் என்ன நடந்தது?", "3,00,000க்கும் மேற்பட்ட வீரர்கள் Franceஇலிருந்து வெளியேற்றப்பட்டனர், பலர் சிறு படகுகளில்|ஒரு பெரும் கடற்போர் வெல்லப்பட்டது|பிரிட்டிஷ் படைகள் Normandyஇல் இறங்கின|RAF Luftwaffeஐத் தோற்கடித்தது", "நூற்றுக்கணக்கான குடிமக்களின் படகுகள் Dunkirk கடற்கரையிலிருந்து பிரிட்டிஷ், பிரெஞ்சு வீரர்களை மீட்க உதவின."],
  80: ["1940இன் Battle of Britain முக்கியமாக எந்தப் படையால் நடத்தப்பட்டது?", "The Royal Air Force|The Royal Navy|இராணுவம்|The Home Guard", "RAFஇன் Spitfire, Hurricane விமானங்கள் ஜெர்மன் விமானப்படையைத் தோற்கடித்து, படையெடுப்பைத் தடுத்தன."],
  81: ["D-Dayஅன்று நேச நாட்டுப் படைகள் Normandyஇல் எந்தத் தேதியில் இறங்கின?", "6 June 1944|8 May 1945|3 September 1939|11 November 1918", "D-Day இறங்குதல்கள் நாஜி ஆக்கிரமிப்பிலிருந்து மேற்கு ஐரோப்பாவின் விடுதலையைத் தொடங்கின."],
  82: ["ஐரோப்பாவில் வெற்றியைக் குறிக்கும் VE Day எந்தத் தேதியில் கொண்டாடப்படுகிறது?", "8 May 1945|6 June 1944|11 November 1918|1 January 1945", "ஐரோப்பாவில் போர் 8 May 1945இல் முடிந்தது; Japan August 1945இல் சரணடைந்தது."],
  83: ["1928இல் penicillinஐக் கண்டுபிடித்தவர் யார்?", "Sir Alexander Fleming|Sir Frank Whittle|Alan Turing|Sir Isaac Newton", "ஸ்காட்டிஷ் அறிவியலாளர் Alexander Fleming penicillinஐக் கண்டுபிடித்தார், பின்னர் அது நுண்ணுயிர்க்கொல்லியாக உருவாக்கப்பட்டது."],
  84: ["நவீன நலன்புரி அரசுக்கு வழிவகுத்த அறிக்கையை எழுதியவர் யார்?", "William Beveridge|Clement Attlee|Aneurin Bevan|Winston Churchill", "1942இன் Beveridge Report 'தொட்டில் முதல் கல்லறை வரை' சமூகப் பாதுகாப்புத் திட்டத்தை வகுத்தது."],
  85: ["1948இல் National Health Service நிறுவுவதை வழிநடத்தியவர் யார்?", "Aneurin Bevan|William Beveridge|Winston Churchill|Margaret Thatcher", "சுகாதார அமைச்சர் Aneurin Bevan NHSஐத் தொடங்கினார், பயன்படுத்தும் இடத்தில் அனைவருக்கும் இலவச சுகாதாரப் பராமரிப்பு வழங்கப்பட்டது."],
  86: ["1948இல் வந்த Empire Windrush கப்பல் எங்கிருந்து தொழிலாளர்களைக் கொண்டுவந்தது?", "The West Indies|India|Ireland|Poland", "போருக்குப் பிந்தைய தொழிலாளர் பற்றாக்குறையால் Britain West Indiesஇலிருந்தும் பின்னர் India, Pakistanஇலிருந்தும் தொழிலாளர்களை அழைத்தது."],
  87: ["India, Pakistan, Ceylon (Sri Lanka) சுதந்திரம் பெற்ற ஆண்டு எது?", "1947|1922|1966|1973", "இந்நாடுகளின் சுதந்திரம் British Empireஇன் விரைவான காலனியகற்றலைத் தொடங்கியது."],
  88: ["யுகே European Economic Communityஇல் சேர்ந்த ஆண்டு எது?", "1973|1957|1969|1992", "யுகே 1973இல் EECஇல் சேர்ந்து, 31 January 2020இல் European Unionஐ விட்டு வெளியேறியது."],
  89: ["யுகேயின் முதல் பெண் Prime Minister யார்?", "Margaret Thatcher|Theresa May|Emmeline Pankhurst|Barbara Castle", "Margaret Thatcher 1979 முதல் 1990 வரை Prime Ministerஆக இருந்தார், 20ஆம் நூற்றாண்டின் நீண்டகாலப் பதவி வகித்த PM."],
  90: ["1998இல் Northern Irelandஇல் கையெழுத்தானது எது?", "The Belfast (Good Friday) Agreement|The Act of Union|The Treaty of Rome|The Bill of Rights", "இந்த ஒப்பந்தம் Stormontஇல் அதிகாரப் பகிர்வு Northern Ireland Assemblyக்கு வழிவகுத்தது."],
  91: ["Scottish Parliament, Welsh Assembly முதன்முதலில் கூடிய ஆண்டு எது?", "1999|1979|1989|2007", "1997இன் பொதுவாக்கெடுப்புகள் devolved அமைப்புகளுக்கு வழிவகுத்தன, அவை 1999இல் முதலில் கூடின."],
  92: ["Alan Turing எதற்காக அதிகம் அறியப்படுகிறார்?", "ஜெர்மன் குறியீடுகளை உடைக்க உதவியதற்கும் கணினி அறிவியலின் முன்னோடியாக இருந்ததற்கும்|ஜெட் இயந்திரத்தைக் கண்டுபிடித்ததற்கு|penicillinஐக் கண்டுபிடித்ததற்கு|ரேடாரை உருவாக்கியதற்கு", "Bletchley Parkஇல் Turingஇன் பணி Second World Warஐக் குறைக்க உதவியது, அவர் நவீன கணினியியலின் தந்தையருள் ஒருவர்."],
  93: ["ஜெட் இயந்திரத்தைக் கண்டுபிடித்தவர் யார்?", "Sir Frank Whittle|Sir Christopher Cockerell|John Logie Baird|Sir Bernard Lovell", "RAF பொறியாளர் Sir Frank Whittle 1930களில் டர்போ ஜெட் இயந்திரத்திற்கு காப்புரிமை பெற்றார்."],
  94: ["1690இல் Irelandஇல் William III James IIஐத் தோற்கடித்த போர் எது?", "The Battle of the Boyne|The Battle of Culloden|The Battle of Naseby|The Battle of Bannockburn", "Battle of the Boyne இன்றும் Northern Irelandஇல் சிலரால் நினைவுகூரப்படுகிறது."],
  95: ["1679இன் Habeas Corpus Act எதற்கு உத்தரவாதம் அளித்தது?", "விசாரணையின்றி யாரையும் சட்டவிரோதமாகத் தடுத்து வைக்க முடியாது|வாக்குரிமை|பத்திரிகைச் சுதந்திரம்|இலவசக் கல்வி", "Habeas corpus சட்டவிரோதச் சிறைவாசத்திற்கு எதிரான முக்கியப் பாதுகாப்பு."],
  96: ["Highland Clearances என்றால் என்ன?", "ஆட்டு வளர்ப்புக்கு இடமளிக்க நிலவுடைமையாளர்கள் குத்தகைதாரர்களை வெளியேற்றியது|ஸ்காட்டிஷ் சதுப்பு நிலங்களை வடித்தது|காடு வளர்ப்புத் திட்டம்|ரோமானிய இடிபாடுகளை அகற்றியது", "பல ஸ்காட்டிஷ் மக்கள் Highlandsஇல் தங்கள் வீடுகளிலிருந்து வெளியேற்றப்பட்டு America மற்றும் பிற இடங்களுக்குக் குடிபெயர்ந்தனர்."],
  97: ["United Kingdom European Unionஐ விட்டு வெளியேறிய ஆண்டு எது?", "2020|2016|2019|2021", "2016இல் பொதுவாக்கெடுப்பு நடத்தப்பட்டது, யுகே 31 January 2020இல் முறையாக EUஐ விட்டு வெளியேறியது."],
  98: ["அரசி Elizabeth II அரியணை ஏறிய ஆண்டு எது?", "1952|1936|1945|1960", "Elizabeth II 1952 முதல் 2022 வரை ஆட்சி செய்தார், நீண்டகாலம் ஆட்சி செய்த பிரிட்டிஷ் மன்னர்."],
  99: ["யுகேயின் எந்த நாட்டில் மிக அதிக மக்கள்தொகை உள்ளது?", "England|Scotland|Wales|Northern Ireland", "யுகேயின் மக்கள்தொகையில் சுமார் 84% England இல் உள்ளது."],
  100: ["யுகேயில் மக்கள்தொகைக் கணக்கெடுப்பு எத்தனை ஆண்டுகளுக்கு ஒருமுறை நடத்தப்படுகிறது?", "ஒவ்வொரு 10 ஆண்டுகளுக்கும்|ஒவ்வொரு 5 ஆண்டுகளுக்கும்|ஒவ்வொரு ஆண்டும்|ஒவ்வொரு 20 ஆண்டுகளுக்கும்", "முழு மக்கள்தொகைக் கணக்கெடுப்பு பத்தாண்டுகளுக்கு ஒருமுறை எடுக்கப்படுகிறது."],
  101: ["St Georgeஇன் சிலுவைக் கொடி எது?", "வெள்ளைப் பின்னணியில் சிவப்புச் சிலுவை|நீலப் பின்னணியில் வெள்ளை மூலைவிட்டச் சிலுவை|வெள்ளைப் பின்னணியில் சிவப்பு மூலைவிட்டச் சிலுவை|கருப்புப் பின்னணியில் மஞ்சள் சிலுவை", "St George Englandஇன் காவல் புனிதர்; அவரது கொடி வெள்ளையில் சிவப்புச் சிலுவை."],
  102: ["St Andrewஇன் கொடி எப்படி இருக்கும்?", "நீலப் பின்னணியில் வெள்ளை மூலைவிட்டச் சிலுவை|வெள்ளையில் சிவப்புச் சிலுவை|பச்சை-வெள்ளையில் சிவப்பு டிராகன்|கருப்பில் மஞ்சள் சிலுவை", "St Andrew Scotlandஇன் காவல் புனிதர்; saltire நீலத்தில் வெள்ளை."],

  /* ---------- CHAPTER 4 (core) ---------- */
  103: ["எந்தக் காவல் புனிதரின் கொடி Union Flagஇல் இடம்பெறவில்லை?", "St David|St George|St Andrew|St Patrick", "Union Flag St George, St Andrew, St Patrick ஆகியோரின் சிலுவைகளை இணைக்கிறது. Wales பிரதிநிதித்துவப்படுத்தப்படவில்லை."],
  104: ["St David's Day எப்போது?", "1 March|17 March|23 April|30 November", "St David (Wales) 1 March, St Patrick (NI) 17 March, St George (England) 23 April, St Andrew (Scotland) 30 November."],
  105: ["St Andrew's Day எப்போது?", "30 November|23 April|17 March|1 March", "St Andrew's Day, 30 November, Scotlandஇல் ஒரு தேசிய நாள்."],
  106: ["5 Novemberஇன் Bonfire Night எதை நினைவுகூர்கிறது?", "1605இல் நாடாளுமன்றத்தைத் தகர்க்கத் தோல்வியுற்ற சதி|First World Warஇன் முடிவு|The Great Fire of London|Spanish Armadaஇன் தோல்வி", "Guy Fawkes உட்பட சதிகாரர்கள் நாடாளுமன்றத்தைத் தகர்த்து புராட்டஸ்டன்ட் மன்னரைக் கொல்ல முயன்றனர்."],
  107: ["11 Novemberஇல் Remembrance Dayஅன்று மக்கள் எதை அணிகிறார்கள்?", "பாப்பி மலர்|ரோஜா|திஸில்|டேஃபோடில்", "இரு உலகப் போர்களிலும் பிற்கால மோதல்களிலும் இறந்தவர்களை பாப்பி மலர்கள் நினைவுகூர்கின்றன."],
  108: ["Hogmanay எதன் கொண்டாட்டம்?", "Scotlandஇல் புத்தாண்டு முன்தினம்|Walesஇல் நடுக்கோடை|Northern Irelandஇல் அறுவடை|Englandஇல் May Day", "Hogmanay ஒரு முக்கிய ஸ்காட்டிஷ் கொண்டாட்டம்; Scotlandஇல் 2 Januaryஉம் பொது விடுமுறை."],
  109: ["25 Januaryஇல் Burns Nightஅன்று யாருடைய வாழ்க்கை கொண்டாடப்படுகிறது?", "Robert Burns|Robert the Bruce|Rabbie MacAlpin|Robert Louis Stevenson", "Burns Night விருந்துகள் Auld Lang Syne எழுதிய ஸ்காட்டிஷ் கவிஞர் Robert Burnsஐக் கொண்டாடுகின்றன."],
  110: ["யுகே முழுவதும் பொது விடுமுறை (bank holidays) எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "Christmas Day|Good Friday|Halloween|Valentine's Day", "Christmas Day, Boxing Day, New Year's Day, Good Friday, Easter Monday மற்றும் பிற பொது விடுமுறைகள் bank holidays."],
  111: ["The Ashes என்பது England மற்றும் எந்த நாட்டிற்கும் இடையிலான கிரிக்கெட் போட்டி?", "Australia|India|South Africa|New Zealand", "England, Australia இடையிலான Ashes தொடர் 1882 முதல் விளையாடப்படுகிறது."],
  112: ["Wimbledon டென்னிஸ் சாம்பியன்ஷிப் எங்கே நடத்தப்படுகிறது?", "London|Manchester|Edinburgh|Birmingham", "Wimbledonஇல் நடக்கும் All England Lawn Tennis Championships உலகின் மிகப் பழமையான டென்னிஸ் போட்டி."],
  113: ["Grand National குதிரைப் பந்தயம் எந்த மைதானத்தில் நடத்தப்படுகிறது?", "Aintree|Epsom|Ascot|Ayr", "Grand National Liverpool அருகே Aintreeஇல் நடத்தப்படுகிறது; Derby Epsomஇல்."],
  114: ["எந்த ஸ்காட்டிஷ் நகரம் கோல்ஃபின் தாயகமாக அறியப்படுகிறது?", "St Andrews|Aberdeen|Stirling|Perth", "நவீன விளையாட்டு Scotlandஇல் உருவானது, St Andrews அதன் வரலாற்றுத் தாயகம்."],
  115: ["Sir Roger Bannister எதைச் செய்த முதல் மனிதர்?", "நான்கு நிமிடங்களுக்குள் ஒரு மைல் ஓடியது|ஐந்து ஒலிம்பிக் தங்கப் பதக்கங்கள் வென்றது|தனியாக உலகைச் சுற்றிப் பயணித்தது|Tour de France வென்றது", "Bannister 1954இல் நான்கு நிமிட மைல் தடையை உடைத்தார்."],
  116: ["Sir Steve Redgrave எந்த விளையாட்டில் ஐந்து தங்கப் பதக்கங்கள் வென்றார்?", "படகுப் போட்டி (rowing)|சைக்கிளிங்|தடகளம்|படகோட்டம்", "Redgrave தொடர்ச்சியாக ஐந்து ஒலிம்பிக் போட்டிகளில் தங்கம் வென்றார்."],
  117: ["1966 உலகக் கோப்பையை வென்ற England கால்பந்து அணிக்குத் தலைமை தாங்கியவர் யார்?", "Bobby Moore|Bobby Charlton|Ian Botham|Jackie Stewart", "Wembleyஇல் England West Germanyஐத் தோற்கடித்த பின் Bobby Moore உலகக் கோப்பையை உயர்த்தினார்."],
  118: ["London எத்தனை முறை ஒலிம்பிக் போட்டிகளை நடத்தியுள்ளது?", "மூன்று முறை|ஒரு முறை|இரு முறை|நான்கு முறை", "London 1908, 1948, 2012ஆம் ஆண்டுகளில் போட்டிகளை நடத்தியது."],
  119: ["The Planets இசையமைத்தவர் யார்?", "Gustav Holst|Edward Elgar|Benjamin Britten|Henry Purcell", "Gustav Holstஇன் The Planets இசைத்தொகுப்பு 1918இல் முதன்முதலில் அரங்கேறியது."],
  120: ["BBC Proms இசை நிகழ்ச்சிகள் எங்கே நடத்தப்படுகின்றன?", "The Royal Albert Hall|The Globe Theatre|The National Gallery|Wembley Stadium", "Proms என்பது எட்டு வார கோடைக்கால செவ்வியல் இசைப் பருவம், Last Night of the Promsஉடன் நிறைவடைகிறது."],
  121: ["The Hay Wain ஓவியத்தை வரைந்த கலைஞர் யார்?", "John Constable|J M W Turner|David Hockney|Thomas Gainsborough", "Constable ஆங்கிலக் கிராமப்புற நிலக்காட்சி ஓவியங்களுக்காகப் புகழ்பெற்றவர்."],
  122: ["Tate Britainஇல் சமகாலக் கலைக்காக வழங்கப்படும் பரிசு எது?", "The Turner Prize|The Booker Prize|The Mercury Prize|The Laurence Olivier Award", "J M W Turner பெயரிடப்பட்ட Turner Prize சமகாலப் பிரிட்டிஷ் கலையைக் கொண்டாடுகிறது."],
  123: ["St Paul's Cathedralஐ வடிவமைத்தவர் யார்?", "Sir Christopher Wren|Inigo Jones|Robert Adam|Sir Norman Foster", "1666இன் Great Fire of Londonக்குப் பிறகு Wren St Paul'sஐ மீண்டும் கட்டினார்."],
  124: ["'Capability' Brown எதை வடிவமைத்ததற்காகப் புகழ்பெற்றவர்?", "நிலக்காட்சித் தோட்டங்களும் பூங்காக்களும்|பேராலயங்கள்|நீராவி இயந்திரங்கள்|மரச்சாமான்கள்", "Lancelot 'Capability' Brown கிராமப்புற மாளிகைகளைச் சுற்றி இயற்கையாகத் தோன்றும் பரந்த தோட்டங்களை வடிவமைத்தார்."],
  125: ["Commonwealth அல்லது Irelandஐச் சேர்ந்த எழுத்தாளரின் சிறந்த நாவலுக்கு ஒவ்வொரு ஆண்டும் வழங்கப்படும் பரிசு எது?", "The Booker Prize|The Turner Prize|The Mercury Prize|The BAFTA", "Man Booker Prize for Fiction 1968 முதல் வழங்கப்பட்டு வருகிறது."],
  126: ["Pride and Prejudice எழுதியவர் யார்?", "Jane Austen|Charlotte Bronte|George Eliot|Mary Shelley", "Jane Austenஇன் நாவல்கள் 19ஆம் நூற்றாண்டின் தொடக்க Englandஇல் திருமணத்தையும் சமூக வர்க்கத்தையும் ஆராய்கின்றன."],
  127: ["Poets' Corner எங்கே உள்ளது?", "Westminster Abbey|St Paul's Cathedral|The Tower of London|Canterbury Cathedral", "பல புகழ்பெற்ற கவிஞர்கள் Westminster Abbeyஇல் உள்ள Poets' Cornerஇல் அடக்கம் செய்யப்பட்டுள்ளனர் அல்லது நினைவுகூரப்படுகின்றனர்."],
  128: ["World Wide Webஐக் கண்டுபிடித்தவர் யார்?", "Sir Tim Berners-Lee|Alan Turing|John Logie Baird|Sir Clive Sinclair", "பிரிட்டிஷ் அறிவியலாளர் Berners-Lee 1989-1990இல் World Wide Webஐக் கண்டுபிடித்தார்."],
  129: ["John Logie Baird எதன் முன்னோடியாக அறியப்படுகிறார்?", "தொலைக்காட்சி|தொலைபேசி|ரேடார்|hovercraft", "Baird 1926இல் முதல் தொலைக்காட்சி ஒளிபரப்பையும் 1928இல் முதல் அட்லாண்டிக் கடந்த TV ஒளிபரப்பையும் செய்தார்."],
  130: ["1996இல் குளோன் செய்யப்பட்ட Dolly ஆடு, எதிலிருந்து குளோன் செய்யப்பட்ட முதல் பாலூட்டி?", "ஒரு முதிர்ந்த செல்|ஒரு கருவுயிரி|ஒரு தாவரச் செல்|உறைந்த முட்டை", "Sir Ian Wilmut, Keith Campbell ஆகியோர் Edinburghஇல் உள்ள Roslin Instituteஇல் Dollyஐக் குளோன் செய்தனர்."],
  131: ["Northern Irelandஇல் Finn McCool எனும் அரக்கனின் புராணத்துடன் தொடர்புடைய அமைப்பு எது?", "The Giant's Causeway|The Eden Project|Snowdonia|Loch Lomond", "The Giant's Causeway Northern Irelandஇன் வடகிழக்குக் கடற்கரையில் உள்ள இயற்கைப் பாறை அமைப்பு."],
  132: ["யுகேயின் மிக உயரமான மலை எது?", "Ben Nevis|Snowdon|Scafell Pike|Slieve Donard", "Scotlandஇல் உள்ள Ben Nevis யுகேயின் மிக உயரமான மலை; Snowdon Walesஇன் உயரமான மலை."],
  133: ["Crown Jewels எங்கே வைக்கப்பட்டுள்ளன?", "The Tower of London|Buckingham Palace|Windsor Castle|Edinburgh Castle", "Tower of Londonஐ Beefeaters என அறியப்படும் Yeoman Warders காவல் காக்கின்றனர்."],
  134: ["யுகேயின் நாணயம் எது?", "pound sterling|யூரோ|டாலர்|கினி", "pound sterling (£) 100 penceஆகப் பிரிக்கப்படுகிறது."],
  135: ["Englandஇல் அரசு அங்கீகரித்த திருச்சபை எது?", "The Church of England|The Church of Scotland|ரோமன் கத்தோலிக்க திருச்சபை|மெதடிஸ்ட் திருச்சபை", "Church of England ஆங்கிலிக்கன்; மன்னர் அதன் தலைவர், Archbishop of Canterbury அதன் ஆன்மிகத் தலைவர்."],
  136: ["Scotlandஇன் தேசியத் திருச்சபை எது?", "The Church of Scotland, ஒரு பிரெஸ்பிடீரியன் திருச்சபை|The Church of England|ரோமன் கத்தோலிக்க திருச்சபை|தேசியத் திருச்சபை எதுவும் இல்லை", "Church of Scotland அதன் General Assembly மூலம் நிர்வகிக்கப்படுகிறது, Moderator தலைமை வகிக்கிறார்."],

  /* ---------- CHAPTER 5 (core) ---------- */
  137: ["யுகேயில் pubஇல் சட்டப்படி மது வாங்கக்கூடிய வயது என்ன?", "18|16|21|17", "மது வாங்க 18 வயது இருக்க வேண்டும். சில சூழல்களில் 18க்குக் கீழ் உள்ளவர்கள் பெரியவருடன் pubக்குள் நுழையலாம், ஆனால் பொதுவாக மது அருந்த முடியாது."],
  138: ["ஆங்கிலம் தவிர யுகேயின் சில பகுதிகளில் பேசப்படும் இரு மொழிகள் எவை? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "Welsh|Gaelic|லத்தீன்|Cornish Norse", "Welsh Walesஇல் பரவலாகப் பேசப்படுகிறது; Gaelic Scotland, Northern Irelandஇன் சில பகுதிகளில் பேசப்படுகிறது."],
  139: ["யுகேயில் எத்தகைய ஆட்சி முறை உள்ளது?", "நாடாளுமன்ற ஜனநாயகத்துடன் கூடிய அரசியலமைப்பு முடியாட்சி|முழுமையான முடியாட்சி|கூட்டாட்சிக் குடியரசு|ஒரு கட்சி ஆட்சி", "மன்னர் அரசுத் தலைவர், ஆனால் தேர்ந்தெடுக்கப்பட்ட அரசே நாட்டை நடத்துகிறது."],
  140: ["House of Commonsஇல் எத்தனை நாடாளுமன்ற உறுப்பினர்கள் (MPs) உள்ளனர்?", "650|600|129|450", "ஒவ்வொரு MPஉம் ஒரு தொகுதியைப் பிரதிநிதித்துவப்படுத்துகிறார், மொத்தம் 650 பேர்."],
  141: ["House of Commonsஇல் விவாதங்களுக்குத் தலைமை தாங்குபவர் யார்?", "The Speaker|The Prime Minister|The Lord Chancellor|மன்னர்", "Speaker என்பவர் மற்ற MPsஆல் இரகசிய வாக்கெடுப்பில் தேர்ந்தெடுக்கப்படும் MP, அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டும்."],
  142: ["House of Lords உறுப்பினர்கள் பொதுவாக எவ்வாறு அறியப்படுகிறார்கள்?", "Peers|MPs|கவுன்சிலர்கள்|அமைச்சர்கள்", "இன்று பெரும்பாலானோர் life peers, வாழ்நாள் முழுவதும் நியமிக்கப்பட்டவர்கள்; Lordsஇல் ஆயர்களும் சில hereditary peersஉம் உள்ளனர்."],
  143: ["பொதுத் தேர்தல் குறைந்தபட்சம் எத்தனை காலத்திற்கு ஒருமுறை நடத்தப்பட வேண்டும்?", "குறைந்தது ஐந்தாண்டுகளுக்கு ஒருமுறை|குறைந்தது மூன்றாண்டுகளுக்கு ஒருமுறை|குறைந்தது ஏழாண்டுகளுக்கு ஒருமுறை|இரண்டாண்டுகளுக்கு ஒருமுறை", "பொதுத் தேர்தல் குறைந்தது ஐந்தாண்டுகளுக்கு ஒருமுறை நடத்தப்பட வேண்டும்."],
  144: ["யுகே பொதுத் தேர்தல்களுக்குப் பயன்படுத்தப்படும் தேர்தல் முறையின் பெயர் என்ன?", "First past the post|விகிதாசாரப் பிரதிநிதித்துவம்|ஒற்றை மாற்றத்தக்க வாக்கு|மாற்று வாக்கு", "ஒவ்வொரு தொகுதியிலும் அதிக வாக்குகள் பெறும் வேட்பாளர் MP ஆகிறார்."],
  145: ["Prime Ministerஇன் அதிகாரப்பூர்வ இல்லம் எது?", "10 Downing Street|11 Downing Street|Buckingham Palace|Chequers", "PM 10 Downing Streetஇல் வசிக்கிறார், Chequers எனும் கிராமப்புற இல்லமும் உள்ளது."],
  146: ["பொருளாதாரத்திற்குப் பொறுப்பான அமைச்சர் யார்?", "The Chancellor of the Exchequer|The Home Secretary|The Foreign Secretary|The Lord Chancellor", "Chancellor of the Exchequer 11 Downing Streetஇல் வசிக்கிறார்."],
  147: ["குற்றம், காவல்துறை, குடியேற்றத்திற்குப் பொறுப்பான அமைச்சர் யார்?", "The Home Secretary|The Foreign Secretary|The Chancellor of the Exchequer|The Defence Secretary", "Home Secretary Home Officeஐ நடத்துகிறார்."],
  148: ["'எதிர்க்கட்சி' என்றால் என்ன?", "House of Commonsஇல் இரண்டாவது பெரிய கட்சி|அரசு ஊழியர்களின் குழு|The House of Lords|சுயேச்சை MPs மட்டும்", "Leader of the Opposition தமது கட்சியை வழிநடத்தி, அரசை எதிர்கொள்ள நிழல் அமைச்சரவையை நியமிக்கிறார்."],
  149: ["அரசுப் பணித்துறை (civil service) எப்படி இருக்க வேண்டும்?", "அரசியல் ரீதியாக நடுநிலையாகவும் தகுதியின் அடிப்படையில் நியமிக்கப்பட்டதாகவும்|பொதுமக்களால் தேர்ந்தெடுக்கப்பட்டதாக|மன்னரால் நியமிக்கப்பட்டதாக|ஆளும் கட்சியின் உறுப்பினர்களாக", "அரசு ஊழியர்கள் தமது சொந்த அரசியல் கருத்துகள் எதுவாயினும் அப்போதைய அரசை ஆதரிக்கிறார்கள்."],
  150: ["Scottish Parliamentஇல் எத்தனை உறுப்பினர்கள் உள்ளனர்?", "129|650|90|60", "Edinburghஇல் உள்ள Holyroodஐ மையமாகக் கொண்ட Scottish Parliamentஇல் 129 உறுப்பினர்கள் (MSPs) உள்ளனர்."],
  151: ["Northern Ireland Assembly எங்கே கூடுகிறது?", "Stormont, Belfast|Holyrood, Edinburgh|Cardiff Bay|Westminster", "Northern Ireland Assemblyஇல் 90 உறுப்பினர்கள் (MLAs) உள்ளனர், அது அதிகாரப் பகிர்வு அடிப்படையில் செயல்படுகிறது."],
  152: ["நாடாளுமன்ற விவாதங்களின் பதிவு எவ்வாறு அழைக்கப்படுகிறது?", "Hansard|The Domesday Book|The Gazette|The Register", "Hansard தினமும் வெளியிடப்படுகிறது, பெரிய நூலகங்களிலும் இணையத்திலும் கிடைக்கிறது."],
  153: ["இக்கூற்றுகளில் எது சரியானது?", "மன்னர் அரசியல் ரீதியாக நடுநிலையானவர், அரசியலில் யாருக்கும் ஆதரவாக இல்லை|நாடாளுமன்றம் எந்தச் சட்டங்களை இயற்றும் என்பதை மன்னர் தேர்வு செய்கிறார்|மன்னர் அனைத்து MPsஐயும் நியமிக்கிறார்|மன்னர் மிகப்பெரிய அரசியல் கட்சியை வழிநடத்துகிறார்", "மன்னர் அரசுத் தலைவர், ஆனால் கட்சி அரசியலுக்கு அப்பாற்பட்டவர், ஆலோசனையும் எச்சரிக்கையும் வழங்க Prime Ministerஐ வழக்கமாகச் சந்திக்கிறார்."],
  154: ["ஒவ்வொரு ஆண்டும் State Opening of Parliamentஇல் என்ன நடக்கிறது?", "அரசின் கொள்கைகளை விவரிக்கும் உரையை மன்னர் வாசிக்கிறார்|MPs புதிய Speakerஐத் தேர்ந்தெடுக்கின்றனர்|நிதிநிலை அறிக்கை அறிவிக்கப்படுகிறது|புதிய peers உருவாக்கப்படுகின்றனர்", "மன்னரின் உரையை அரசு எழுதுகிறது, வரும் ஆண்டுக்கான அதன் திட்டங்களை அது விவரிக்கிறது."],
  155: ["யுகே பொதுத் தேர்தலில் எந்த வயதில் வாக்களிக்கலாம்?", "18|16|21|17", "பொதுத் தேர்தலில் வாக்களிக்க 18 வயது அல்லது அதற்கு மேல் இருக்க வேண்டும், electoral registerஇல் பெயர் இருக்க வேண்டும்."],
  156: ["தேர்தல் நாளில் வாக்குச்சாவடிகள் எப்போது முதல் எப்போது வரை திறந்திருக்கும்?", "காலை 7 முதல் இரவு 10 வரை|காலை 9 முதல் மாலை 5 வரை|காலை 8 முதல் இரவு 8 வரை|காலை 6 முதல் நள்ளிரவு வரை", "வாக்குச்சாவடிகள் காலை 7 மணிக்குத் திறந்து இரவு 10 மணிக்கு மூடப்படும்."],
  157: ["Commonwealthஇல் எத்தனை உறுப்பு நாடுகள் உள்ளன?", "54|27|15|100", "Commonwealth என்பது 54 நாடுகளின் தன்னார்வக் கூட்டமைப்பு; மன்னர் அதன் தலைவர், உறுப்பினர்கள் மீது அதற்கு அதிகாரம் இல்லை."],
  158: ["யுகே UN Security Councilஇன் எத்தனை நிரந்தர உறுப்பினர்களில் ஒன்று?", "ஐந்து|மூன்று|பத்து|பதினைந்து", "யுகே ஐந்து நிரந்தர உறுப்பினர்களில் ஒன்று, முன்மொழிவுகளுக்கு veto செய்ய முடியும்."],
  159: ["NATOஇன் முக்கிய நோக்கம் என்ன?", "உறுப்பு நாடுகளுக்குக் கூட்டுப் பாதுகாப்பு வழங்குவது|வர்த்தக விதிகளை வகுப்பது|யூரோவை நிர்வகிப்பது|ஐரோப்பாவில் மனித உரிமைகளைப் பாதுகாப்பது", "NATO உறுப்பினர்கள் தாக்குதலுக்கு உள்ளானால் ஒருவருக்கொருவர் உதவ ஒப்புக்கொள்கின்றனர்."],
  160: ["Council of Europe என்ன செய்கிறது?", "உறுப்பு நாடுகளில் மனித உரிமைகளைப் பாதுகாக்கிறது|EU நிதிநிலையை வகுக்கிறது|ஐரோப்பியப் படைகளுக்குக் கட்டளையிடுகிறது|கடவுச்சீட்டுகளை வழங்குகிறது", "Council of Europe European Convention on Human Rightsக்குப் பொறுப்பானது, அதற்குச் சட்டமியற்றும் அதிகாரம் இல்லை."],
  161: ["England, Walesஇல் சிறு குற்றங்களைக் கையாளும் நீதிமன்றம் எது?", "The Magistrates' Court|The Crown Court|The County Court|The High Court", "Justices of the Peace எனவும் அழைக்கப்படும் magistrates ஊதியமற்ற தன்னார்வலர்கள், நடுவர் குழு இன்றி சிறு வழக்குகளை விசாரிக்கின்றனர்."],
  162: ["Scotlandஇல் சிறு குற்றங்கள் பொதுவாக எந்த நீதிமன்றத்தில் விசாரிக்கப்படுகின்றன?", "The Justice of the Peace Court|The Magistrates' Court|The County Court|The Crown Court", "Scotlandக்குத் தனி சட்ட அமைப்பு உள்ளது, Justice of the Peace Courts, Sheriff Courts உடன்."],
  163: ["England, Wales, Northern Irelandஇல் Crown Courtஇல் நடுவர் குழுவில் எத்தனை பேர் இருப்பர்?", "12|15|10|8", "England, Wales, Northern Irelandஇல் நடுவர் குழுவில் 12 பேர், Scotlandஇல் 15 பேர்."],
  164: ["England, Wales, Northern Irelandஇல் குற்றவியல் பொறுப்பு வயது என்ன?", "10|12|16|18", "England, Wales, Northern Irelandஇல் அது 10, Scotlandஇல் 12."],
  165: ["England, Walesஇல் சிறு உரிமையியல் தகராறுகளைக் கையாளும் நீதிமன்றம் எது?", "The County Court|The Crown Court|The Magistrates' Court|The Youth Court", "County Courts கடன், தனிநபர் காயம், ஒப்பந்த மீறல் போன்ற உரிமையியல் விவகாரங்களைக் கையாள்கின்றன."],
  166: ["சட்ட மற்றும் பண சிக்கல்களுக்கு இலவச, சுயாதீன ஆலோசனை வழங்கும் அமைப்பு எது?", "Citizens Advice|The Home Office|Law Society மட்டும்|The Crown Prosecution Service", "Citizens Advice என்பது இலவச இரகசிய ஆலோசனை வழங்கும் தேசிய தொண்டு நிறுவனங்களின் வலையமைப்பு."],
  167: ["யுகேயில் சட்டவிரோதமானவை எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "கட்டாயத் திருமணம்|பெண் பிறப்புறுப்புச் சிதைவு|சம்மதமுள்ள பெரியவர்களிடையே ஏற்பாடு செய்யப்பட்ட திருமணம்|மதஆடை அணிதல்", "கட்டாயத் திருமணமும் FGMஉம் கடுமையான குற்றங்கள். இருவரும் சம்மதிக்கும் ஏற்பாடு செய்யப்பட்ட திருமணம் சட்டப்பூர்வமானது."],
  168: ["National Insurance எதற்குப் பயன்படுகிறது?", "அரசு நலன்களுக்கும் அரசு ஓய்வூதியத்திற்கும் நிதியளிக்க|உங்கள் வீட்டைக் காப்பீடு செய்ய|council tax செலுத்த|கார் விபத்துகளை ஈடுகட்ட", "வேலை செய்யும் ஏறக்குறைய அனைவரும் National Insurance பங்களிப்புகளைச் செலுத்துகிறார்கள், National Insurance எண் தேவை."],
  169: ["PAYE முறையில் உங்கள் ஊதியத்திலிருந்து வருமான வரியைக் கழிப்பவர் யார்?", "உங்கள் முதலாளி|நீங்களே, self-assessment மூலம்|உங்கள் உள்ளாட்சி|உங்கள் வங்கி", "PAYE என்பது Pay As You Earn; சுயதொழில் செய்வோர் பொதுவாக self-assessment மூலம் வரி செலுத்துகின்றனர்."],
  170: ["ஆன்லைன் self-assessment வரிப் படிவத்தை எந்தத் தேதிக்குள் தாக்கல் செய்ய வேண்டும்?", "31 January|31 October|5 April|1 January", "காகித படிவங்கள் 31 Octoberக்குள்ளும் ஆன்லைன் படிவங்கள் 31 Januaryக்குள்ளும் தாக்கல் செய்யப்பட வேண்டும்."],

  /* ---------- CHAPTER 5 / EXTRA (core) ---------- */
  171: ["யுகேயில் எந்த வயதில் கார் ஓட்டலாம்?", "17|16|18|21", "17 வயதில் கார் அல்லது மோட்டார் சைக்கிள் ஓட்டலாம், 16 வயதில் moped ஓட்டலாம்."],
  172: ["கார் முதல் MOT சோதனையை எப்போது செய்ய வேண்டும்?", "மூன்று வயதாகும்போது|ஒரு வயதாகும்போது|ஐந்து வயதாகும்போது|வாங்கிய உடனேயே", "மூன்று ஆண்டுகளுக்கு மேற்பட்ட வாகனங்கள் சாலைக்கு உகந்ததாக இருக்க ஆண்டுதோறும் MOT சோதனையில் தேர்ச்சி பெற வேண்டும்."],
  173: ["உங்கள் சமூகத்தில் பங்கேற்கும் வழிகள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "school governorஆகப் பணியாற்றுவது|ஒரு தொண்டு நிறுவனத்திற்குத் தன்னார்வத் தொண்டு|jury serviceஐ மறுப்பது|உள்ளாட்சித் தேர்தல்களைத் தவிர்ப்பது", "neighbourhood watchஇல் சேரலாம், magistrate அல்லது special constable ஆகலாம், அல்லது உள்ளூர் மருத்துவமனையில் உதவலாம்."],
  174: ["jury serviceக்கு யாரை அழைக்கலாம்?", "electoral registerஇல் உள்ள 18 முதல் 70 வயதுடைய எவரையும்|வழக்கறிஞர்களை மட்டும்|25 வயதுக்கு மேற்பட்டவர்களை மட்டும்|பிரிட்டனில் பிறந்த குடிமக்களை மட்டும்", "jury service ஒரு கடமை, மக்கள் electoral registerஇலிருந்து சீரற்ற முறையில் தேர்ந்தெடுக்கப்படுகின்றனர்."],
  175: ["யுகேயில் அனைத்து ஓட்டுநர்களும் எதை வைத்திருக்க வேண்டும்?", "மோட்டார் காப்பீடு|பல்கலைக்கழகப் பட்டம்|குடியிருப்பு அனுமதி|வாகன நிறுத்த அனுமதி", "காப்பீடு இன்றி வாகனம் ஓட்டுவது குற்றம்; செல்லுபடியாகும் உரிமமும் road taxஉம் தேவை."],
  176: ["காவல்துறை உங்களை நிறுத்தி அநீதியாக நடத்தியதாக உணர்ந்தால் என்ன செய்யலாம்?", "காவல்துறையிடமோ ஒரு சுயாதீன அமைப்பிடமோ புகார் அளிக்கலாம்|எதுவும் செய்ய முடியாது|MPயிடம் மட்டுமே புகார் அளிக்கலாம்|இனி எந்த உத்தரவையும் மறுக்கலாம்", "காவல்துறை சட்டத்தைக் கடைப்பிடிக்க வேண்டும், இல்லையெனில் முறையான புகார் நடைமுறைகள் உள்ளன."],
  177: ["Police and Crime Commissioner என்பவர் யார்?", "உள்ளூர் காவல்துறை முன்னுரிமைகளை மேற்பார்வையிடும் தேர்ந்தெடுக்கப்பட்ட அதிகாரி|ஒரு மூத்த காவல் அதிகாரி|Home Officeஇல் ஒரு அரசு ஊழியர்|குற்றவியல் நீதிமன்றத்தில் ஒரு நீதிபதி", "England, Walesஇல் உள்ளூர் காவல்துறையைப் பொறுப்புக்கூறச் செய்ய PCCs பொதுமக்களால் தேர்ந்தெடுக்கப்படுகின்றனர்."],
  178: ["இக்கூற்றுகளில் எது சரியானது?", "உள்ளாட்சி அமைப்புகளுக்கு மத்திய அரசும் உள்ளூர் council taxஉம் நிதியளிக்கின்றன|உள்ளாட்சி அமைப்புகளுக்கு நன்கொடைகள் மட்டுமே நிதியளிக்கின்றன|உள்ளாட்சி அமைப்புகளுக்கு அரசுப் பணம் கிடைப்பதில்லை|உள்ளாட்சி அமைப்புகளுக்கு மன்னர் நிதியளிக்கிறார்", "Councils குப்பை சேகரிப்பு, நூலகங்கள், பள்ளிகள் போன்ற சேவைகளை வழங்குகின்றன."],
  201: ["இவற்றுள் எது பிரிட்டிஷ் வாழ்வின் அடிப்படைக் கோட்பாடுகளில் ஒன்று அல்ல?", "ஓர் அரசியல் கட்சிக்கு விசுவாசம்|தனிமனித சுதந்திரம்|வெவ்வேறு நம்பிக்கை உள்ளவர்கள் மீதான சகிப்புத்தன்மை|ஜனநாயகம்", "கோட்பாடுகள் ஜனநாயகம், சட்டத்தின் ஆட்சி, தனிமனித சுதந்திரம், வெவ்வேறு நம்பிக்கைகள் மீதான சகிப்புத்தன்மை, சமூக வாழ்வில் பங்கேற்பு ஆகியவை."],
  202: ["நிரந்தரக் குடியிருப்பு அல்லது குடியுரிமைக்கு விண்ணப்பிக்கும் முன் என்ன செய்ய வேண்டும்?", "Life in the UK தேர்வில் தேர்ச்சி பெற்று ஆங்கில மொழித் தேவையை நிறைவேற்ற வேண்டும்|யுகேயில் ஒரு வீடு வாங்க வேண்டும்|ஆயுதப் படையில் பணியாற்ற வேண்டும்|பதிவுசெய்யப்பட்ட அரசியல் கட்சியில் சேர வேண்டும்", "விலக்கு இல்லையெனில் பொதுவாக இரு தேவைகளும் நிறைவேற்றப்பட வேண்டும்."],
  203: ["இக்கூற்று சரியா தவறா? யுகே பன்முகச் சமூகம், புதிதாக வருபவர்களை வரவேற்கும் நீண்ட வரலாறு கொண்டது.", "சரி|தவறு", "Anglo-Saxons, வைக்கிங்குகள் முதல் சமீபத்திய வருகைகள் வரை, குடியேற்றம் பல நூற்றாண்டுகளாகப் பிரிட்டிஷ் சமூகத்தை வடிவமைத்துள்ளது."],
  204: ["நீங்கள் வாழும் இடத்தின் சுற்றுச்சூழலைப் பாதுகாக்க எவை இரண்டைச் செய்யலாம்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "வீட்டுக் கழிவுகளை மறுசுழற்சி செய்வது|குறுகிய பயணங்களுக்கு நடப்பது அல்லது சைக்கிள் ஓட்டுவது|பொது பூங்காக்களில் குப்பையை விடுவது|தோட்டத்தில் கழிவுகளை எரிப்பது", "நீங்கள் வாழும் பகுதியைப் பராமரிப்பது யுகேயில் வாழ்வதன் பொறுப்புகளில் ஒன்று."],
  205: ["Scotlandஇன் தலைநகரம் எது?", "Edinburgh|Glasgow|Aberdeen|Dundee", "Edinburgh தலைநகரம்; Scottish Parliament அங்கு Holyroodஇல் கூடுகிறது."],
  206: ["இக்கூற்று சரியா தவறா? Isle of Man United Kingdomஇன் பகுதி.", "தவறு|சரி", "Isle of Man தனி அரசு கொண்ட Crown dependency, யுகேயின் பகுதி அல்ல."],
  207: ["யுகேயின் நீளமான ஆறு எது?", "The Severn|The Thames|The Tyne|The Clyde", "Severn சுமார் 220 மைல்கள் ஓடுகிறது; அதற்கு அடுத்தபடியாக Thames Englandஇன் நீளமான ஆறு."],
  208: ["இவற்றுள் எது Northern Irelandஇல் உள்ள பெரிய நகரம்?", "Londonderry|Swansea|Leeds|Dundee", "Belfast, Londonderry ஆகியவை Northern Irelandஇன் முக்கிய நகரங்கள்."],
  209: ["Stonehengeஐக் கட்டியவர்கள் யார்?", "கற்கால மற்றும் வெண்கலக் கால மக்கள்|ரோமானியர்கள்|வைக்கிங்குகள்|நார்மன்கள்", "Wiltshireஇல் உள்ள Stonehenge ஒருவேளை சடங்கு இடமாக இருந்திருக்கலாம், கற்கால மற்றும் வெண்கலக் காலத்தில் கட்டப்பட்டது."],
  210: ["Celts எந்த மொழி பேசினர்?", "Celtic மொழிகள், Welsh, Gaelicஇன் மூதாதையர்|லத்தீன்|Old English|நோர்ஸ்", "Celtic மொழிகள் இன்று Welsh, Gaelic, Cornish ஆக நீடிக்கின்றன."],
  211: ["Britainஇன் எந்தப் பகுதிகள் ரோமானியரால் ஒருபோதும் கைப்பற்றப்படவில்லை?", "Scotland, Ireland|Wales, Cornwall|Kent, Sussex|East Anglia", "ரோமானிய ஆட்சி England, Walesஐ உள்ளடக்கியது; Scotland, Ireland பேரரசுக்கு வெளியே இருந்தன."],
  212: ["Iona தீவில் ஒரு மடத்தை நிறுவியவர் யார்?", "St Columba|St Augustine|St Patrick|St Andrew", "St Columbaஇன் பணி Ionaஇலிருந்து Scotland முழுவதும் கிறித்தவத்தைப் பரப்பியது."],
  213: ["Battle of Hastingsஇல் ஆங்கிலேயருக்குத் தலைமை தாங்கிய மன்னர் யார்?", "Harold|Alfred|Cnut|Edward", "1066இல் Hastingsஇல் மன்னர் Harold கொல்லப்பட்டார், William of Normandy அரியணை ஏறினார்."],
  214: ["Runnymedeஇல் மன்னர் John எந்த ஆவணத்தில் முத்திரையிட்டார்?", "Magna Carta|The Bill of Rights|The Domesday Book|The Act of Union", "1215இல் Magna Cartaவை ஏற்க பாரன்கள் மன்னர் Johnஐ நிர்ப்பந்தித்தனர்."],
  215: ["Black Death எந்த நூற்றாண்டில் Britainஇற்கு வந்தது?", "14ஆம் நூற்றாண்டு|12ஆம் நூற்றாண்டு|16ஆம் நூற்றாண்டு|17ஆம் நூற்றாண்டு", "கொள்ளைநோய் 1348இல் Englandஐ அடைந்து மக்கள்தொகையில் சுமார் மூன்றில் ஒரு பங்கைக் கொன்றது."],
  216: ["Black Deathஇன் விளைவுகள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "தொழிலாளர் பற்றாக்குறை|செல்வமிக்க நடுத்தர வர்க்கத்தின் வளர்ச்சி|நார்மன் வெற்றி|அச்சுத்தொழிலின் கண்டுபிடிப்பு", "குறைவான தொழிலாளர்கள் என்பதால் உயிர் பிழைத்தவர்கள் சிறந்த ஊதியம் கோர முடிந்தது, இது பழைய நிலப்பிரபுத்துவ முறையை பலவீனப்படுத்தியது."],
  217: ["Englandஐ ஆட்சி செய்த கடைசிக் கத்தோலிக்க மன்னர் யார்?", "James II|Charles II|Henry VIII|Elizabeth I", "James II 1688இல் Glorious Revolution காலத்தில் தப்பிச் சென்றார்."],
  218: ["Reformation என்றால் என்ன?", "போப்பின் அதிகாரத்திற்கு எதிரான ஓர் இயக்கம்|வரிக்கு எதிரான கிளர்ச்சி|சட்ட அமைப்பில் ஒரு மாற்றம்|நாடாளுமன்றத்தின் நிறுவுதல்", "புராட்டஸ்டன்ட் கருத்துகள் ஐரோப்பாவெங்கும் பரவின; Henry VIIIஇன் ரோம் பிரிவினை அவற்றை Englandக்குக் கொண்டுவந்தது."],
  219: ["Scotlandஐ ஆட்சி செய்து 1587இல் தூக்கிலிடப்பட்ட அரசி யார்?", "Mary, Queen of Scots|Mary I|Elizabeth I|Anne", "Mary Englandஇற்குத் தப்பி, 20 ஆண்டுகள் சிறையில் இருந்து, இறுதியில் Elizabeth Iக்கு எதிரான சதி சந்தேகத்தில் தூக்கிலிடப்பட்டார்."],
  220: ["Gunpowder Plot என்றால் என்ன?", "1605இல் Houses of Parliamentஐத் தகர்க்க ஒரு கத்தோலிக்கத் திட்டம்|Londonஐ எரிக்கும் திட்டம்|Cromwellஐக் கொல்லும் சதி|ஒரு ஸ்காட்டிஷ் கிளர்ச்சி", "நாடாளுமன்றத்திற்குக் கீழே வெடிபொருள்களைக் காவல் காத்த Guy Fawkes பிடிபட்டார்; இத்தோல்வி 5 Novemberஇல் நினைவுகூரப்படுகிறது."],
  221: ["நாடாளுமன்றத்திற்கும் மன்னர் Charles Iக்கும் இடையே நடந்த போர் எது?", "The English Civil War|The Wars of the Roses|The Hundred Years War|The Crimean War", "உள்நாட்டுப் போர் 1642இல் தொடங்கி 1649இல் மன்னரின் மரணதண்டனையில் முடிந்தது."],
  222: ["Great Fireக்குப் பிறகு St Paul's Cathedralஐ மீண்டும் கட்டிய கட்டடக்கலைஞர் யார்?", "Sir Christopher Wren|Inigo Jones|Robert Adam|John Nash", "1666இன் Great Fire பழைய பேராலயம் உட்பட Londonஇன் பெரும்பகுதியை அழித்தது."],
  223: ["Irelandஉடனான Act of Union United Kingdom of Great Britain and Irelandஐ உருவாக்கிய ஆண்டு எது?", "1801|1707|1922|1689", "Ireland 1801இல் ஒன்றியத்தில் சேர்ந்தது; அதன் பெரும்பகுதி 1922இல் வெளியேறியது."],
  224: ["தொழிற்புரட்சிக்கு முக்கியமான Richard Arkwrightஇன் கண்டுபிடிப்பு எது?", "துணிக்கான திறமையான, லாபகரமான நூற்பு இயந்திரங்கள்|நீராவி ரயில் என்ஜின்|தொலைபேசி|மின் விளக்கு", "Arkwrightஇன் தொழிற்சாலைகள் ஜவுளி உற்பத்தியை மாற்றியமைத்தன."],
  225: ["Isambard Kingdom Brunel எதற்காகப் புகழ்பெற்றவர்?", "பாலங்கள், ரயில்பாதைகள், கப்பல்கள் கட்டியதற்காக|penicillin கண்டுபிடித்ததற்காக|NHS நிறுவியதற்காக|நாவல்கள் எழுதியதற்காக", "Brunel Great Western Railwayஐயும் SS Great Britain உள்ளிட்ட கப்பல்களையும் கட்டினார்."],
  226: ["1851இன் Great Exhibition எதைக் கொண்டாட நடத்தப்பட்டது?", "Britain மற்றும் உலகெங்கிலுமிருந்து தொழில் மற்றும் பண்பாடு|நெப்போலியப் போர்களின் முடிவு|அரசி Victoriaஇன் முடிசூட்டு விழா|பேரரசின் நிறுவுதல்", "இது Hyde Parkஇல் உள்ள Crystal Palaceஇல் நடத்தப்பட்டது."],
  227: ["Mary Seacole யார்?", "Crimeaவில் காயமடைந்த வீரர்களுக்கு சிகிச்சை அளித்த ஜமைக்காவைச் சேர்ந்த செவிலியர்|Britainஇன் முதல் பெண் மருத்துவர்|ஒரு suffragette தலைவர்|ஒரு போர்க்கால பிரதமர்", "நோயுற்ற, காயமடைந்த வீரர்களுக்காக அவர் ஒரு தங்குமிடத்தை அமைத்தார், இன்று Londonஇல் சிலையால் கௌரவிக்கப்படுகிறார்."],
  228: ["Emmeline Pankhurstஇன் பிரச்சாரகர்கள் பொதுவாக எவ்வாறு அறியப்பட்டனர்?", "Suffragettes|Chartists|Levellers|Jacobites", "suffragettes பெண்களுக்கு வாக்குரிமை கோரி, First World Warக்கு முன் மேலும் தீவிரமான முறைகளைக் கையாண்டனர்."],
  229: ["First World Warஇல் Britainஇன் முக்கிய கூட்டாளி நாடுகள் எவை?", "France, Russia மற்றும் பின்னர் United States|Germany, Austria|Italy, Japan மட்டும்|Spain, Portugal", "Britain France, Russia மற்றும் பின்னர் Italy, Japan, United Statesஉடன் சேர்ந்து போரிட்டது."],
  230: ["Blitz என்றால் என்ன?", "ஜெர்மன் விமானங்களால் பிரிட்டிஷ் நகரங்கள் மீதான கடும் குண்டுவீச்சு|Dunkirk வெளியேற்றம்|Normandy படையெடுப்பு|Malta பாதுகாப்பு", "1940 முதல் London, Coventry மற்றும் பிற நகரங்கள் கடுமையாகக் குண்டுவீசப்பட்டன."],
  231: ["Second World Warஇல் Britain எந்த ஜெர்மன் தலைவருக்கு எதிராகப் போரிட்டது?", "Adolf Hitler|Kaiser Wilhelm|Otto von Bismarck|Erich Ludendorff", "Germany Poland மீது படையெடுத்த பிறகு Britain 1939இல் போரை அறிவித்தது."],
  232: ["Second World Warக்குப் பிறகு விரைவில் நிறுவப்பட்டவை எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "The National Health Service|நலன்புரி அரசின் சலுகை அமைப்பு|European Union|The Bank of England", "NHS 1948இல் தொடங்கியது, Beveridge Report நவீன நலன்புரி அரசை வடிவமைத்தது."],
  233: ["DNAஇன் அமைப்பைக் கண்டறிய உதவிய பிரிட்டிஷ் அறிவியலாளர்கள் யார்?", "Francis Crick, Maurice Wilkins|Alexander Fleming, Howard Florey|Charles Darwin, Alfred Wallace|Isaac Newton, Robert Hooke", "இக்கண்டுபிடிப்பு 1953இல் Cambridgeஇல், James Watsonஉடன் இணைந்து செய்யப்பட்டது."],
  234: ["hovercraftஐக் கண்டுபிடித்தவர் யார்?", "Sir Christopher Cockerell|Sir Frank Whittle|John Logie Baird|Sir Tim Berners-Lee", "பிரிட்டிஷ் கண்டுபிடிப்பாளர் Cockerell 1950களில் hovercraftஐ உருவாக்கினார்."],

  /* ---------- EXTRA (core, completing 253) ---------- */
  235: ["Second World War காலத்தில் புகழ்பெற்ற பிரிட்டிஷ் Prime Minister யார்?", "Winston Churchill|Harold Wilson|Stanley Baldwin|Anthony Eden", "Churchill 1940 முதல் போர்க்கால கூட்டணி அரசை வழிநடத்தி, 1951இல் மீண்டும் PM ஆனார்."],
  236: ["Commonwealth முதலில் எதிலிருந்து உருவானது?", "ஒரு காலத்தில் British Empireஇன் பகுதியாக இருந்த நாடுகள்|European Union உறுப்பினர்கள்|ஐக்கிய நாடுகளின் நிறுவன உறுப்பினர்கள்|NATO உறுப்பு நாடுகள்", "பெரும்பாலான Commonwealth உறுப்பினர்கள் முன்னாள் பிரிட்டிஷ் காலனிகள், எனினும் உறுப்பினர்ப் பதிவு தன்னார்வமானது."],
  237: ["Wales, Scotland ஆகியவற்றுடன் தொடர்புடைய பாரம்பரிய உணவுகள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "Welsh cakes|Haggis|Ulster fry|Cornish pasty", "Welsh cakes Walesஇலிருந்தும் haggis Scotlandஇலிருந்தும் வருகின்றன; Ulster fry Northern Irelandஇலிருந்து."],
  238: ["United Kingdomஇன் கொடி பொதுவாக எவ்வாறு அழைக்கப்படுகிறது?", "The Union Flag அல்லது Union Jack|The Royal Standard|The Red Ensign|The Saltire", "இது St George, St Andrew, St Patrick ஆகியோரின் சிலுவைகளை இணைக்கிறது."],
  239: ["Christmas Day எந்தத் தேதியில் கொண்டாடப்படுகிறது?", "25 December|24 December|26 December|1 January", "26 December, Boxing Dayஉம் பொது விடுமுறை."],
  240: ["யுகேயில் இந்துக்களும் சீக்கியர்களும் கொண்டாடும் ஒளித் திருவிழா எது?", "Diwali|Eid al-Fitr|Hanukkah|Vaisakhi", "Diwali பொதுவாக October அல்லது Novemberஇல் வந்து ஐந்து நாட்கள் நீடிக்கும்."],
  241: ["Eid al-Fitr என்றால் என்ன?", "Ramadanஇன் முடிவைக் குறிக்கும் ஒரு முஸ்லிம் திருவிழா|ஓர் இந்து புத்தாண்டுத் திருவிழா|ஒரு சீக்கிய அறுவடைத் திருவிழா|ஓர் யூத ஒளித் திருவிழா", "நோன்பு மாதத்தை நிறைவு செய்யும் வலிமை அளித்ததற்காக முஸ்லிம்கள் இறைவனுக்கு நன்றி கூறுகின்றனர்."],
  242: ["Lord's கிரிக்கெட் மைதானத்தில் எந்த விளையாட்டு விளையாடப்படுகிறது?", "கிரிக்கெட்|ரக்பி|டென்னிஸ்|கால்பந்து", "Londonஇல் உள்ள Lord's உலகின் மிகப் புகழ்பெற்ற கிரிக்கெட் மைதானங்களில் ஒன்று."],
  243: ["யுகே முழுவதிலுமிருந்து தேசிய ரக்பி யூனியன் அணிகள் பங்கேற்கும் போட்டி எது?", "The Six Nations Championship|The Ashes|The Ryder Cup|The Grand National", "England, Scotland, Wales, Ireland ஒவ்வொரு ஆண்டும் France, Italyஉடன் விளையாடுகின்றன."],
  244: ["Sir Ian Botham எந்த விளையாட்டில் புகழ்பெற்றவர்?", "கிரிக்கெட்|கால்பந்து|படகுப் போட்டி|கார் பந்தயம்", "டெஸ்ட் கிரிக்கெட்டில் Englandஇன் அதிக விக்கெட் சாதனையை Botham வைத்திருந்தார்."],
  245: ["1960கள், 70களில் மூன்று முறை Formula 1 உலக சாம்பியன்ஷிப் வென்ற கார் பந்தய ஓட்டுநர் யார்?", "Sir Jackie Stewart|Damon Hill|Lewis Hamilton|Stirling Moss", "ஸ்காட்டிஷ் ஓட்டுநர் Jackie Stewart மூன்று உலக சாம்பியன்ஷிப்களை வென்றார்."],
  246: ["'bank holiday' என்றால் என்ன?", "பெரும்பாலான வணிகங்கள் மூடப்படும் பொது விடுமுறை|வங்கிகள் கட்டணம் வசூலிக்காத நாள்|வங்கிகள் மட்டும் மூடப்படும் நாள்|ஒரு மதத் திருவிழா", "bank holidaysஇல் Christmas Day, Boxing Day, New Year's Day, Easter Monday அடங்கும்."],
  247: ["இவற்றுள் யார் புகழ்பெற்ற பிரிட்டிஷ் திரைப்பட இயக்குநர்?", "Sir Alfred Hitchcock|Steven Spielberg|Martin Scorsese|Ang Lee", "Hitchcock Psycho, The Birds ஆகியவற்றை இயக்கினார்; பிரிட்டிஷ் திரைப்பட விருதுகள் BAFTAs."],
  248: ["Londonஇல் நடத்தப்படும் ஆண்டு மலர் கண்காட்சி எது?", "The Chelsea Flower Show|The Edinburgh Festival|The Notting Hill Carnival|The Eisteddfod", "Chelsea Flower Show உலகெங்கிலுமிருந்து தோட்ட வடிவமைப்பைக் காட்சிப்படுத்துகிறது."],
  249: ["Eisteddfod என்றால் என்ன?", "இலக்கியம், இசை, நிகழ்த்துகலைக்கான ஒரு வெல்ஷ் திருவிழா|ஒரு ஸ்காட்டிஷ் highland games|ஓர் ஐரிஷ் நடனப் போட்டி|ஓர் ஆங்கிலக் கிராமத் திருவிழா", "Walesஇல் ஆண்டுதோறும் National Eisteddfod நடைபெறுகிறது, முக்கியமாக வெல்ஷ் மொழியில்."],
  250: ["இவற்றுள் Wiltshireஇல் உள்ள வரலாற்றுக்கு முந்தைய நினைவுச்சின்னம் எது?", "Stonehenge|The Eden Project|The Tower of London|Snowdonia", "Stonehenge ஒரு World Heritage Site, உலகின் மிகப் புகழ்பெற்ற வரலாற்றுக்கு முந்தைய நினைவுச்சின்னங்களில் ஒன்று."],
  251: ["Eden Project எங்கே உள்ளது?", "Cornwall|Kent|Fife|Antrim", "Cornwallஇல் உள்ள Eden Projectஇன் biomes உலகெங்கிலுமிருந்து தாவரங்களைக் கொண்டுள்ளன."],
  252: ["யுகேயின் மிகப்பெரிய தேசியப் பூங்கா எது?", "The Cairngorms|Snowdonia|The Lake District|The Peak District", "Scotlandஇல் உள்ள Cairngorms National Park யுகேயின் மிகப்பெரியது."],
  253: ["யுகேயில் நேரலை தொலைக்காட்சியைப் பார்க்கவோ பதிவு செய்யவோ முன் என்ன செய்ய வேண்டும்?", "TV licence வாங்க வேண்டும்|உள்ளாட்சியில் பதிவு செய்ய வேண்டும்|BBCஇல் சேர வேண்டும்|Ofcomக்கு விண்ணப்பிக்க வேண்டும்", "நேரலை தொலைக்காட்சி பார்க்கும் அல்லது BBC iPlayer பயன்படுத்தும் ஒவ்வொரு குடும்பத்திற்கும் TV licence தேவை."],
  254: ["National Lottery டிக்கெட்டை எந்த வயதில் வாங்கலாம்?", "18|16|21|14", "National Lottery பொருட்களுக்கான குறைந்தபட்ச வயது 18."],
  255: ["யுகேயில் மக்கள் தொண்டில் பங்கேற்கும் வழிகள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "தொண்டு நிறுவனக் கடையில் தன்னார்வத் தொண்டு|நிதி திரட்டும் முயற்சிக்கு நன்கொடை|வரி செலுத்த மறுப்பது|உள்ளாட்சித் தேர்தல்களைப் புறக்கணிப்பது", "National Trust, Comic Relief போன்ற தொண்டு நிறுவனங்கள் தன்னார்வலர்களையும் நன்கொடைகளையும் பெரிதும் நம்பியுள்ளன."],
  256: ["யுகேயின் அரசுத் தலைவர் யார்?", "மன்னர்|The Prime Minister|The Speaker|The Lord Chancellor", "மன்னர் அரசுத் தலைவர்; Prime Minister அரசாங்கத் தலைவர்."],
  257: ["constituency என்றால் என்ன?", "ஒரு MP பிரதிநிதித்துவப்படுத்தும் பகுதி|ஓர் அரசியல் கட்சி|ஓர் அரசுத் துறை|ஒரு வகை நீதிமன்றம்", "650 தொகுதிகள் உள்ளன, ஒவ்வொன்றும் ஒரு MPஐத் தேர்ந்தெடுக்கிறது."],
  258: ["by-election என்றால் என்ன?", "பொதுத் தேர்தல்களுக்கு இடையே ஓர் MPஇன் இடம் காலியாகும்போது நடத்தப்படும் தேர்தல்|பொதுத் தேர்தலின் இரண்டாம் சுற்று|உள்ளாட்சிக் கவுன்சிலர்களுக்கான தேர்தல்|ஒரு பொதுவாக்கெடுப்பு", "ஓர் MP பதவி விலகும்போது அல்லது இறக்கும்போது by-elections நடைபெறுகின்றன."],
  259: ["ஒரு pressure groupஇன் பங்கு என்ன?", "ஒரு குறிப்பிட்ட பிரச்சினையில் அரசுக் கொள்கையைச் செல்வாக்கு செலுத்துவது|தேர்தல்களை நடத்துவது|வரி வசூலிப்பது|நீதிபதிகளை நியமிப்பது", "pressure groups குறிப்பிட்ட நோக்கங்களில் பிரிட்டிஷ் குடிமக்களின் கருத்துகளைப் பிரதிநிதித்துவப்படுத்துகின்றன."],
  260: ["யுகே சட்டத்தின் இரு முக்கிய ஆதாரங்கள் எவை?", "Acts of Parliament மற்றும் case law|அரச ஆணைகளும் திருச்சபைச் சட்டமும்|ஐரோப்பிய ஒப்பந்தங்கள் மட்டும்|உள்ளாட்சி விதிகள்", "நீதிபதிகளும் சட்டத்தை விளக்குகிறார்கள், அவர்களின் தீர்ப்புகள் common law ஆகத் திரள்கின்றன."],
  261: ["கடுமையான குற்றச்சாட்டு எதிர்கொள்ளும்போது வழக்கறிஞரை நியமிக்க முடியாவிட்டால் உங்களைப் பிரதிநிதித்துவப்படுத்துவது யார்?", "legal aid மூலம் பணம் பெறும் solicitor அல்லது barrister|ஒரு காவல் அதிகாரி|ஒரு magistrate|ஓர் அரசு ஊழியர்", "உங்கள் சூழல்களையும் வழக்கையும் பொறுத்து legal aid கிடைக்கக்கூடும்."],
  262: ["Scotlandஇல் கடுமையான குற்றவியல் வழக்குகளை எந்த நீதிமன்றம் விசாரிக்கிறது?", "The High Court of Justiciary அல்லது Sheriff Court|The Crown Court|The Magistrates' Court|The County Court", "England, Wales, Northern Irelandஇலிருந்து தனியான சொந்த சட்ட அமைப்பு Scotlandக்கு உள்ளது."],
  263: ["நீங்கள் பணம் செலுத்திய பொருள் அல்லது சேவையில் சிக்கல் இருந்தால் என்ன செய்யலாம்?", "வழக்கை County Courtக்கு எடுத்துச் செல்லலாம் அல்லது small claims நடைமுறையைப் பயன்படுத்தலாம்|காவல்துறையிடம் புகார் அளிக்கலாம்|நாடாளுமன்றத்திடம் மேல்முறையீடு செய்யலாம்|Crown Courtஐத் தொடர்பு கொள்ளலாம்", "small claims England, Wales, Northern Irelandஇல் County Courtsஇலும் Scotlandஇல் Sheriff Courtsஇலும் கையாளப்படுகின்றன."],
  264: ["பணியிடத்தில் சட்டவிரோதமான பாகுபாட்டு வடிவங்கள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "இனத்தின் அடிப்படையிலான பாகுபாடு|இயலாமையின் அடிப்படையிலான பாகுபாடு|சரியான தகுதி இல்லாத ஒருவரை வேலைக்கு எடுக்க மறுப்பது|அதிக அனுபவத்திற்கு அதிக ஊதியம் தருவது", "Equality Act வயது, இயலாமை, இனம், மதம், பாலினம், பாலியல் நாட்டம் போன்ற அடிப்படைகளில் பாகுபாட்டிலிருந்து பாதுகாக்கிறது."],
  265: ["காவல்துறை, தீயணைப்பு, ஆம்புலன்ஸுக்கான யுகேயின் அவசரத் தொலைபேசி எண் எது?", "999 அல்லது 112|911|101|111", "அவசரநிலையில் 999 அல்லது 112 பயன்படுத்தவும்; 101 அவசரமற்ற காவல்துறை விவகாரங்களுக்கும் 111 அவசரமற்ற மருத்துவ ஆலோசனைக்கும்."],
  266: ["Englandஇல் அவசரமற்ற மருத்துவ ஆலோசனைக்கு எந்த எண்ணை அழைக்க வேண்டும்?", "111|999|101|112", "நிலைமை உயிருக்கு ஆபத்தானதாக இல்லாதபோது NHS 111 மருத்துவ ஆலோசனை வழங்குகிறது."],
  267: ["மருத்துவரிடம் எவ்வாறு பதிவு செய்யலாம்?", "உள்ளூர் GP surgeryஇல் பெயர் பதிவு செய்யலாம்|Home Officeக்கு விண்ணப்பிக்கலாம்|முதலாளியிடம் கேட்கலாம்|மருத்துவமனையில் மட்டும் பதிவு செய்யலாம்", "அவசரமற்ற உடல்நலப் பிரச்சினைகளுக்கு GPs பொதுவாக முதல் தொடர்பு புள்ளி."],
  268: ["யார் MPஆகத் தேர்தலில் நிற்கலாம்?", "யுகே, ஐரிஷ் அல்லது தகுதியுள்ள Commonwealth குடிமக்களான 18 வயது அல்லது மேற்பட்ட பெரும்பாலானோர்|25 வயதுக்கு மேற்பட்டவர்கள் மட்டும்|இரு பெரும் கட்சிகளின் உறுப்பினர்கள் மட்டும்|யுகேயில் பிறந்தவர்கள் மட்டும்", "ஆயுதப் படை உறுப்பினர்கள், அரசு ஊழியர்கள், கைதிகள் போன்ற சிலர் தகுதியிழக்கின்றனர்."],
  269: ["school governor என்பவர் யார்?", "ஒரு பள்ளியை நடத்த உதவும் தன்னார்வலர்|ஊதியம் பெறும் தலைமை ஆசிரியர்|உள்ளாட்சி ஊழியர்|அரசு ஆய்வாளர்", "school governor ஆவது உங்கள் சமூகத்தில் பங்கேற்கும் ஒரு வழி."],
  270: ["jury serviceக்கு அழைக்கப்பட்டால் எதைச் செய்ய வேண்டும்?", "விலக்குக்கான செல்லுபடியான காரணம் இல்லையெனில் ஆஜராக வேண்டும்|பங்கேற்க கட்டணம் செலுத்த வேண்டும்|விசாரிக்க ஒரு வழக்கைத் தேர்வு செய்ய வேண்டும்|முழு ஆண்டும் பணியாற்ற வேண்டும்", "jury service ஒரு பொதுக் கடமை, மக்கள் electoral registerஇலிருந்து சீரற்ற முறையில் தேர்ந்தெடுக்கப்படுகின்றனர்."],
  271: ["Speakerஇன் தொகுதிப் பணியின் நோக்கம் என்ன?", "Speaker இன்னும் MPஆகத் தமது வாக்காளர்களைப் பிரதிநிதித்துவப்படுத்துகிறார்|Speakerக்குத் தொகுதி இல்லை|Speaker அரசைப் பிரதிநிதித்துவப்படுத்துகிறார்|Speaker விவாதங்களுக்கு மட்டும் தலைமை தாங்குகிறார்", "Speaker தொகுதி MPஆகவே இருக்கிறார், ஆனால் Commonsஇல் அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டும்."],
  272: ["House of Commons நிறைவேற்றிய சட்டங்களைச் சரிபார்த்து திருத்தங்களை முன்மொழியக்கூடிய அமைப்பு எது?", "The House of Lords|The Supreme Court|அரசுப் பணித்துறை|மன்னரின் குடும்பம்", "Lords சட்டங்களை ஆய்வு செய்கிறது, எனினும் Commons இறுதியில் அதை மீறலாம்."],
  273: ["council tax செலுத்தாவிட்டால் என்ன நடக்கும்?", "நீதிமன்றத்திற்கு அழைத்துச் செல்லப்பட்டு கூடுதல் செலவுகளை எதிர்கொள்ள நேரிடும்|எதுவும் இல்லை, அது தன்னார்வமானது|உங்கள் கடவுச்சீட்டு பறிக்கப்படும்|நீங்கள் நாடு கடத்தப்படுவீர்கள்", "council tax குப்பை சேகரிப்பு, நூலகங்கள், காவல்துறை போன்ற உள்ளூர் சேவைகளுக்குப் பணம் அளிக்கிறது."],
  274: ["'devolved power' என்ற சொல்லின் பொருள் என்ன?", "மத்திய அரசிடமிருந்து ஒரு தேசிய அல்லது பிராந்திய அமைப்புக்கு மாற்றப்பட்ட அதிகாரங்கள்|மன்னருக்கு வழங்கப்பட்ட அதிகாரங்கள்|நீதிமன்றங்களுக்கு வழங்கப்பட்ட அதிகாரங்கள்|உள்ளூர் தொண்டு நிறுவனங்களுக்கு வழங்கப்பட்ட அதிகாரங்கள்", "Scotland, Wales, Northern Irelandக்கு சுகாதாரம், கல்வி போன்ற துறைகளில் அதிகாரங்களுடன் devolved நிர்வாகங்கள் உள்ளன."],
  275: ["வேலை செய்யும் ஒவ்வொரு யுகே குடியிருப்பாளரின் பொறுப்பு எது?", "வருமான வரியும் National Insuranceஉம் செலுத்துவது|ஒரு தொழிற்சங்கத்தில் சேருவது|ஒவ்வொரு தேர்தலிலும் வாக்களிப்பது|magistrateஆகப் பணியாற்றுவது", "வரி சாலைகள், பள்ளிகள், ஆயுதப் படைகள், NHS போன்ற பொதுச் சேவைகளுக்குப் பணம் அளிக்கிறது."],

  /* ---------- DOUBLES — CHAPTER 1-3 ---------- */
  1000: ["பின்வருவனவற்றுள் எது Britain வாழ்வின் மையக் கோட்பாடாகக் கருதப்படுகிறது?", "சட்டத்தின் ஆட்சி|அனைத்து பெரியவர்களுக்கும் கட்டாய இராணுவப் பணி|ஒரே அதிகாரப்பூர்வ மதம்|பத்திரிகைகள் மீதான அரசுக் கட்டுப்பாடு", "அடிப்படைக் கோட்பாடுகளில் ஜனநாயகம், சட்டத்தின் ஆட்சி, தனிமனித சுதந்திரம், வெவ்வேறு நம்பிக்கைகள் மீதான சகிப்புத்தன்மை, சமூக வாழ்வில் பங்கேற்பு ஆகியவை அடங்கும்."],
  1004: ["யுகேயில் வாழ்பவர்களிடம் எதிர்பார்க்கப்படுபவை இவற்றுள் எவை இரண்டு? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "மற்றவர்களை நியாயமாக நடத்துவது|தன்னையும் தன் குடும்பத்தையும் கவனித்துக்கொள்வது|வாரந்தோறும் வழிபாட்டுத் தலத்திற்குச் செல்வது|ஓர் அரசியல் கட்சியின் உறுப்பினராவது", "பொறுப்புகளில் சட்டத்தைக் கடைப்பிடித்தல், பிறரின் உரிமைகளை மதித்தல், மக்களை நியாயமாக நடத்துதல், தன்னையும் குடும்பத்தையும் கவனித்தல், வாழும் பகுதியைப் பராமரித்தல் ஆகியவை அடங்கும்."],
  1008: ["இந்த மொழி விருப்பங்களில் எதில் ஒருவர் Life in the UK தேர்வு எழுதலாம்?", "ஆங்கிலம், Welsh அல்லது Scottish Gaelic|ஆங்கிலம் மட்டும்|ஏதேனும் அதிகாரப்பூர்வ EU மொழி|ஆங்கிலம் அல்லது பிரெஞ்சு", "இத்தேர்வை ஆங்கிலம், Welsh அல்லது Scottish Gaelic மொழியில் எழுதலாம்."],
  1012: ["குடியுரிமை விழாவில், விசுவாசப் பிரமாணத்தோடு சேர்த்து புதிய குடிமக்கள் வேறு என்ன செய்கிறார்கள்?", "யுகேயின் உரிமைகள், சுதந்திரங்கள், சட்டங்களை மதிப்பதாக உறுதியளிக்கிறார்கள்|ஆயுதப் படையில் சேருவதாக வாக்களிக்கிறார்கள்|ஒரு தொண்டு நிறுவனத்திற்கு நன்கொடை அளிக்கிறார்கள்|பிற அனைத்து குடியுரிமைகளையும் முறையாகத் துறக்கிறார்கள்", "புதிய குடிமக்கள் மன்னருக்கு விசுவாசப் பிரமாணம் எடுத்து, யுகேயின் உரிமைகள், சுதந்திரங்கள், சட்டங்களை மதிப்பதாக உறுதியளிக்கிறார்கள்."],
  1016: ["யுகேயில் அனைவரும் பகிர்ந்துகொள்ளும் உரிமை இவற்றுள் எது?", "நம்பிக்கை மற்றும் மத சுதந்திரம்|வரி செலுத்தாமல் தவிர்க்கும் உரிமை|இலவச வீட்டுவசதிக்கான உரிமை|எந்த வயதிலும் அரசு ஓய்வூதியத்திற்கான உரிமை", "நம்பிக்கை மற்றும் மத சுதந்திரம் யுகேயில் அனைவரும் பெறும் உரிமைகளில் ஒன்று."],
  1020: ["யுகேயில் இவற்றுள் எது உரிமை அல்லது சுதந்திரம் அல்ல, ஒரு பொறுப்பு?", "வரி செலுத்துவது|நியாயமான விசாரணை|அநீதியான பாகுபாட்டிலிருந்து விடுதலை|பேச்சுரிமை", "வரி செலுத்துவது ஒரு பொறுப்பு, சுதந்திரம் அல்ல. உரிமைகளில் பேச்சுரிமை, நம்பிக்கைச் சுதந்திரம், நியாயமான விசாரணை, அநீதியான பாகுபாட்டிலிருந்து விடுதலை ஆகியவை அடங்கும்."],
  1024: ["குடியுரிமை விழாக்களை பொதுவாக யார் ஏற்பாடு செய்கிறார்கள்?", "உள்ளாட்சி அமைப்பு|Houses of Parliament|அரச குடும்பம்|நேரடியாக Home Office, உள்ளூர் ஈடுபாடு இன்றி", "உள்ளாட்சி அமைப்புகள் குடியுரிமை விழாக்களை ஏற்பாடு செய்கின்றன, பொதுவாக விண்ணப்பம் ஒப்புதல் பெற்ற மூன்று மாதங்களுக்குள்."],
  1028: ["நிரந்தரக் குடியிருப்பு அல்லது குடியுரிமைக்கு விண்ணப்பிக்கும் பெரும்பாலானோர் எவை இரண்டைக் காட்ட வேண்டும்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "அவர்கள் ஆங்கிலம் பேசவும் படிக்கவும் முடியும்|யுகே வாழ்க்கையை நன்கு புரிந்துகொண்டுள்ளனர்|யுகேயில் அவர்களுக்குச் சொத்து உள்ளது|அவர்கள் Londonஇல் வாழ்ந்துள்ளனர்", "விண்ணப்பதாரர்கள் ஆங்கிலம் பேசவும் படிக்கவும் முடியும் என்பதையும், யுகே வாழ்க்கை குறித்து நல்ல புரிதல் உள்ளது என்பதையும் காட்ட வேண்டும்."],
  1032: ["'சமூக வாழ்வில் பங்கேற்பு' எவ்வாறு சிறப்பாக விவரிக்கப்படுகிறது?", "பிரிட்டிஷ் வாழ்வின் ஓர் அடிப்படைக் கோட்பாடு|அனைத்து குடியிருப்பாளர்களுக்கும் சட்டக் கடமை|குடிமக்கள் மட்டுமே செய்யக்கூடியது|வேலைவாய்ப்பிற்கான நிபந்தனை", "சமூக வாழ்வில் பங்கேற்பு பிரிட்டிஷ் வாழ்வின் அடிப்படைக் கோட்பாடுகளில் இடம்பெறுகிறது."],
  1036: ["சட்டம் தொடர்பாக யுகேயில் உள்ள ஒவ்வொருவரிடமும் என்ன எதிர்பார்க்கப்படுகிறது?", "அதை மதித்து கடைப்பிடிப்பது|தான் தனிப்பட்ட முறையில் ஒப்புக்கொள்ளும் சட்டங்களை மட்டும் பின்பற்றுவது|பிடிக்காத எந்தச் சட்டத்தையும் நாடாளுமன்றத்திற்குத் தெரிவிப்பது|குடிமகனான பிறகே அதைக் கடைப்பிடிப்பது", "சட்டத்தை மதித்து கடைப்பிடிப்பது யுகேயில் வாழும் அனைவரின் அடிப்படைப் பொறுப்பாகும்."],
  1040: ["யுகே ஒரு ஜனநாயகம் என விவரிக்கப்படுகிறது. நடைமுறையில் அதன் பொருள் என்ன?", "அதிகாரம் மக்களிடம் அல்லது அவர்கள் தேர்ந்தெடுத்த பிரதிநிதிகளிடம் உள்ளது|அதிகாரம் மன்னரிடம் மட்டுமே உள்ளது|அதிகாரம் நீதிமன்றங்களிடம் உள்ளது|அதிகாரம் இராணுவத்திடம் உள்ளது", "ஜனநாயகத்தில் அதிகாரம் மக்களிடம் உள்ளது — நேரடியாகவோ தேர்ந்தெடுக்கப்பட்ட பிரதிநிதிகள் வழியாகவோ."],
  1044: ["நீங்கள் வாழும் இடத்தின் சுற்றுச்சூழலைப் பராமரிப்பது எதற்கு எடுத்துக்காட்டு?", "ஒரு பொறுப்பு|ஓர் உரிமை|குடிமக்களுக்கு மட்டும் ஒதுக்கப்பட்ட சட்டச் சலுகை|விருப்பமான மரியாதை", "நீங்கள் வாழும் பகுதியையும் சுற்றுச்சூழலையும் பராமரிப்பது யுகேயில் வாழ்வதன் பொறுப்புகளில் ஒன்று."],
  1048: ["இவற்றுள் எது பிரிட்டிஷ் வாழ்வின் அடிப்படைக் கோட்பாடுகளில் இல்லை?", "ஒரு குறிப்பிட்ட அரசியல் கட்சிக்கு விசுவாசம்|தனிமனித சுதந்திரம்|ஜனநாயகம்|வெவ்வேறு நம்பிக்கைகள் மீதான சகிப்புத்தன்மை", "கோட்பாடுகள் ஜனநாயகம், சட்டத்தின் ஆட்சி, தனிமனித சுதந்திரம், வெவ்வேறு நம்பிக்கைகள் மீதான சகிப்புத்தன்மை, சமூக வாழ்வில் பங்கேற்பு. ஒரு குறிப்பிட்ட கட்சியை ஆதரிப்பது அவற்றுள் இல்லை."],
  1052: ["நிரந்தரக் குடியிருப்பு அல்லது குடியுரிமைக்கு விண்ணப்பிக்கும் முன் பெரும்பாலானோர் என்ன செய்திருக்க வேண்டும்?", "Life in the UK தேர்வில் தேர்ச்சி பெற்று ஆங்கில மொழித் தேவையை நிறைவேற்றியிருக்க வேண்டும்|யுகேயில் ஒரு வீடு வாங்கியிருக்க வேண்டும்|இராணுவப் பணிக் காலத்தை முடித்திருக்க வேண்டும்|பதிவுசெய்யப்பட்ட அரசியல் கட்சியில் சேர்ந்திருக்க வேண்டும்", "விலக்கு இல்லையெனில் பொதுவாக இரு தேவைகளும் நிறைவேற்றப்பட வேண்டும்."],
  1056: ["யுகேயின் குடியேற்ற வரலாற்றை எவ்வாறு சிறப்பாக விவரிக்கலாம்?", "பன்முகச் சமூகத்தில் புதிதாக வருபவர்களை வரவேற்கும் நீண்ட வரலாறு|அனைத்துக் குடியேற்றத்தையும் ஊக்கமிழக்கச் செய்த வரலாறு|வரலாற்று முன்னுதாரணம் இல்லாத சமீபத்திய நிகழ்வு|முற்றிலும் கடந்த இருபது ஆண்டுகளுக்கு மட்டுப்பட்டது", "Anglo-Saxons, வைக்கிங்குகள் முதல் சமீபத்திய வருகைகள் வரை, குடியேற்றம் பல நூற்றாண்டுகளாகப் பிரிட்டிஷ் சமூகத்தை வடிவமைத்துள்ளது."],
  1060: ["நீங்கள் வாழும் இடத்தின் சுற்றுச்சூழலைப் பாதுகாக்க இவற்றுள் எவை இரண்டு செயல்கள் உதவும்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "வீட்டுக் கழிவுகளை மறுசுழற்சி செய்வது|குறுகிய பயணங்களுக்கு நடப்பது அல்லது சைக்கிள் ஓட்டுவது|பொது பூங்காக்களில் குப்பையை விடுவது|தோட்டத்தில் கழிவுகளை எரிப்பது", "நீங்கள் வாழும் பகுதியைப் பராமரிப்பது யுகேயில் வாழ்வதன் பொறுப்புகளில் ஒன்று."],
  1064: ["United Kingdom எத்தனை நாடுகளால் ஆனது?", "நான்கு|இரண்டு|மூன்று|ஐந்து", "யுகே England, Scotland, Wales, Northern Ireland ஆகியவற்றால் ஆனது."],
  1068: ["எந்த மூன்று நாடுகள் சேர்ந்து Great Britain ஆகின்றன?", "England, Scotland, Wales|England, Scotland, Northern Ireland|England, Wales மட்டும்|யுகேயின் நான்கு நாடுகளும்", "Great Britain என்பது England, Scotland, Wales மட்டுமே. யுகேயில் Northern Irelandஉம் அடங்கும்."],
  1072: ["இவற்றுள் எவை இரண்டு Crown dependencies, யுகேயின் பகுதி அல்ல? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "The Channel Islands|The Isle of Man|The Isle of Wight|Anglesey", "Channel Islands, Isle of Man ஆகியவற்றுக்குத் தனி அரசுகள் உள்ளன; அவை Crown dependencies, யுகேயின் பகுதி அல்ல."],
  1076: ["இவற்றுள் எது யுகேயின் பகுதி அல்ல, ஒரு பிரிட்டிஷ் கடல்கடந்த பகுதி?", "The Falkland Islands|The Isle of Man|Jersey|Guernsey", "Falkland Islands, St Helena போன்ற கடல்கடந்த பகுதிகள் யுகேயுடன் தொடர்புடையவை, ஆனால் அதன் பகுதி அல்ல."],
  1080: ["Cardiff யுகேயின் எந்த நாட்டின் தலைநகரம்?", "Wales|Scotland|Northern Ireland|England", "Cardiff Walesஇன் தலைநகரம்; Senedd (வெல்ஷ் நாடாளுமன்றம்) Cardiff Bayஇல் கூடுகிறது."],
  1084: ["Belfast யுகேயின் எந்த நாட்டின் தலைநகரம்?", "Northern Ireland|Scotland|Wales|England", "Belfast Northern Irelandஇன் தலைநகரம். Northern Ireland Assembly Belfastஇல் உள்ள Stormontஇல் கூடுகிறது."],
  1088: ["Northern Irelandஇன் நிலையை இவற்றுள் எது சிறப்பாக விவரிக்கிறது?", "யுகேயின் பகுதி, ஆனால் Great Britainஇன் பகுதி அல்ல|Great Britainஇன் பகுதி|யுகேயின் பகுதியே அல்ல|ஒரு Crown dependency", "Northern Ireland யுகேயின் பகுதி, ஆனால் Great Britain என்பது England, Scotland, Wales மட்டுமே."],
  1092: ["யுகேயின் எந்த மூன்று பகுதிகளுக்குத் தனித்தனியே devolved நிர்வாகம் உள்ளது?", "Scotland, Wales, Northern Ireland|England, Scotland, Wales|Scotland, England, Northern Ireland|Wales, England, Northern Ireland", "Scotland, Wales, Northern Ireland ஒவ்வொன்றுக்கும் Westminsterஇலிருந்து சில அதிகாரங்கள் மாற்றப்பட்ட devolved அரசு உள்ளது."],
  1096: ["Edinburgh யுகேயின் எந்த நாட்டின் தலைநகரம்?", "Scotland|England|Wales|Northern Ireland", "Edinburgh தலைநகரம்; Scottish Parliament அங்கு Holyroodஇல் கூடுகிறது."],
  1100: ["Isle of Manஇன் நிலை என்ன?", "ஒரு Crown dependency, யுகேயின் பகுதி அல்ல|யுகேயின் பகுதி|Scotlandஇன் பகுதி|ஒரு பிரிட்டிஷ் கடல்கடந்த பகுதி", "Isle of Man தனி அரசு கொண்ட Crown dependency, யுகேயின் பகுதி அல்ல."],
  1104: ["யுகேயின் நீளமான ஆறு எது?", "The Severn|The Thames|The Tyne|The Clyde", "Severn சுமார் 220 மைல்கள் ஓடுகிறது; அதற்கு அடுத்தபடியாக Thames Englandஇன் நீளமான ஆறு."],
  1111: ["இவற்றுள் எது Northern Irelandஇல் உள்ள நகரம் அல்ல?", "Leeds|Belfast|Londonderry|Armagh", "Belfast, Londonderry, Armagh அனைத்தும் Northern Irelandஇன் நகரங்கள். Leeds Englandஇன் நகரம்."],
  1112: ["Britainஇல் வாழ்ந்த முதல் மக்களை எது சிறப்பாக விவரிக்கிறது?", "வேட்டையாடி உணவு சேகரிப்பவர்கள்|விவசாயிகள்|வணிகர்கள்|வீரர்கள்", "Britainஇன் முதல் குடியிருப்பாளர்கள் வேட்டையாடி உணவு சேகரிப்பவர்கள், காலநிலைக்கேற்ப வந்து சென்றவர்கள்."],
  1116: ["Britainஐ ஐரோப்பியக் கண்டத்துடன் இணைத்த நிலப்பாலம் சுமார் எத்தனை ஆண்டுகளுக்கு முன்பு நீரில் மூழ்கியது?", "சுமார் 10,000 ஆண்டுகளுக்கு முன்பு|சுமார் 1,000 ஆண்டுகளுக்கு முன்பு|சுமார் 100,000 ஆண்டுகளுக்கு முன்பு|சுமார் 500 ஆண்டுகளுக்கு முன்பு", "சுமார் 10,000 ஆண்டுகளுக்கு முன்பு கண்டத்திற்கான நிலப்பாலம் நீரில் மூழ்கியது, Britain நிரந்தரமாகத் தீவானது."],
  1122: ["தொல்லியலில் ஆர்வமுள்ள நண்பர் Orkneyஇன் எந்த தளம் கற்கால வாழ்வு எப்படி இருந்தது என்பதைக் காட்டுகிறது எனக் கேட்கிறார். என்ன சொல்வீர்கள்?", "Skara Brae|Stonehenge|Maiden Castle|Hadrian's Wall", "Orkneyஇல் உள்ள Skara Brae தொல்லியலாளர்களுக்குக் கற்கால வாழ்வின் விரிவான சித்திரத்தைத் தருகிறது."],
  1124: ["Dorsetஇல் உள்ள Maiden Castle எத்தகைய தளத்திற்கு எடுத்துக்காட்டு?", "இரும்புக் கால மலைக்கோட்டை|ரோமானிய villa|நார்மன் கோட்டை|வைக்கிங் குடியிருப்பு", "Maiden Castle ஒரு பெரிய இரும்புக் கால மலைக்கோட்டை. வெண்கலக் கால மக்கள் வட்ட வீடுகளையும் புதைமேடுகளையும் கட்டினர்."],

  /* ---------- DOUBLES — CHAPTER 3 (History) ---------- */
  1128: ["Julius Caesar Britain மீது தோல்வியுற்ற படையெடுப்பை முயன்ற ஆண்டு எது?", "55 BC|AD 43|AD 122|AD 410", "Caesarஇன் 55 BC தாக்குதல் தோல்வியடைந்தது. வெற்றிகரமான ரோமானியப் படையெடுப்பு AD 43இல் பேரரசர் Claudius தலைமையில் நிகழ்ந்தது."],
  1135: ["Britainஇன் ஆரம்ப வரலாற்றில் இவர்களுள் யார் கிளர்ச்சியையோ அரசுகளின் ஒன்றிணைப்பையோ வழிநடத்தவில்லை?", "Julius Caesar|Boudicca|Alfred the Great|Kenneth MacAlpin", "Boudicca ரோமுக்கு எதிராகக் கிளர்ச்சி நடத்தினார், Alfred வைக்கிங்குகளைத் தோற்கடித்தார், Kenneth MacAlpin Scotlandஐ ஒன்றிணைத்தார். Julius Caesar ஒரு ரோமானிய படையெடுப்பாளர், பிரிட்டிஷ் தலைவர் அல்ல."],
  1136: ["Hadrian's Wallஇன் முக்கிய நோக்கம் என்ன?", "வடக்கிலிருந்து Picts போன்ற பழங்குடிகளைத் தடுப்பது|Wales எல்லையைக் குறிப்பது|வைக்கிங் தாக்குதல்களிலிருந்து பாதுகாப்பது|Londonஐப் பாதுகாப்பது", "ரோமானிய Britainஇன் வடக்கு எல்லையைப் பாதுகாக்க AD 122இல் பேரரசர் Hadrian இச்சுவரைக் கட்ட ஆணையிட்டார்."],
  1143: ["AD 410இல் ரோமானியர்கள் Britainஐ விட்டு வெளியேறியதுடன் தொடர்புடைய காரணம் இவற்றுள் எது அல்ல?", "அவர்கள் வைக்கிங்குகளால் தோற்கடிக்கப்பட்டனர்|தங்கள் பேரரசின் பிற பகுதிகளைப் பாதுகாக்க வேண்டியிருந்தது|ரோமானியப் பேரரசின் பிற இடங்களில் அழுத்தம் அதிகரித்தது|Britainஇல் ரோமானிய ஆட்சி முறையாக முடிவுற்றது", "தங்கள் பேரரசின் பிற பகுதிகளைப் பாதுகாக்க ரோமானியர்கள் AD 410இல் வெளியேறினர் — வைக்கிங்குகள் AD 789 வரை Britain மீது தாக்குதல் நடத்தவில்லை, ரோம் சென்ற நீண்ட காலத்திற்குப் பிறகு."],
  1144: ["ரோமானியர்கள் சென்ற பிறகு Britain மீது படையெடுத்து அங்கே குடியேறிய மக்கள் யார்?", "Jutes, Angles, Saxons|Normans, Franks|Picts, Scots மட்டும்|ஸ்பானியர், போர்த்துகீசியர்", "Anglo-Saxons — Jutes, Angles, Saxons — வட ஐரோப்பாவிலிருந்து வந்து Britainஇல் குடியேறினர்."],
  1148: ["East Angliaஇல் உள்ள Sutton Hoo யாருடைய புதைவிடம்?", "ஓர் Anglo-Saxon மன்னரின்|ஒரு ரோமானியத் தளபதியின்|ஒரு வைக்கிங் தலைவரின்|ஒரு நார்மன் வீரரின்", "Sutton Hooஇல் உள்ள கப்பல் புதைவிடம் ஓர் Anglo-Saxon மன்னர் அல்லது பெரும் வீரருடையது என நம்பப்படுகிறது."],
  1154: ["597இல் Anglo-Saxonsஐக் கிறித்தவ மதத்திற்கு மாற்ற ரோமிலிருந்து யார் அனுப்பப்பட்டார் என நண்பர் கேட்கிறார். அவர் யார்?", "St Augustine|St Columba|St Patrick|St Andrew", "St Augustine 597இல் வந்து முதல் Archbishop of Canterbury ஆனார்."],
  1159: ["இந்தத் தேதிகளில் எது Britainஇன் வைக்கிங்குகளுடன் தொடர்பில்லாதது?", "AD 1215|AD 789|கிழக்கிலும் வடக்கிலும் Danelaw காலகட்டம்|மன்னர் Alfredஇன் பிற்கால வெற்றிகள்", "வைக்கிங்குகள் AD 789இல் முதலில் தாக்கி, பின்னர் Alfred the Great தோற்கடிக்கும் வரை Danelawஐக் கட்டுப்படுத்தினர். AD 1215 Magna Cartaஇன் ஆண்டு, வைக்கிங்குகளுடன் தொடர்பில்லாதது."],
  1162: ["வைக்கிங்குகளைத் தோற்கடித்ததற்காக எந்த Anglo-Saxon மன்னர் நினைவுகூரப்படுகிறார் என நண்பர் கேட்கிறார். அவர் யார்?", "Alfred the Great|Harold|Cnut|William of Normandy", "மன்னர் Alfred the Great வைக்கிங்குகளைத் தோற்கடித்தார், எனினும் அவர்கள் கிழக்கிலும் வடக்கிலும் Danelawஐக் கட்டுப்பாட்டில் வைத்திருந்தனர்."],
  1167: ["Britainஇன் ஆரம்ப வரலாற்றில் இவர்களுள் யார் அரசுகளை ஒன்றிணைக்கவோ மக்களை வெற்றிக்கு வழிநடத்தவோ இல்லை?", "Macbeth|Kenneth MacAlpin|Alfred the Great|Robert the Bruce", "Kenneth MacAlpin Picts, Scotsஐ ஒன்றிணைத்தார், Alfred the Great வைக்கிங்குகளைத் தோற்கடித்தார், Robert the Bruce Bannockburnஇல் வென்றார். Macbeth பிற்கால ஸ்காட்டிஷ் மன்னர், அரசை ஒன்றிணைத்த பெருமை அவருக்கு இல்லை."],
  1170: ["1066இல் எந்தப் புகழ்பெற்ற போர் நடந்தது என நண்பர் கேட்கிறார். பதில் என்ன?", "The Battle of Hastings|The Battle of Bosworth Field|The Battle of Bannockburn|The Battle of Agincourt", "1066இல் Hastingsஇல் Normandy பிரபு William மன்னர் Haroldஐத் தோற்கடித்தார் — England மீதான கடைசி வெற்றிகரமான வெளிநாட்டுப் படையெடுப்பு."],
  1175: ["Bayeux Tapestry பற்றி இவற்றுள் எது உண்மை அல்ல?", "இது ஒரு எழுதப்பட்ட சட்ட ஆவணம்|இது ஒரு பின்னலாடை|இது நார்மன் வெற்றியைச் சித்தரிக்கிறது|இது இன்னும் Franceஇல் காட்சிக்கு உள்ளது", "Bayeux Tapestry ஒரு பின்னலாடை, எழுதப்பட்ட சட்ட ஆவணம் அல்ல — இக்காலகட்டத்தின் எழுதப்பட்ட நிலக் கணக்கெடுப்பு Domesday Book."],
  1178: ["1086இல் William Englandஇன் பெரும் கணக்கெடுப்பை ஏன் ஆணையிட்டார் என நண்பர் கேட்கிறார். அது எதற்காக?", "England முழுவதும் யார் நிலமும் கால்நடையும் வைத்திருந்தனர் எனப் பதிவு செய்ய|அவரது ஆட்சியை எத்தனை பேர் ஆதரிக்கின்றனர் எனக் கணக்கிட|புதிய சாலை வலையமைப்பைத் திட்டமிட|ஒவ்வொரு நகரமும் எத்தனை வீரர்களைத் தர முடியும் என மதிப்பிட", "England முழுவதும் யார் நிலமும் கால்நடையும் வைத்திருந்தனர் என்பதைப் பதிவு செய்ய 1086இல் William Domesday Bookஐ ஆணையிட்டார்."],
  1183: ["இந்தக் கோட்டைகளில் எது Edward Iஇன் வெல்ஷ் கோட்டை வளையத்தின் பகுதி அல்ல?", "Bosworth Castle|Conwy Castle|Caernarfon Castle|Harlech Castle", "Walesஐக் கைப்பற்றிய பிறகு Edward I Conwy, Caernarfon, Harlech உள்ளிட்ட கோட்டைகளைக் கட்டினார். Bosworth ஒரு கோட்டை அல்ல — அது Wars of the Rosesஐ முடித்த 1485 போரின் இடம்."],
  1186: ["Robert the Bruce தலைமையில் எந்தப் போர் Scotlandஇன் சுதந்திரத்தைப் பல நூற்றாண்டுகளுக்கு உறுதி செய்தது என நண்பர் கேட்கிறார். எது?", "Bannockburn|Culloden|Agincourt|Naseby", "1314இல் Robert the Bruce தலைமையில் Scots Bannockburnஇல் வெற்றி பெற்றனர், Scotland பல நூற்றாண்டுகள் சுதந்திரமாக இருந்தது."],
  1191: ["இந்த மன்னர்களில் யார் Hundred Years War காலத்தில் ஆட்சி செய்யவில்லை?", "Henry VIII|Henry V|Edward III|Richard II", "Henry V, Edward III, Richard II அனைவரும் Hundred Years War (1337-1453) காலத்தில் ஆட்சி செய்தனர். Henry VIII 16ஆம் நூற்றாண்டில், அது முடிந்த நீண்ட காலத்திற்குப் பிறகு ஆட்சி செய்தார்."],
  1194: ["Hundred Years Warஐ இழந்த பிறகும் England எந்த பிரெஞ்சு நகரத்தை வைத்திருந்தது என நண்பர் கேட்கிறார். எது?", "Calais|Paris|Rouen|Bordeaux", "Calais துறைமுகத்தைத் தவிர England தனது அனைத்து பிரெஞ்சுப் பகுதிகளையும் இழந்தது; Calaisஉம் 1558இல் இழக்கப்பட்டது."],
  1199: ["1348இன் Black Deathஇன் விளைவு இவற்றுள் எது அல்ல?", "தொழிலாளர்களின் திடீர் உபரியும் ஊதியக் குறைவும்|தொழிலாளர் பற்றாக்குறை|செல்வமிக்க நடுத்தர வர்க்கத்தின் வளர்ச்சி|மக்கள்தொகையில் சுமார் மூன்றில் ஒரு பங்கின் மரணம்", "Black Death தொழிலாளர் பற்றாக்குறையை ஏற்படுத்தியது, உபரியை அல்ல — குறைவான தொழிலாளர்கள் என்பதால் உயிர் பிழைத்தவர்கள் அதிக ஊதியம் கோர முடிந்தது, இது செல்வமிக்க நடுத்தர வர்க்கம் உருவாக உதவியது."],
  1202: ["1215இல் மன்னர் John எதை ஏற்க நிர்ப்பந்திக்கப்பட்டார் என நண்பர் கேட்கிறார். அது என்ன, என்ன செய்தது?", "Magna Carta, இது மன்னராக அவரது அதிகாரத்தை வரம்பிட்டது|Scotlandஉடன் போரை முடிக்கும் ஒப்பந்தம்|முதல் ஆங்கில பைபிள்|புதிய நாணய முறை", "1215இல் மன்னர் John Magna Cartaவை ('பெரும் சாசனம்') ஏற்க நிர்ப்பந்திக்கப்பட்டார், இதனால் மன்னரும் சட்டத்திற்கு உட்பட்டவர் என நிலைநாட்டப்பட்டது."],
  1207: ["இந்தக் குடும்பங்களில் எது Wars of the Rosesஇல் ஈடுபடவில்லை?", "Tudor, போர் தொடங்கும் முன்|Lancaster|York|சிவப்பு ரோஜா, வெள்ளை ரோஜா அணிகள்", "Wars of the Roses Lancaster, York இடையே நடந்தது. Tudor வம்சம் அதன் பிறகே தொடங்கியது, Henry Tudor 1485இல் Bosworth Fieldஇல் வென்றபோது."],
  1210: ["Henry Tudor மன்னர் Henry VII ஆக எந்தப் போர் வழிவகுத்தது என நண்பர் கேட்கிறார். எது?", "The Battle of Bosworth Field|The Battle of Hastings|The Battle of the Boyne|The Battle of Agincourt", "1485இல் Bosworth Fieldஇல் Richard III கொல்லப்பட்டார், Henry Tudor Henry VII ஆகி Tudor வம்சத்தை நிறுவினார்."],
  1215: ["William Caxton பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் The Canterbury Tales எழுதினார்|அவர் Englandஇல் முதல் அச்சகத்தை நிறுவினார்|அவர் 1476இல் பணியாற்றினார்|அவரது பணி புத்தகங்களை மிகவும் பரவலாகக் கிடைக்கச் செய்தது", "William Caxton Englandஇற்கு அச்சுத்தொழிலைக் கொண்டுவந்தார் — The Canterbury Tales எழுதியவர் Geoffrey Chaucer, முந்தைய எழுத்தாளர், அவரது படைப்பை Caxton பின்னர் அச்சிட்டார்."],
  1218: ["Canterbury செல்லும் யாத்திரிகர்கள் பற்றிய புகழ்பெற்ற கவிதைத் தொகுப்பை யார் எழுதினார் என நண்பர் கேட்கிறார். அவர் யார்?", "Geoffrey Chaucer|William Shakespeare|John Milton|William Caxton", "Chaucerஇன் Canterbury Tales, Canterbury செல்லும் யாத்திரிகர் குழு பற்றிய கவிதைத் தொகுப்பு."],
  1223: ["இவர்களுள் யார் Henry VIIIஇன் ஆறு மனைவியரில் ஒருவர் அல்ல?", "Mary I|Catherine of Aragon|Anne Boleyn|Catherine Parr", "Henry VIIIஇன் ஆறு மனைவியர் Catherine of Aragon, Anne Boleyn, Jane Seymour, Anne of Cleves, Catherine Howard, Catherine Parr. Mary I அவரது மகள், மனைவி அல்ல."],
  1226: ["Henry VIII ஏன் Church of Englandஐ உருவாக்கினார் என நண்பர் கேட்கிறார். சரியான காரணம் என்ன?", "Catherine of Aragonஉடனான அவரது திருமணத்தை ரத்து செய்ய போப் மறுத்தார்|அவர் France மீது படையெடுக்க விரும்பினார்|தேவாலயச் சடங்குகளில் பயன்படுத்தப்பட்ட லத்தீன் அவருக்குப் பிடிக்கவில்லை|அவர் வரிவிதிப்பை ஒழிக்க விரும்பினார்", "மீண்டும் திருமணம் செய்ய Henry தன்னையே தலைவராகக் கொண்டு Church of Englandஐ நிறுவினார், இதுவே ஆங்கில சீர்திருத்தத்தின் தொடக்கம்."],
  1231: ["Mary I பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் ஓர் உறுதியான புராட்டஸ்டன்ட்|அவர் Henry VIIIஇன் மகள்|அவர் புராட்டஸ்டன்ட்களை ஒடுக்கினார்|அவர் 'Bloody Mary' என அறியப்படுகிறார்", "Mary I ஒரு பக்திமிக்க கத்தோலிக்கர், புராட்டஸ்டன்ட் அல்ல — அதனாலேயே அவர் தமது ஆட்சிக்காலத்தில் புராட்டஸ்டன்ட்களை ஒடுக்கினார்."],
  1234: ["Philip II அனுப்பிய ஸ்பானியப் படையெடுப்புக் கப்பற்படையை England எந்த ஆண்டு தோற்கடித்தது என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1588|1485|1666|1707", "England மீது படையெடுக்க Philip II அனுப்பிய Spanish Armadaவை ஆங்கிலக் கப்பற்படை 1588இல் தோற்கடித்தது."],
  1239: ["William Shakespeare பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் Londonஇல் பிறந்தார்|அவர் Stratford-upon-Avonஇல் பிறந்தார்|அவர் Globe அரங்கில் பணியாற்றினார்|அவர் Londonஇல் நாடக ஆசிரியராகப் பணியாற்றினார்", "Shakespeare Stratford-upon-Avonஇல் பிறந்தார், Londonஇல் அல்ல — எனினும் பின்னர் Londonஇல் Globe அரங்கில் பணியாற்றினார்."],
  1242: ["1603க்குப் பிறகு இரு நாடுகளும் முறையாக இணையாமலேயே Scotland, England இரண்டையும் ஆட்சி செய்த மன்னர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Scotlandஇன் James VI (Englandஇன் James I)|Charles I|Henry VII|William III", "1603இன் Union of the Crowns England, Scotlandஐ ஒரே மன்னரின் கீழ் கொண்டுவந்தது, எனினும் அவை தனி நாடுகளாகவே இருந்தன."],
  1247: ["இந்தச் சொற்களில் எது English Civil Warஇன் ஒரு பக்கத்தை விவரிக்கவில்லை?", "Jacobites|Cavaliers|Roundheads|Royalists", "உள்நாட்டுப் போரில் Cavaliers (Royalists) Roundheads (Parliamentarians) உடன் போரிட்டனர். Jacobites நாடுகடத்தப்பட்ட James II மற்றும் அவரது வாரிசுகளின் ஆதரவாளர்கள், பிற்கால மோதலில்."],

  /* ---------- DOUBLES — CHAPTER 3 (continued) ---------- */
  1250: ["Charles I எந்த ஆண்டு தூக்கிலிடப்பட்டு England குடியரசானது என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1649|1660|1666|1688", "1649இல் Charles I தூக்கிலிடப்பட்டார், England Commonwealth எனும் குடியரசானது."],
  1255: ["Oliver Cromwell பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் Englandஇன் மன்னராக முடிசூட்டப்பட்டார்|அவர் Lord Protector பட்டத்துடன் ஆட்சி செய்தார்|அவர் 1658இல் இறந்தார்|அவரது மகன் Richard பின்தொடர்ந்தார், ஆனால் திறம்பட ஆட்சி செய்ய இயலவில்லை", "Cromwell Lord Protectorஆக ஆட்சி செய்தார், மன்னராக அல்ல — இக்காலகட்டத்தில் England மன்னரற்ற குடியரசாக இருந்தது."],
  1258: ["Cromwellஇன் குடியரசுக்குப் பிறகு Charles II தலைமையில் எந்த ஆண்டு முடியாட்சி மீட்டெடுக்கப்பட்டது என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1660|1649|1688|1707", "1660இல் நாடாளுமன்றம் Charles IIஐத் திரும்ப அழைத்தது, இது Restoration என அறியப்படுகிறது."],
  1263: ["1660களில் இவற்றுள் எது Londonஐத் தாக்கவில்லை?", "The Black Death|The Great Plague|The Great Fire|St Paul's உட்பட மறுகட்டுமானம் தேவைப்பட்ட பரவலான அழிவு", "Great Plague (1665), Great Fire (1666) 1660களில் Londonஐத் தாக்கின. Black Death மிக முந்தைய தொற்றுநோய், 1348இல்."],
  1266: ["1688இன் Glorious Revolutionஇன் விளைவாக யார் மன்னரானார் என நண்பர் கேட்கிறார். அவர் யார்?", "William of Orange|Charles II|George I|James II, அவர் தமது அரியணையைத் தக்கவைத்தார்", "William of Orangeஉம் அவரது மனைவி Mary, James IIஇன் மகளும், Englandஇல் போரின்றி அரியணை ஏற்றனர்."],
  1271: ["1689இன் Bill of Rights இவற்றுள் எதை நிலைநாட்டவில்லை?", "அனைத்துப் பெரியவர்களுக்கும் வாக்குரிமை|மன்னருக்கு நாடாளுமன்றத்தின் ஒப்புதல் தேவை என்பது|வழக்கமான நாடாளுமன்றத் தேவை|அரச அதிகாரத்திற்கான வரம்புகள்", "Bill of Rights அரச அதிகாரத்தை வரம்பிட்டு வழக்கமான நாடாளுமன்றங்களைக் கோரியது — அனைத்துப் பெரியவர்களுக்கும் வாக்குரிமை மிகப் பிறகு, 20ஆம் நூற்றாண்டில் வந்தது."],
  1274: ["1707இன் Act of Union எதை இணைத்தது, என்ன உருவாக்கியது என நண்பர் கேட்கிறார். பதில் என்ன?", "Scotland, Englandஐ ஒரே நாடாளுமன்றத்தின் கீழ் இணைத்து Kingdom of Great Britainஐ உருவாக்கியது|England, Irelandஐ இணைத்து United Kingdomஐ உருவாக்கியது|Commonwealthஐ உருவாக்கியது|England, Walesஐ மட்டும் இணைத்தது", "1707இல் Scotland, England ஒரே நாடாளுமன்றத்தின் கீழ் இணைந்து Kingdom of Great Britain ஆயின."],
  1279: ["இவர்களுள் யார் யுகேயின் Prime Ministerஆகப் பணியாற்றவில்லை?", "Oliver Cromwell|Sir Robert Walpole|Winston Churchill|Margaret Thatcher", "Walpole, Churchill, Thatcher அனைவரும் Prime Ministerஆக இருந்தனர். Oliver Cromwell முந்தைய குடியரசில் Lord Protectorஆக ஆட்சி செய்தார், Prime Minister பதவி உருவாகும் முன்பே."],
  1282: ["1746இல் Bonnie Prince Charlieஇன் போராட்டத்தை எந்தப் போர் முடித்தது என நண்பர் கேட்கிறார். எது?", "Culloden|Bannockburn|Naseby|Bosworth Field", "1746இல் Cullodenஇல் Bonnie Prince Charlieஇன் படைகள் நசுக்கப்பட்டன; பின்னர் அவர் ஐரோப்பாவுக்குத் தப்பிச் சென்றார்."],
  1287: ["இவற்றுள் எது Scottish Enlightenmentஉடன் தொடர்புடையது அல்ல?", "James Wattஇன் நீராவி இயந்திரம்|Adam Smith|David Hume|தத்துவம், அறிவியலில் புதிய கருத்துகள்", "Adam Smith, David Hume அறிவொளிக் காலத்தின் முன்னணிச் சிந்தனையாளர்கள். James Wattஇன் நீராவி இயந்திரம் பிற்கால தொழிற்புரட்சிக்கு உரியது, எனினும் இரண்டும் ஸ்காட்டிஷ் சாதனைகள்."],
  1290: ["தொழிற்புரட்சிக்கு ஆற்றல் அளிக்க நீராவி இயந்திரத்தை மேம்படுத்திய பெருமை யாருக்கு என நண்பர் கேட்கிறார். அவர் யார்?", "James Watt|Richard Arkwright|Isaac Newton|Isambard Kingdom Brunel", "ஸ்காட்லாந்தைச் சேர்ந்த James Watt, தொழிற்சாலைகளிலும் சுரங்கங்களிலும் இயந்திரங்களை இயக்கும் வகையில் நீராவி இயந்திரத்தை மேம்படுத்தினார்."],
  1295: ["British Empireஇல் அடிமைத்தனமும் அடிமை வணிகமும் ஒழிக்கப்பட்டது பற்றி இவற்றுள் எது சரியல்ல?", "அடிமை வணிகமும் அடிமைத்தனமும் இரண்டுமே 1807இல் ஒழிக்கப்பட்டன|அடிமை வணிகம் 1807இல் ஒழிக்கப்பட்டது|பேரரசு முழுவதும் அடிமைத்தனம் 1833இல் ஒழிக்கப்பட்டது|William Wilberforce அடிமை வணிகத்திற்கு எதிராகப் பிரச்சாரம் செய்தார்", "அடிமை வணிகம் 1807இல் ஒழிக்கப்பட்டது, ஆனால் அடிமைத்தனம் 1833இன் Emancipation Act வரை பேரரசில் தொடர்ந்தது — இவை இரு வெவ்வேறு தேதிகள்."],
  1298: ["Britainஇன் அடிமை வணிக ஈடுபாட்டை முடித்ததுடன் மிக நெருக்கமாகத் தொடர்புடைய சாரி யார் என நண்பர் கேட்கிறார். அவர் யார்?", "William Wilberforce|Robert Walpole|William Gladstone|Robert Peel", "இவாஞ்சலிக்கல் கிறித்தவரான William Wilberforce அடிமைத்தனத்திற்கு எதிரான நாடாளுமன்றப் பிரச்சாரத்தை வழிநடத்தினார்."],
  1303: ["Admiral Nelson பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் Waterlooஇல் பிரிட்டிஷ் தரைப்படைகளுக்குத் தலைமை தாங்கினார்|அவர் Battle of Trafalgarஇல் இறந்தார்|அவரது முதன்மைக் கப்பல் HMS Victory|Trafalgar Square ஓரளவு அவரது நினைவாகப் பெயரிடப்பட்டது", "Nelson ஒரு கடற்படைத் தளபதி, 1805இல் Trafalgarஇல் இறந்தார் — 1815இன் தரைப்போரான Waterlooக்கு Duke of Wellington தலைமை தாங்கினார்."],
  1306: ["1815இல் Waterlooஇல் Napoleonஐ வெல்ல Britainஐ யார் வழிநடத்தினார் என நண்பர் கேட்கிறார். அவர் யார்?", "The Duke of Wellington|Admiral Nelson|Sir Robert Walpole|William Pitt", "பின்னர் Prime Minister ஆன Duke of Wellington, Iron Duke என அறியப்பட்டார், Waterlooஇல் தலைமை தாங்கினார்."],
  1311: ["அரசி Victoriaஇன் ஆட்சி பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது 20 ஆண்டுகளுக்கும் குறைவாக நீடித்தது|அது 1837இல் தொடங்கியது|அது 1901இல் முடிந்தது|அது 64 ஆண்டுகள் நீடித்தது", "அரசி Victoria 1837 முதல் 1901 வரை 64 ஆண்டுகள் ஆட்சி செய்தார் — 20 ஆண்டுகளை விட மிக அதிகம்."],
  1314: ["Florence Nightingale எந்தப் போருடன் மிக நெருக்கமாகத் தொடர்புடையவர் என நண்பர் கேட்கிறார். எது?", "The Crimean War|The First World War|The Boer War|The Napoleonic Wars", "Florence Nightingale Crimean War காலத்தில் Scutariஇல் செவிலியராகப் பணியாற்றி, பின்னர் Londonஇல் ஒரு செவிலியர் பள்ளியை நிறுவினார்."],
  1319: ["Emmeline Pankhurst பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் Crimean Warஇன் செவிலியர்|அவர் 1889இல் Women's Franchise Leagueஐ நிறுவினார்|அவர் suffragette இயக்கத்தை வழிநடத்தினார்|அவரது பிரச்சாரம் மேலும் மேலும் தீவிரமான உத்திகளைக் கையாண்டது", "Emmeline Pankhurst பெண்களின் வாக்குரிமைக்கான suffragette பிரச்சாரத்தை வழிநடத்தினார். Crimean Warஇல் செவிலியர் பணி முந்தைய தலைமுறையின் Florence Nightingaleஇன் சாதனை."],
  1322: ["ஆண்களுக்கு நிகரான அதே நிபந்தனைகளில் பெண்கள் இறுதியாக எப்போது வாக்குரிமை பெற்றனர் என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1928|1918|1945|1969", "சொத்துள்ள 30 வயதுக்கு மேற்பட்ட பெண்கள் 1918இல் வாக்குரிமை பெற்றனர்; வாக்களிக்கும் வயதில் முழு சமத்துவம் 1928இல் வந்தது."],
  1327: ["இந்நிகழ்வுகளில் எது First World Warஇன் தொடக்கத்துடன் தொடர்பில்லாதது?", "1939இல் Poland மீதான படையெடுப்பு|Archduke Franz Ferdinand படுகொலை|1914இல் Sarajevoஇல் நிகழ்வுகள்|ஐரோப்பிய வல்லரசுகளைப் போருக்கு இழுத்த கூட்டணிச் சங்கிலி", "Franz Ferdinand படுகொலைக்குப் பிறகு 1914இல் First World War தொடங்கியது. 1939இல் Poland படையெடுப்பு Second World Warஐத் தூண்டியது."],
  1330: ["1916இல் Sommeஇன் முதல் நாளில் சுமார் எத்தனை பிரிட்டிஷ் இழப்புகள் என நண்பர் கேட்கிறார். மிக நெருக்கமான எண் எது?", "சுமார் 60,000|சுமார் 6,000|சுமார் 600|சுமார் 600,000", "Somme First World Warஇன் மிகக் கொடூரமான போர்களில் ஒன்று, முதல் நாளில் மட்டும் சுமார் 60,000 பிரிட்டிஷ் இழப்புகள்."],
  1335: ["இந்தத் தேதிகளில் எது First World Warஉடன் தொடர்பில்லாதது?", "8 May 1945|11 November 1918|1914, போர் தொடங்கியபோது|'பதினொன்றாம் மாதத்தின் பதினொன்றாம் நாளின் பதினொன்றாம் மணி'", "First World War 11 November 1918இல் முடிந்தது. 8 May 1945 என்பது VE Day, ஐரோப்பாவில் Second World Warஇன் முடிவைக் குறிக்கிறது."],
  1338: ["1922இல் நாடு பிரிக்கப்பட்டபோது தெற்கு Irelandஇல் என்ன உருவாக்கப்பட்டது என நண்பர் கேட்கிறார். அது எவ்வாறு அழைக்கப்பட்டது?", "The Irish Free State|The Republic of Ulster|The Kingdom of Ireland|The Irish Commonwealth", "1922இல் தெற்கில் Irish Free State உருவானது; வடக்கில் ஆறு கவுண்டிகள் யுகேயில் தங்கின."],
  1343: ["Winston Churchill பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் National Health Serviceஐ நிறுவினார்|அவர் 1940இல் Prime Minister ஆனார்|அவரது போர்க்கால உரைகளுக்காக அவர் நினைவுகூரப்படுகிறார்|அவர் Second World Warஇன் பெரும்பகுதியில் Britainஐ வழிநடத்தினார்", "Churchill Prime Ministerஆக Second World Warஇல் Britainஐ வழிநடத்தினார். NHS 1948இல் சுகாதார அமைச்சர் Aneurin Bevanஆல், வேறொரு அரசின் கீழ் நிறுவப்பட்டது."],
  1346: ["1940இல் Dunkirkஇல் நூற்றுக்கணக்கான சிறு குடிமக்கள் படகுகள் ஈடுபட்ட நிகழ்வு என்ன என நண்பர் கேட்கிறார். அது என்ன?", "கடற்கரையிலிருந்து 3,00,000க்கும் மேற்பட்ட வீரர்களை வெளியேற்றியது|Franceஇன் வெற்றிகரமான படையெடுப்பு|ஜெர்மன் கப்பற்படை மீதான கடற்படை வெற்றி|ஓர் அமைதி ஒப்பந்தம் கையெழுத்திடல்", "1940இல் நூற்றுக்கணக்கான குடிமக்களின் படகுகள் Dunkirk கடற்கரையிலிருந்து பிரிட்டிஷ், பிரெஞ்சு வீரர்களை மீட்க உதவின."],
  1351: ["Battle of Britainஇல் RAFக்காக இந்த விமானங்களில் எது முதன்மைப் பங்கு வகிக்கவில்லை?", "Lancaster குண்டுவீச்சு விமானம்|The Spitfire|The Hurricane|பிரிட்டிஷ் வானைக் காக்கும் போர் விமானங்கள்", "RAFஇன் Spitfire, Hurricane விமானங்களே Battle of Britainஐ வென்றன. Lancaster ஒரு கனரக குண்டுவீச்சு விமானம், போரின் பிற்பகுதியில் பயன்படுத்தப்பட்டது."],
  1354: ["மேற்கு ஐரோப்பாவை விடுவிக்கத் தொடங்க நேச நாட்டுப் படைகள் எந்தத் தேதியில் Normandyஇல் இறங்கின என நண்பர் கேட்கிறார். எந்தத் தேதி?", "6 June 1944|8 May 1945|3 September 1939|11 November 1918", "6 June 1944இன் D-Day இறங்குதல்கள் நாஜி ஆக்கிரமிப்பிலிருந்து மேற்கு ஐரோப்பாவின் விடுதலையைத் தொடங்கின."],
  1359: ["VE Day பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Japanஇன் சரணாகதியைக் குறித்தது|அது 8 May 1945இல் வந்தது|அது ஐரோப்பாவில் வெற்றியைக் குறித்தது|அதற்குப் பிறகும் Japanக்கு எதிரான போர் தொடர்ந்தது", "VE Day 8 May 1945இல் ஐரோப்பாவில் வெற்றியைக் குறித்தது — Japan பின்னர், August 1945இல்தான் சரணடைந்தது."],
  1362: ["எந்த ஸ்காட்டிஷ் அறிவியலாளர் penicillinஐக் கண்டுபிடித்தார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Alexander Fleming|Sir Frank Whittle|Alan Turing|James Watt", "ஸ்காட்டிஷ் அறிவியலாளர் Alexander Fleming 1928இல் penicillinஐக் கண்டுபிடித்தார், பின்னர் அது நுண்ணுயிர்க்கொல்லியாக உருவாக்கப்பட்டது."],
  1367: ["Beveridge Report பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதை Aneurin Bevan எழுதினார்|அது 1942இல் வெளியிடப்பட்டது|அதை William Beveridge எழுதினார்|அது நவீன நலன்புரி அரசை முன்மொழிந்தது", "அறிக்கையை William Beveridge எழுதினார்; Aneurin Bevan வேறொரு ஆளுமை, அவர் பின்னர் 1948இல் NHS உருவாக்கத்தை வழிநடத்தினார்."],

  /* ---------- DOUBLES — CHAPTER 3 (continued) ---------- */
  1370: ["1948இல் NHSஐத் தொடங்கிய பெருமை எந்த அமைச்சருக்கு என நண்பர் கேட்கிறார். அவர் யார்?", "Aneurin Bevan|William Beveridge|Winston Churchill|Clement Attlee, எனினும் Bevan நேரடியாக வழிநடத்தினார்", "சுகாதார அமைச்சர் Aneurin Bevan 1948இல் NHSஐத் தொடங்கினார், பயன்படுத்தும் இடத்தில் அனைவருக்கும் இலவச சுகாதாரப் பராமரிப்பு வழங்கப்பட்டது."],
  1375: ["Empire Windrush பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது 1948இல் Indiaஇலிருந்து வந்தது|அது West Indiesஇலிருந்து தொழிலாளர்களைக் கொண்டுவந்தது|அது 1948இல் வந்தது|போருக்குப் பிந்தைய தொழிலாளர் பற்றாக்குறை பயணிக்க அழைப்பை ஏற்படுத்தியது", "Empire Windrush 1948இல் West Indiesஇலிருந்து தொழிலாளர்களைக் கொண்டுவந்தது, போருக்குப் பிந்தைய தொழிலாளர் பற்றாக்குறையை ஈடுகட்ட — Indiaஇலிருந்து அல்ல, எனினும் India, Pakistanஇலிருந்து தொழிலாளர்கள் சற்றுப் பிறகு வந்தனர்."],
  1378: ["India, Pakistan, Ceylon Britainஇடமிருந்து எந்த ஆண்டு சுதந்திரம் பெற்றன என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1947|1922|1966|1973", "India, Pakistan, Ceylon 1947இல் சுதந்திரம் பெற்றன, இது British Empireஇன் விரைவான காலனியகற்றலைத் தொடங்கியது."],
  1383: ["யுகே மற்றும் EEC/EU பற்றி இவற்றுள் எது உண்மை அல்ல?", "யுகே EECஇல் சேருவதற்கு முன்பே EUஐ விட்டு வெளியேறியது|யுகே 1973இல் EECஇல் சேர்ந்தது|யுகே 2020இல் European Unionஐ விட்டு வெளியேறியது|EEC பின்னர் European Union ஆனது", "யுகே 1973இல் EECஇல் சேர்ந்து, European Unionஐ மிக பின்னர், 2020இல்தான் விட்டு வெளியேறியது — சேருவதற்கு முன் வெளியேறவில்லை."],
  1386: ["1979இல் யுகேயின் முதல் பெண் Prime Minister யார் ஆனார் என நண்பர் கேட்கிறார். அவர் யார்?", "Margaret Thatcher|Theresa May|Emmeline Pankhurst|Indira Gandhi", "Margaret Thatcher 1979 முதல் 1990 வரை Prime Ministerஆக இருந்தார், 20ஆம் நூற்றாண்டின் நீண்டகாலப் பதவி வகித்த PM."],
  1391: ["Belfast (Good Friday) Agreement பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது 1801இல் கையெழுத்தானது|அது 1998இல் கையெழுத்தானது|அது Stormontஇல் அதிகாரப் பகிர்வு Assemblyக்கு வழிவகுத்தது|அது Northern Ireland தொடர்பானது", "Belfast (Good Friday) Agreement 1998இல் கையெழுத்தானது — 1801 என்பது Irelandஉடனான முந்தைய Act of Unionஇன் ஆண்டு."],
  1394: ["1997 பொதுவாக்கெடுப்புகளுக்குப் பிறகு devolved Scottish Parliament, Welsh Assembly எந்த ஆண்டு முதலில் கூடின என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1999|1979|1989|2007", "1997இன் பொதுவாக்கெடுப்புகள் devolved அமைப்புகளுக்கு வழிவகுத்தன, அவை 1999இல் முதலில் கூடின."],
  1399: ["இவற்றுள் எது Alan Turingஇன் சாதனை அல்ல?", "ஜெட் இயந்திரத்தைக் கண்டுபிடித்தது|Bletchley Parkஇல் ஜெர்மன் குறியீடுகளை உடைக்க உதவியது|நவீன கணினி அறிவியலின் முன்னோடியாக இருந்தது|குறியீடு உடைக்கும் பணி மூலம் Second World Warஐக் குறைத்தது", "Turingஇன் சாதனைகள் குறியீடு உடைத்தலிலும் கணினியியலிலும் இருந்தன. ஜெட் இயந்திரத்தை வேறொரு பிரிட்டிஷ் ஆளுமை, Sir Frank Whittle கண்டுபிடித்தார்."],
  1402: ["1930களில் டர்போ ஜெட் இயந்திரத்திற்கு எந்த RAF பொறியாளர் காப்புரிமை பெற்றார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Frank Whittle|Sir Christopher Cockerell|John Logie Baird|Alan Turing", "RAF பொறியாளர் Sir Frank Whittle 1930களில் டர்போ ஜெட் இயந்திரத்திற்கு காப்புரிமை பெற்றார்."],
  1407: ["Battle of the Boyne பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Scotlandஇல் நடந்தது|அது 1690இல் நடந்தது|அங்கு William III James IIஐத் தோற்கடித்தார்|Northern Irelandஇல் இன்றும் அது நினைவுகூரப்படுகிறது", "Battle of the Boyne 1690இல் Irelandஇல் நடந்தது, Scotlandஇல் அல்ல, அப்போது William III James IIஐத் தோற்கடித்தார்."],
  1410: ["1679இன் Habeas Corpus Act என்ன பாதுகாப்பை வழங்குகிறது என நண்பர் கேட்கிறார். சரியான பதில் என்ன?", "விசாரணையின்றி சட்டவிரோதமாகத் தடுத்து வைப்பதற்கு எதிரான பாதுகாப்பு|தேர்தலில் வாக்களிக்கும் உரிமை|பத்திரிகைச் சுதந்திரம்|அனைவருக்கும் இலவசக் கல்வி", "Habeas corpus சட்டவிரோதச் சிறைவாசத்திற்கு எதிரான முக்கியப் பாதுகாப்பு, 1679 சட்டத்தால் நிறுவப்பட்டது."],
  1415: ["Highland Clearancesஇன் பண்பு இவற்றுள் எது அல்ல?", "நிலவுடைமையாளர்கள் குத்தகைதாரர்களை இலவசமாகத் தங்க அழைத்தனர்|குத்தகைதாரர்கள் தங்கள் வீடுகளிலிருந்து வெளியேற்றப்பட்டனர்|நிலம் ஆட்டு வளர்ப்புக்கு மாற்றப்பட்டது|இதன் விளைவாகப் பல ஸ்காட்டிஷ் மக்கள் குடிபெயர்ந்தனர்", "Highland Clearancesஇல் நிலவுடைமையாளர்கள் குத்தகைதாரர்களை வெளியேற்றினர், தங்க அழைக்கவில்லை — வெளியேற்றப்பட்ட பல குடும்பங்கள் America மற்றும் பிற இடங்களுக்குக் குடிபெயர்ந்தன."],
  1418: ["ஒரு நண்பர் EU பொதுவாக்கெடுப்பை யுகேயின் உண்மையான வெளியேற்றத்துடன் குழப்புகிறார். எந்த ஆண்டு யுகே முறையாக EUஐ விட்டு வெளியேறியது?", "2020|2016|2019|2021", "2016இல் பொதுவாக்கெடுப்பு நடத்தப்பட்டது, ஆனால் யுகே 31 January 2020 வரை முறையாக EUஐ விட்டு வெளியேறவில்லை."],
  1423: ["அரசி Elizabeth IIஇன் ஆட்சி பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது அரசி Victoriaஇன் ஆட்சியை விடக் குறுகியது|அது 1952இல் தொடங்கியது|அது 2022 வரை நீடித்தது|அது பிரிட்டிஷ் வரலாற்றின் நீண்ட ஆட்சி", "Elizabeth IIஇன் ஆட்சி, 1952 முதல் 2022 வரை, பிரிட்டிஷ் வரலாற்றில் மிக நீண்டது — அரசி Victoriaஇன் 64 ஆண்டுகளை விட நீளமானது, குறுகியது அல்ல."],
  1426: ["Wiltshire வருகை தந்த நண்பர் Stonehengeஇன் கற்வட்டத்தைக் கட்டியவர்கள் யார் எனக் கேட்கிறார். அவர்கள் யார்?", "கற்கால மற்றும் வெண்கலக் கால மக்கள்|ரோமானியர்கள்|வைக்கிங்குகள்|நார்மன்கள்", "Wiltshireஇல் உள்ள Stonehenge ஒருவேளை சடங்கு இடமாக இருந்திருக்கலாம், கற்கால மற்றும் வெண்கலக் காலத்தில் கட்டப்பட்டது."],
  1431: ["பண்டைய பிரிட்டன்கள் பேசிய Celtic மொழிகளிலிருந்து இவற்றுள் எந்த மொழி வரவில்லை?", "Old English|Welsh|Gaelic|Cornish", "Welsh, Gaelic, Cornish அனைத்தும் Celtic மொழிகளிலிருந்து வந்தவை. Old English Anglo-Saxon குடியேறிகளிடமிருந்து வந்தது, முற்றிலும் வேறு மொழிக் குடும்பம்."],
  1432: ["Britain, Irelandஇன் எந்தப் பகுதிகள் ரோமானியரால் ஒருபோதும் கைப்பற்றப்படவில்லை?", "Scotland, Ireland|Wales, Cornwall|Kent, Sussex|East Anglia", "ரோமானிய ஆட்சி England, Walesஐ உள்ளடக்கியது; Scotland, Ireland பேரரசுக்கு வெளியே இருந்தன."],
  1439: ["St Columba பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் முதல் Archbishop of Canterbury ஆனார்|அவர் Ionaஇல் ஒரு மடத்தை நிறுவினார்|அவரது பணி Scotland முழுவதும் கிறித்தவத்தைப் பரப்பியது|அவர் Britainஇன் ஆரம்பக் கிறித்தவத்துடன் தொடர்புடையவர்", "St Columba Ionaஇல் மடத்தை நிறுவினார். முதல் Archbishop of Canterbury ஆனவர் St Augustine, Columba அல்ல."],
  1442: ["1066இல் Battle of Hastingsஇல் எந்த ஆங்கில மன்னர் கொல்லப்பட்டார் என நண்பர் கேட்கிறார். அவர் யார்?", "Harold|Alfred|Cnut|Edward the Confessor", "1066இல் Hastingsஇல் மன்னர் Harold கொல்லப்பட்டார், William of Normandy அரியணை ஏறினார்."],
  1447: ["Runnymedeஇல் Magna Carta பற்றி இவற்றுள் எது உண்மை அல்ல?", "மன்னர் John எந்த அழுத்தமும் இன்றி தானாகவே முத்திரையிட்டார்|அது 1215இல் முத்திரையிடப்பட்டது|பாரன்கள் மன்னரை ஏற்க நிர்ப்பந்தித்தனர்|அது அரச அதிகாரத்தை வரம்பிட்டது", "Magna Carta அழுத்தத்தின் கீழ் முத்திரையிடப்பட்டது — 1215இல் பாரன்கள் மன்னர் Johnஐ ஏற்க நிர்ப்பந்தித்தனர், அது தானாக நிகழ்ந்த செயல் அல்ல."],
  1450: ["Black Death எந்த நூற்றாண்டில் Britainஐத் தாக்கியது என நண்பர் கேட்கிறார். எந்த நூற்றாண்டு?", "14ஆம் நூற்றாண்டு|12ஆம் நூற்றாண்டு|16ஆம் நூற்றாண்டு|17ஆம் நூற்றாண்டு", "கொள்ளைநோய் 1348இல், 14ஆம் நூற்றாண்டில் Englandஐ அடைந்து மக்கள்தொகையில் சுமார் மூன்றில் ஒரு பங்கைக் கொன்றது."],
  1455: ["Black Deathஇன் விளைவு இவற்றுள் எது அல்ல?", "Englandஇன் நார்மன் வெற்றி|தொழிலாளர் பற்றாக்குறை|உயிர் பிழைத்த தொழிலாளர்கள் சிறந்த ஊதியம் கோர முடிந்தது|பழைய நிலப்பிரபுத்துவ முறை பலவீனமடைந்தது", "Black Death தொழிலாளர் பற்றாக்குறையை ஏற்படுத்தி நிலப்பிரபுத்துவத்தைப் பலவீனப்படுத்தி, செல்வமிக்க நடுத்தர வர்க்கம் உருவாக உதவியது. நார்மன் வெற்றி பல நூற்றாண்டுகளுக்கு முன், 1066இல் நிகழ்ந்தது."],
  1458: ["Glorious Revolutionஇல் பதவியிறக்கப்பட்ட Englandஇன் கடைசிக் கத்தோலிக்க மன்னர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "James II|Charles II|Henry VIII|Charles I", "James II Englandஐ ஆட்சி செய்த கடைசிக் கத்தோலிக்க மன்னர்; அவர் 1688இல் Glorious Revolution காலத்தில் தப்பிச் சென்றார்."],
  1463: ["Reformation பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஐரோப்பா முழுவதும் போப்பின் அதிகாரத்தை வலுப்படுத்தியது|அது போப்பின் அதிகாரத்திற்கு எதிரான இயக்கம்|அதனால் புராட்டஸ்டன்ட் கருத்துகள் ஐரோப்பாவில் பரவின|Henry VIIIஇன் ரோம் பிரிவினை அதனுடன் தொடர்புடையது", "Reformation போப்பின் அதிகாரத்தைச் சவால் செய்து பலவீனப்படுத்தி, புராட்டஸ்டன்ட் கருத்துகளைப் பரப்பியது — போப்பின் நிலையை வலுப்படுத்தவில்லை."],
  1466: ["மரணதண்டனைக்கு முன் Englandஇல் 20 ஆண்டுகள் சிறையில் இருந்த ஸ்காட்டிஷ் அரசி யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Mary, Queen of Scots|Mary I|Elizabeth I|Lady Jane Grey", "Mary, Queen of Scots Englandஇற்குத் தப்பி, 20 ஆண்டுகள் சிறையில் இருந்து, இறுதியில் Elizabeth Iக்கு எதிரான சதி சந்தேகத்தில் தூக்கிலிடப்பட்டார்."],
  1471: ["Gunpowder Plot பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது நாடாளுமன்றத்தை அழிப்பதில் வெற்றி பெற்றது|Guy Fawkes அதில் ஈடுபட்டிருந்தார்|அது ஒரு கத்தோலிக்க சதி|அது 1605இல் நிகழ்ந்தது", "Gunpowder Plot தோல்வியடைந்தது — வெடிபொருள்கள் பயன்படுத்தப்படும் முன்பே அவற்றைக் காவல் காத்த Guy Fawkes பிடிபட்டார், நாடாளுமன்றம் அழிக்கப்படவில்லை."],
  1474: ["1642இல் தொடங்கிய, நாடாளுமன்றத்திற்கும் மன்னருக்கும் இடையேயான மோதல் எது என நண்பர் கேட்கிறார். எது?", "The English Civil War|The Wars of the Roses|The Hundred Years War|The Jacobite rebellions", "English Civil War 1642இல் நாடாளுமன்றத்திற்கும் மன்னர் Charles Iக்கும் இடையே தொடங்கி, 1649இல் மன்னரின் மரணதண்டனையில் முடிந்தது."],
  1479: ["Sir Christopher Wren பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் மூல இடைக்கால St Paul's Cathedralஐ வடிவமைத்தார்|அவர் Great Fireக்குப் பிறகு St Paul'sஐ மீண்டும் கட்டினார்|அவரது பணி 1666 தீ விபத்திற்குப் பிந்தையது|அவர் புகழ்பெற்ற ஆங்கிலக் கட்டடக்கலைஞர்", "Great Fire பழைய இடைக்கால பேராலயத்தை அழித்த பிறகு Christopher Wren St Paul'sஐ மீண்டும் கட்டினார் — அவர் மூலப் பேராலயத்தை வடிவமைக்கவில்லை."],
  1482: ["Ireland Great Britainஉடனான ஒன்றியத்தில் எந்த ஆண்டு முறையாகச் சேர்ந்தது என நண்பர் கேட்கிறார். எந்த ஆண்டு?", "1801|1707|1922|1689", "Ireland 1801இல் ஒன்றியத்தில் சேர்ந்தது; அதன் பெரும்பகுதி 1922இல் வெளியேறியது."],
  1487: ["Richard Arkwright பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் பாலங்கள், ரயில்பாதைகள், கப்பல்கள் கட்டினார்|அவர் துணிக்கான நூற்பு இயந்திரங்களை உருவாக்கினார்|அவரது தொழிற்சாலைகள் ஜவுளி உற்பத்தியை மாற்றின|அவர் தொழிற்புரட்சியின் முக்கிய ஆளுமை", "Arkwright நூற்பு இயந்திரங்களுக்கும் தொழிற்சாலைகளுக்கும் அறியப்படுகிறார். பாலங்கள், ரயில்பாதைகள், கப்பல்கள் கட்டியது Isambard Kingdom Brunelஇன் சாதனை."],

  /* ---------- DOUBLES — CHAPTER 3/4 ---------- */
  1490: ["Great Western Railway மற்றும் SS Great Britainஐக் கட்டியவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Isambard Kingdom Brunel|Richard Arkwright|James Watt|George Stephenson", "Brunel Great Western Railwayஐயும் SS Great Britain உள்ளிட்ட கப்பல்களையும் கட்டினார்."],
  1495: ["1851இன் Great Exhibition பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Crimean Warஇன் முடிவைக் குறிக்க நடத்தப்பட்டது|அது Crystal Palaceஇல் நடத்தப்பட்டது|அது தொழிலையும் பண்பாட்டையும் கொண்டாடியது|அது Hyde Parkஇல் நடந்தது", "1851இன் Great Exhibition உலகெங்கிலுமிருந்து தொழிலையும் பண்பாட்டையும் கொண்டாடியது — Crimean War (1853-56) அப்போது தொடங்கியிருக்கவே இல்லை."],
  1498: ["Crimean War பணிக்காக Londonஇல் சிலையால் கௌரவிக்கப்பட்ட ஜமைக்கச் செவிலியர் பற்றி நண்பர் கேட்கிறார். அவர் யார்?", "Mary Seacole|Florence Nightingale|Elizabeth Fry|Emmeline Pankhurst", "Mary Seacole Jamaicaவைச் சேர்ந்த செவிலியர், Crimeaவில் காயமடைந்த வீரர்களுக்குச் சிகிச்சை அளித்து, நோயுற்றோர்க்கும் காயமடைந்தோர்க்கும் தங்குமிடம் அமைத்தார்."],
  1503: ["suffragettes பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர்கள் 17ஆம் நூற்றாண்டில், உள்நாட்டுப் போரின்போது பிரச்சாரம் செய்தனர்|அவர்கள் பெண்களின் வாக்குரிமைக்காகப் பிரச்சாரம் செய்தனர்|அவர்கள் மேலும் மேலும் தீவிரமான முறைகளைக் கையாண்டனர்|அவர்கள் First World Warக்கு முன் செயலில் இருந்தனர்", "suffragettes First World Warக்கு முன், 20ஆம் நூற்றாண்டின் தொடக்கத்தில் பிரச்சாரம் செய்தனர் — 17ஆம் நூற்றாண்டு உள்நாட்டுப் போரின்போது அல்ல."],
  1506: ["First World Warஇல் Britainஉடன் சேர்ந்து போரிட்ட முக்கிய நாடுகள் எவை என நண்பர் கேட்கிறார். எவை?", "France, Russia மற்றும் பின்னர் United States|Germany, Austria|Italy, Japan மட்டும்|Spain, Portugal", "Britain France, Russia மற்றும் பின்னர் Italy, Japan, United Statesஉடன் சேர்ந்து போரிட்டது."],
  1511: ["Blitz பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Germanyக்கு எதிரான நேச நாட்டுக் குண்டுவீச்சுப் பிரச்சாரம்|அதில் பிரிட்டிஷ் நகரங்கள் மீது கடும் குண்டுவீச்சு நடந்தது|அதை ஜெர்மன் விமானங்கள் மேற்கொண்டன|அது 1940இல் தொடங்கியது", "Blitz என்பது Germany பிரிட்டிஷ் நகரங்கள் மீது குண்டுவீசியது, Germanyக்கு எதிரான நேச நாட்டுப் பிரச்சாரம் அல்ல — London, Coventry தாக்கப்பட்ட நகரங்களில் இருந்தன."],
  1514: ["Poland படையெடுப்புக்குப் பிறகு 1939இல் Britain எந்த ஜெர்மன் தலைவருக்கு எதிராகப் போர் அறிவித்தது என நண்பர் கேட்கிறார். அவர் யார்?", "Adolf Hitler|Kaiser Wilhelm|Otto von Bismarck|Erich Ludendorff", "Adolf Hitler தலைமையிலான Germany Poland மீது படையெடுத்த பிறகு Britain 1939இல் போரை அறிவித்தது."],
  1519: ["Second World Warக்குப் பிறகு விரைவில் இவற்றுள் எது நிறுவப்படவில்லை?", "The Bank of England, பல நூற்றாண்டுகளுக்கு முன் நிறுவப்பட்டது|The National Health Service|நவீன நலன்புரி அரசின் சலுகை அமைப்பு|பயன்படுத்தும் இடத்தில் இலவச சுகாதாரப் பராமரிப்பு", "NHSஉம் நவீன நலன்புரி அரசும் Second World Warக்குப் பிறகு 1948இல் நிறுவப்பட்டன. Bank of England அப்போதே பல நூற்றாண்டுகளாக இருந்து வந்தது."],
  1522: ["James Watsonஉடன் இணைந்து 1953இல் DNA அமைப்பைக் கண்டறிந்த பிரிட்டிஷ் அறிவியலாளர்கள் யார் என நண்பர் கேட்கிறார். அவர்கள் யார்?", "Francis Crick, Maurice Wilkins|Alexander Fleming, Howard Florey|Charles Darwin, Alfred Wallace|Isaac Newton, Robert Hooke", "Francis Crick, Maurice Wilkins ஆகியோர் James Watsonஉடன் இணைந்து 1953இல் Cambridgeஇல் DNA அமைப்பைக் கண்டறிய உதவினர்."],
  1527: ["Sir Christopher Cockerell பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் ஜெட் இயந்திரத்தைக் கண்டுபிடித்தார்|அவர் hovercraftஐக் கண்டுபிடித்தார்|அவர் அதை 1950களில் உருவாக்கினார்|அவர் ஒரு பிரிட்டிஷ் கண்டுபிடிப்பாளர்", "Cockerell hovercraftஐக் கண்டுபிடித்தார். ஜெட் இயந்திரத்தை வேறொரு பிரிட்டிஷ் கண்டுபிடிப்பாளர், Sir Frank Whittle கண்டுபிடித்தார்."],
  1530: ["Second World Warஇன் பெரும்பகுதியில் Britainஇன் கூட்டணி அரசை வழிநடத்தி, பின்னர் PMஆகத் திரும்பியவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Winston Churchill|Harold Wilson|Stanley Baldwin|Neville Chamberlain, அவர் 1951இல் திரும்பினார்", "Churchill 1940 முதல் போர்க்கால கூட்டணி அரசை வழிநடத்தி, 1951இல் மீண்டும் Prime Minister ஆனார்."],
  1535: ["Commonwealth பற்றி இவற்றுள் எது உண்மை அல்ல?", "முன்னாள் பிரிட்டிஷ் காலனிகளுக்கு உறுப்பினர்ப் பதிவு கட்டாயம்|பெரும்பாலான உறுப்பினர்கள் ஒரு காலத்தில் British Empireஇன் பகுதியாக இருந்தனர்|இன்று உறுப்பினர்ப் பதிவு தன்னார்வமானது|அது முன்னாள் British Empireஇலிருந்து வளர்ந்தது", "Commonwealth உறுப்பினர்ப் பதிவு தன்னார்வமானது, கட்டாயம் அல்ல — முழு சுதந்திரம் பெற்றிருந்தாலும் நாடுகள் உறுப்பினராகத் தொடர விரும்புகின்றன."],
  1538: ["யுகேயின் எந்த நாட்டில் மக்கள்தொகையின் மிகப்பெரிய பங்கு உள்ளது என நண்பர் கேட்கிறார். எது?", "England|Scotland|Wales|Northern Ireland", "யுகேயின் மக்கள்தொகையில் சுமார் 84% England இல் உள்ளது."],
  1543: ["யுகே மக்கள்தொகைக் கணக்கெடுப்பு பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஒவ்வொரு ஆண்டும் நடத்தப்படுகிறது|அது முழு மக்கள்தொகையையும் கணக்கிடுகிறது|அது ஒவ்வொரு 10 ஆண்டுகளுக்கும் நடத்தப்படுகிறது|அது நாடு தழுவிய கணக்கெடுப்பு", "யுகே மக்கள்தொகைக் கணக்கெடுப்பு பத்தாண்டுகளுக்கு ஒருமுறை நடத்தப்படுகிறது, ஒவ்வொரு ஆண்டும் அல்ல."],
  1546: ["Englandஇன் காவல் புனிதரின் கொடி எப்படி இருக்கும் என நண்பர் கேட்கிறார். எவ்வாறு விவரிப்பீர்கள்?", "வெள்ளைப் பின்னணியில் சிவப்புச் சிலுவை|நீலப் பின்னணியில் வெள்ளை மூலைவிட்டச் சிலுவை|வெள்ளைப் பின்னணியில் சிவப்பு மூலைவிட்டச் சிலுவை|பச்சை-வெள்ளை நிலத்தில் ஒரு டிராகன்", "St George Englandஇன் காவல் புனிதர்; அவரது கொடி வெள்ளையில் சிவப்புச் சிலுவை."],
  1551: ["St Andrewஇன் கொடி பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Union Jack எனப்படுகிறது|அது saltire எனப்படுகிறது|அது Scotlandஐப் பிரதிநிதித்துவப்படுத்துகிறது|அது நீலப் பின்னணியில் வெள்ளை", "St Andrewஇன் கொடி saltire எனப்படுகிறது, அது Scotlandஐப் பிரதிநிதித்துவப்படுத்துகிறது. Union Jack முழு யுகேயின் ஒருங்கிணைந்த கொடி."],
  1554: ["Union Flag வடிவமைப்பில் Wales ஏன் பிரதிநிதித்துவப்படுத்தப்படவில்லை என நண்பர் கேட்கிறார். அதில் யாருடைய சிலுவை இல்லை?", "St Davidஇன்|St Georgeஇன்|St Andrewஇன்|St Patrickஇன்", "Union Flag St George, St Andrew, St Patrick ஆகியோரின் சிலுவைகளை இணைக்கிறது. Walesஉம் St Davidஇன் சிலுவையும் அதில் இல்லை."],
  1559: ["இவற்றுள் எது அதன் காவல் புனிதரின் நாளுடன் சரியாகப் பொருந்தவில்லை?", "St David's Day — 23 April|St David's Day — 1 March|St Patrick's Day — 17 March|St George's Day — 23 April", "St David's Day 1 Marchஇல் வருகிறது, 23 Aprilஇல் அல்ல — 23 April என்பது Englandஇன் St George's Day."],
  1562: ["Scotlandஇல் உள்ள நண்பர் தங்கள் தேசிய நாளான St Andrew's Day எந்தத் தேதியில் வருகிறது எனக் கேட்கிறார். எந்தத் தேதி?", "30 November|23 April|17 March|1 March", "St Andrew's Day, 30 November, Scotlandஇல் ஒரு தேசிய நாள்."],
  1567: ["Bonfire Night பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது நாடாளுமன்றத்தை அழிப்பதில் வெற்றி பெற்ற சதியை நினைவுகூர்கிறது|அது 5 Novemberஇல் வருகிறது|அது 1605இன் ஒரு சதியை நினைவுகூர்கிறது|அது நினைவுகூரும் சதியில் Guy Fawkes ஈடுபட்டிருந்தார்", "Bonfire Night நினைவுகூரும் Gunpowder Plot தோல்வியடைந்தது — நாடாளுமன்றம் அழிக்கப்படவில்லை, திட்டம் நிறைவேறும் முன்பே Guy Fawkes பிடிபட்டார்."],
  1570: ["போரில் இறந்தவர்களை நினைவுகூர ஒவ்வொரு Novemberஇலும் எந்த மலர் அணியப்படுகிறது என நண்பர் கேட்கிறார். எந்த மலர்?", "பாப்பி|ரோஜா|திஸில்|டேஃபோடில்", "பாப்பி மலர்கள் இரு உலகப் போர்களிலும் பிற்கால மோதல்களிலும் இறந்தவர்களை நினைவுகூர்கின்றன; 11 Novemberஇன் Remembrance Day சமயத்தில் அணியப்படுகின்றன."],
  1575: ["Hogmanay பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Walesஇல் அறுவடைத் திருவிழாவாகக் கொண்டாடப்படுகிறது|அது ஒரு ஸ்காட்டிஷ் கொண்டாட்டம்|அது புத்தாண்டு முன்தினத்தைக் குறிக்கிறது|அதனால் Scotlandஇல் 2 Januaryஉம் பொது விடுமுறை", "Hogmanay Scotlandஇன் புத்தாண்டு முன்தினக் கொண்டாட்டம் — அது வெல்ஷ் அறுவடைத் திருவிழா அல்ல."],
  1578: ["ஒவ்வொரு 25 Januaryஇலும் Burns Night விருந்தில் யார் கௌரவிக்கப்படுகிறார் என நண்பர் கேட்கிறார். அவர் யார்?", "Robert Burns|Robert the Bruce|Robert Louis Stevenson|Walter Scott", "Burns Night விருந்துகள் Auld Lang Syne எழுதிய ஸ்காட்டிஷ் கவிஞர் Robert Burnsஐக் கொண்டாடுகின்றன."],
  1583: ["இவற்றுள் எது யுகேயின் பொது விடுமுறை (bank holiday) அல்ல?", "Halloween|Christmas Day|Good Friday|New Year's Day", "Christmas Day, Good Friday, New Year's Day அனைத்தும் பொது விடுமுறைகள். Halloween பரவலாகக் கொண்டாடப்படுகிறது, ஆனால் அது அதிகாரப்பூர்வ பொது விடுமுறை அல்ல."],
  1586: ["வரலாற்றுச் சிறப்புமிக்க Ashes தொடரில் England எந்த நாட்டுக்கு எதிராகக் கிரிக்கெட் விளையாடுகிறது என நண்பர் கேட்கிறார். எந்த நாடு?", "Australia|India|South Africa|New Zealand", "England, Australia இடையிலான Ashes தொடர் 1882 முதல் விளையாடப்படுகிறது."],
  1591: ["Wimbledon சாம்பியன்ஷிப் பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது உலகின் புதிய டென்னிஸ் போட்டி|அது Londonஇல் நடத்தப்படுகிறது|அது All England Lawn Tennis Championships எனவும் அழைக்கப்படுகிறது|அது உலகின் மிகப் பழமையான டென்னிஸ் போட்டி", "Wimbledon உலகின் மிகப் பழமையான டென்னிஸ் போட்டி, புதியது அல்ல."],
  1594: ["Liverpool அருகே எந்த ரேஸ்கோர்ஸ் Grand Nationalஐ நடத்துகிறது என நண்பர் கேட்கிறார். எது?", "Aintree|Epsom|Ascot|Ayr", "Grand National Liverpool அருகே Aintreeஇல் நடத்தப்படுகிறது; Derby Epsomஇல்."],
  1599: ["Scotlandஉடன் கோல்ஃபின் தொடர்பு பற்றி இவற்றுள் எது உண்மை அல்ல?", "நவீன விளையாட்டு Englandஇல் உருவானது|நவீன விளையாட்டு Scotlandஇல் உருவானது|St Andrews அதன் வரலாற்றுத் தாயகமாகக் கருதப்படுகிறது|கோல்ஃப் ஸ்காட்டிஷ் வரலாற்றுடன் வலுவாகத் தொடர்புடையது", "நவீன கோல்ஃப் Scotlandஇல் உருவானது, Englandஇல் அல்ல — St Andrews அதன் வரலாற்றுத் தாயகம்."],
  1602: ["1954இல் நான்கு நிமிடங்களுக்குள் ஒரு மைல் ஓடிய முதல் நபர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Roger Bannister|Sir Steve Redgrave|Bobby Moore|Sir Jackie Stewart", "Bannister 1954இல் நான்கு நிமிட மைல் தடையை உடைத்தார்."],
  1607: ["Sir Steve Redgrave பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் தமது தங்கப் பதக்கங்களைத் தடகளத்தில் வென்றார்|அவர் படகுப் போட்டியில் தங்கப் பதக்கங்கள் வென்றார்|அவர் தொடர்ச்சியாக ஐந்து ஒலிம்பிக் போட்டிகளில் வென்றார்|அவர் Britainஇன் மிகச் சிறந்த ஒலிம்பியன்களில் ஒருவர்", "Steve Redgraveஇன் ஐந்து தங்கப் பதக்கங்கள் படகுப் போட்டியில் வெல்லப்பட்டன, தடகளத்தில் அல்ல."],

  /* ---------- DOUBLES — CHAPTER 4 ---------- */
  1610: ["1966இல் Englandஇன் கேப்டனாக உலகக் கோப்பையை உயர்த்தியவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Bobby Moore|Bobby Charlton|Ian Botham|Bobby Robson", "1966இல் Wembleyஇல் England West Germanyஐத் தோற்கடித்த பிறகு Bobby Moore உலகக் கோப்பையை உயர்த்தினார்."],
  1615: ["இந்த ஆண்டுகளில் எதில் London ஒலிம்பிக் போட்டிகளை நடத்தவில்லை?", "1984|1908|1948|2012", "London 1908, 1948, 2012இல் ஒலிம்பிக்கை நடத்தியது — 1984இல் அல்ல, அப்போது Los Angeles நடத்தியது."],
  1618: ["1918இல் முதன்முதலில் அரங்கேறிய The Planets இசைத்தொகுப்பை இயற்றியவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Gustav Holst|Edward Elgar|Benjamin Britten|Ralph Vaughan Williams", "Gustav Holstஇன் The Planets இசைத்தொகுப்பு 1918இல் முதன்முதலில் அரங்கேறியது."],
  1623: ["BBC Proms பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவை கால்பந்து போட்டிகளின் பருவம்|அவை Royal Albert Hallஇல் நடத்தப்படுகின்றன|அவை சுமார் எட்டு வாரங்கள் நீடிக்கின்றன|அவை Last Night of the Promsஉடன் முடிவடைகின்றன", "Proms என்பது செவ்வியல் இசை நிகழ்ச்சிகளின் பருவம், கால்பந்து போட்டிகளின் அல்ல, Royal Albert Hallஇல் நடத்தப்படுகிறது."],
  1626: ["The Hay Wain எனும் புகழ்பெற்ற ஆங்கிலக் கிராமப்புற ஓவியத்தை வரைந்தவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "John Constable|J M W Turner|David Hockney|Thomas Gainsborough", "Constable ஆங்கிலக் கிராமப்புற நிலக்காட்சிகளுக்காகப் புகழ்பெற்றவர், அவற்றுள் The Hay Wainஉம் ஒன்று."],
  1631: ["Turner Prize பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஆண்டின் சிறந்த நாவலுக்கு வழங்கப்படுகிறது|அது J M W Turner பெயரிடப்பட்டது|அது சமகாலப் பிரிட்டிஷ் கலையைக் கொண்டாடுகிறது|அது Tate Britainஉடன் தொடர்புடையது", "Turner Prize சமகாலக் கலையைக் கொண்டாடுகிறது, நாவல்களை அல்ல — சிறந்த நாவலுக்கான பரிசு Booker Prize."],
  1634: ["1666இல் பழையது எரிந்த பிறகு தற்போதைய St Paul's Cathedralஐ வடிவமைத்தவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Christopher Wren|Inigo Jones|Robert Adam|Sir Norman Foster", "1666இன் Great Fire of Londonக்குப் பிறகு Wren St Paul'sஐ வடிவமைத்து மீண்டும் கட்டினார்."],
  1639: ["'Capability' Brown பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் St Paul's Cathedralஐ வடிவமைத்தார்|அவர் நிலக்காட்சித் தோட்டங்களை வடிவமைத்தார்|அவரது முழுப்பெயர் Lancelot Brown|அவரது தோட்டங்கள் கிராமப்புற மாளிகைகளைச் சுற்றி வடிவமைக்கப்பட்டன", "'Capability' Brown நிலக்காட்சித் தோட்டங்களை வடிவமைத்தார், பேராலயங்களை அல்ல — St Paul's Cathedralஐ Sir Christopher Wren வடிவமைத்தார்."],
  1642: ["1968 முதல் வழங்கப்படும் எந்த இலக்கியப் பரிசு ஒவ்வொரு ஆண்டும் சிறந்த நாவலைக் கௌரவிக்கிறது என நண்பர் கேட்கிறார். அதன் பெயர் என்ன?", "The Booker Prize|The Turner Prize|The Mercury Prize|The Costa Book Award", "Man Booker Prize for Fiction 1968 முதல் வழங்கப்பட்டு வருகிறது."],
  1647: ["Jane Austen பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் Frankenstein எழுதினார்|அவர் Pride and Prejudice எழுதினார்|அவரது நாவல்கள் திருமணத்தையும் சமூக வர்க்கத்தையும் ஆராய்கின்றன|அவர் 19ஆம் நூற்றாண்டின் தொடக்க Englandஇல் எழுதினார்", "Jane Austen Pride and Prejudice எழுதினார். Frankenstein வேறொரு நாவலாசிரியர், Mary Shelleyஆல் எழுதப்பட்டது."],
  1650: ["Londonஇல் பல புகழ்பெற்ற கவிஞர்கள் எங்கே அடக்கம் செய்யப்பட்டுள்ளனர் அல்லது நினைவுகூரப்படுகின்றனர் என நண்பர் கேட்கிறார். அது எங்கே?", "Westminster Abbey, Poets' Cornerஇல்|St Paul's Cathedral|The Tower of London|The British Museum", "பல புகழ்பெற்ற கவிஞர்கள் Westminster Abbeyஇல் உள்ள Poets' Cornerஇல் அடக்கம் செய்யப்பட்டுள்ளனர் அல்லது நினைவுகூரப்படுகின்றனர்."],
  1655: ["Sir Tim Berners-Lee பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் தொலைக்காட்சியைக் கண்டுபிடித்தார்|அவர் World Wide Webஐக் கண்டுபிடித்தார்|அவர் தமது கண்டுபிடிப்பை சுமார் 1989-1990இல் செய்தார்|அவர் ஒரு பிரிட்டிஷ் அறிவியலாளர்", "Tim Berners-Lee World Wide Webஐக் கண்டுபிடித்தார். தொலைக்காட்சியை வேறொரு பிரிட்டிஷ் முன்னோடி, John Logie Baird கண்டுபிடித்தார்."],
  1658: ["1926இல் முதல் தொலைக்காட்சி ஒளிபரப்பைச் செய்தவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "John Logie Baird|Sir Tim Berners-Lee|Alan Turing|Sir Frank Whittle", "Baird 1926இல் முதல் தொலைக்காட்சி ஒளிபரப்பையும் 1928இல் முதல் அட்லாண்டிக் கடந்த TV ஒளிபரப்பையும் செய்தார்."],
  1663: ["Dolly ஆடு பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஒரு தாவரச் செல்லிலிருந்து குளோன் செய்யப்பட்டது|அது 1996இல் குளோன் செய்யப்பட்டது|அது ஒரு முதிர்ந்த செல்லிலிருந்து குளோன் செய்யப்பட்டது|அது Edinburghஇன் Roslin Instituteஇல் குளோன் செய்யப்பட்டது", "Dolly ஒரு முதிர்ந்த விலங்குச் செல்லிலிருந்து குளோன் செய்யப்பட்டது, தாவரச் செல்லிலிருந்து அல்ல — அது ஓர் ஆடு, 1996இல் Roslin Instituteஇல் உருவாக்கப்பட்டது."],
  1666: ["Northern Irelandஇன் வடகிழக்குக் கடற்கரைக்கு வருகை தந்த நண்பர் புராணத்தின் ஓர் அரக்கனுடன் தொடர்புடைய பாறை அமைப்பு பற்றிக் கேட்கிறார். அதன் பெயர் என்ன?", "The Giant's Causeway|The Eden Project|Snowdonia|Loch Lomond", "The Giant's Causeway Northern Irelandஇன் வடகிழக்குக் கடற்கரையில் உள்ள இயற்கைப் பாறை அமைப்பு, Finn McCool புராணத்துடன் தொடர்புடையது."],
  1671: ["இந்த மலைகளில் எது தனது யுகே நாட்டின் உயரமான சிகரம் அல்ல?", "Scafell Pike Walesஇன் உயரமான மலை|Ben Nevis ஒட்டுமொத்த யுகேயின் உயரமான மலை|Snowdon Walesஇன் உயரமான மலை|Scafell Pike Englandஇன் உயரமான மலை", "Scafell Pike Englandஇன் உயரமான மலை, Walesஇன் அல்ல — Walesஇல் அந்தப் பெருமை Snowdonக்கு உரியது."],
  1674: ["Londonக்கு வருகை தந்த நண்பர் Beefeaters காவல் காக்கும் Crown Jewelsஐ எங்கே காணலாம் எனக் கேட்கிறார். அவர் எங்கே செல்ல வேண்டும்?", "The Tower of London|Buckingham Palace|Windsor Castle|Westminster Abbey", "Crown Jewels Tower of Londonஇல் வைக்கப்பட்டுள்ளன, Beefeaters என அறியப்படும் Yeoman Warders அவற்றைக் காவல் காக்கின்றனர்."],
  1679: ["pound sterling பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது 1,000 penceஆகப் பிரிக்கப்படுகிறது|அது யுகேயின் நாணயம்|அது 100 penceஆகப் பிரிக்கப்படுகிறது|அதன் குறியீடு £", "pound sterling 100 penceஆகப் பிரிக்கப்படுகிறது, 1,000 ஆக அல்ல."],
  1682: ["Englandஇல் மன்னர் தலைமையிலான அரசு அங்கீகரித்த திருச்சபை எது என நண்பர் கேட்கிறார். எந்தத் திருச்சபை?", "The Church of England|The Church of Scotland|ரோமன் கத்தோலிக்க திருச்சபை|மெதடிஸ்ட் திருச்சபை", "Church of England ஆங்கிலிக்கன்; மன்னர் அதன் தலைவர், Archbishop of Canterbury அதன் ஆன்மிகத் தலைவர்."],
  1687: ["Church of Scotland பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதன் ஆன்மிகத் தலைவர் மன்னர்|அது Presbyterian|அது General Assembly மூலம் நிர்வகிக்கப்படுகிறது|அதற்கு Moderator தலைமை வகிக்கிறார்", "Church of Scotland அதன் சொந்த General Assembly மற்றும் Moderator மூலம் நிர்வகிக்கப்படுகிறது, மன்னர் அதன் தலைவர் அல்ல — அந்த ஏற்பாடு Church of Englandக்கு உரியது."],
  1690: ["17 வயதாகும் நண்பர் இப்போது சட்டப்படி pubஇல் மது வாங்க முடியுமா எனக் கேட்கிறார். என்ன சொல்வீர்கள்?", "இல்லை — அவர் 18 வயதாகும் வரை காத்திருக்க வேண்டும்|ஆம் — 17 சட்டப்பூர்வ வயது|ஆம், ஆனால் பெற்றோர் உடனிருந்தால் மட்டும்|இல்லை — சட்டப்பூர்வ வயது 21", "யுகேயில் மது வாங்க 18 வயது இருக்க வேண்டும், எனவே 17 வயதுள்ளவர் இன்னும் ஓர் ஆண்டு காத்திருக்க வேண்டும்."],
  1695: ["இன்று யுகேயின் சில பகுதிகளில் பரவலாகப் பேசப்படாத மொழி இவற்றுள் எது?", "லத்தீன்|Welsh|Gaelic|ஆங்கிலம்", "Welsh, Gaelic, ஆங்கிலம் அனைத்தும் இன்று யுகேயின் சில பகுதிகளில் பேசப்படுகின்றன. லத்தீன் உயிருள்ள சமூக மொழி அல்ல, எனினும் சில முறையான, கல்வித்துறைப் பயன்பாடுகளில் நீடிக்கிறது."],
  1698: ["Wales, Scotland இரண்டுக்கும் செல்லும் நண்பர் ஒவ்வொன்றிலும் எந்தப் பாரம்பரிய உணவுகளை முயல வேண்டும் எனக் கேட்கிறார். இவற்றுள் எவை இரண்டு சரியாகப் பொருந்துகின்றன? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "Walesஇல் Welsh cakes|Scotlandஇல் Haggis|Walesஇல் Ulster fry|Scotlandஇல் Cornish pasty", "Welsh cakes Walesஇலிருந்தும் haggis Scotlandஇலிருந்தும் வருகின்றன; Ulster fry Northern Irelandஇலிருந்து, Cornish pasty Englandஇன் Cornwallஇலிருந்து."],
  1703: ["இவற்றுள் எது யுகேயின் தேசியக் கொடியின் மற்றொரு பெயர் அல்ல?", "The Saltire|The Union Flag|The Union Jack|மூன்று புனிதர்களின் சிலுவைகளை இணைக்கும் கொடி", "Union Flag Union Jack எனவும் அழைக்கப்படுகிறது. Saltire குறிப்பாக St Andrewஇன் கொடியைக் குறிக்கிறது, அது Scotlandஐ மட்டும் பிரதிநிதித்துவப்படுத்துகிறது."],
  1706: ["யுகேயில் புதிதாக வந்த நண்பர் Christmas Day எந்தத் தேதியில் வருகிறது, அதன் மறுநாள் Boxing Day எனக் கேட்கிறார். எந்தத் தேதி?", "25 December|24 December|26 December|1 January", "Christmas Day 25 Decemberஇல் வருகிறது; 26 December, Boxing Dayஉம் பொது விடுமுறை."],
  1711: ["Diwali பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஓர் யூதத் திருவிழா|அதை இந்துக்களும் சீக்கியர்களும் கொண்டாடுகின்றனர்|அது ஒளித் திருவிழா|அது பொதுவாக October அல்லது Novemberஇல் வருகிறது", "Diwali இந்துக்களின், சீக்கியர்களின் ஒளித் திருவிழா — Hanukkah யூதர்களின் ஒளித் திருவிழா."],
  1714: ["நோன்பு மாதத்தின் இறுதியில் கொண்டாடப்படும் Eid al-Fitr எதைக் குறிக்கிறது என நண்பர் கேட்கிறார். அது என்ன?", "Ramadanஇன் முடிவு|இந்து புத்தாண்டு|ஒரு சீக்கிய அறுவடைத் திருவிழா|ஓர் யூத ஒளித் திருவிழா", "Eid al-Fitr Ramadanஇன் முடிவைக் குறிக்கும் ஒரு முஸ்லிம் திருவிழா, அப்போது நோன்பு மாதத்தை நிறைவு செய்யும் வலிமை அளித்ததற்காக முஸ்லிம்கள் இறைவனுக்கு நன்றி கூறுகின்றனர்."],
  1719: ["Lord's பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஒரு புகழ்பெற்ற டென்னிஸ் அரங்கம்|அது ஒரு புகழ்பெற்ற கிரிக்கெட் மைதானம்|அது Londonஇல் உள்ளது|அது தனது விளையாட்டின் உலகின் மிகப் புகழ்பெற்ற மைதானங்களில் ஒன்று", "Lord's ஒரு புகழ்பெற்ற கிரிக்கெட் மைதானம், டென்னிஸ் அரங்கம் அல்ல — Londonஇன் புகழ்பெற்ற டென்னிஸ் அரங்கம் Wimbledon."],
  1722: ["England, Scotland, Wales, Ireland ஆகியவை France, Italyஉடன் ரக்பி விளையாடும் ஆண்டு போட்டி எது என நண்பர் கேட்கிறார். அதன் பெயர் என்ன?", "The Six Nations Championship|The Ashes|The Ryder Cup|The World Cup", "Six Nations Championshipஇல் England, Scotland, Wales, Ireland ஒவ்வொரு ஆண்டும் France, Italyஉடன் rugby union விளையாடுகின்றன."],
  1727: ["Sir Ian Botham பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர் ஒரு சாம்பியன் rower|அவர் ஒரு புகழ்பெற்ற கிரிக்கெட் வீரர்|Englandஇன் டெஸ்ட் விக்கெட் சாதனை அவரிடம் இருந்தது|அவரது சாதனைகள் கிரிக்கெட்டில் இருந்தன", "Ian Botham கிரிக்கெட் வீரராகப் புகழ்பெற்றவர். படகுப் போட்டித் தங்கங்கள் வேறொரு விளையாட்டு வீரர், Sir Steve Redgraveஇன் சாதனை."],

  /* ---------- DOUBLES — CHAPTER 4/5 ---------- */
  1730: ["1960கள், 70களில் மூன்று Formula 1 உலக சாம்பியன்ஷிப்களை வென்ற ஸ்காட்டிஷ் ஓட்டுநர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Jackie Stewart|Damon Hill|Lewis Hamilton|Nigel Mansell", "ஸ்காட்டிஷ் ஓட்டுநர் Jackie Stewart மூன்று Formula 1 உலக சாம்பியன்ஷிப்களை வென்றார்."],
  1735: ["யுகே bank holiday பற்றி இவற்றுள் எது உண்மை அல்ல?", "வங்கிகள் மட்டுமே பாதிக்கப்படுகின்றன, மற்ற அனைத்து வணிகங்களும் வழக்கம்போல் திறந்திருக்கும்|பெரும்பாலான வணிகங்கள் மூடப்படுகின்றன|Christmas Day அதற்கு ஓர் எடுத்துக்காட்டு|Easter Monday அதற்கு ஓர் எடுத்துக்காட்டு", "bank holiday பெரும்பாலான வணிகங்களைப் பாதிக்கிறது, வங்கிகளை மட்டும் அல்ல — இது ஒரு பொதுவான விடுமுறை."],
  1738: ["Psycho, The Birds படங்களை இயக்கிய பிரிட்டிஷ் இயக்குநர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "Sir Alfred Hitchcock|Steven Spielberg|Martin Scorsese|David Lean", "Hitchcock Psycho, The Birds ஆகியவற்றை இயக்கினார்; பிரிட்டிஷ் திரைப்பட விருதுகள் BAFTAs."],
  1743: ["Chelsea Flower Show பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Edinburghஇல் நடத்தப்படுகிறது|அது Londonஇல் நடத்தப்படுகிறது|அது ஒவ்வொரு ஆண்டும் நடத்தப்படுகிறது|அது உலகெங்கிலுமிருந்து தோட்ட வடிவமைப்பைக் காட்டுகிறது", "Chelsea Flower Show Londonஇல் நடத்தப்படுகிறது, Edinburghஇல் அல்ல — Edinburgh Festival தனி, தொடர்பற்ற நிகழ்வு."],
  1746: ["முக்கியமாக வெல்ஷ் மொழியில் நடத்தப்படும் இலக்கியம், இசை, நிகழ்த்துகலை வெல்ஷ் திருவிழா பற்றி நண்பர் கேட்கிறார். அதன் பெயர் என்ன?", "The Eisteddfod|The Highland Games|The Chelsea Flower Show|The Notting Hill Carnival", "National Eisteddfod இலக்கியம், இசை, நிகழ்த்துகலைக்கான ஆண்டு வெல்ஷ் திருவிழா, முக்கியமாக வெல்ஷ் மொழியில் நடத்தப்படுகிறது."],
  1751: ["Stonehenge பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது Cornwallஇல் உள்ளது|அது Wiltshireஇல் உள்ளது|அது ஒரு World Heritage Site|அது ஒரு வரலாற்றுக்கு முந்தைய நினைவுச்சின்னம்", "Stonehenge Wiltshireஇல் உள்ளது, Cornwallஇல் அல்ல — Cornwallஇல் Eden Project உள்ளது."],
  1754: ["உலகெங்கிலுமிருந்து தாவரங்களைக் கொண்ட Eden Projectஇன் பெரும் biomes எந்தக் கவுண்டியில் உள்ளன என நண்பர் கேட்கிறார். எந்தக் கவுண்டி?", "Cornwall|Kent|Fife|Antrim", "Cornwallஇல் உள்ள Eden Projectஇன் biomes உலகெங்கிலுமிருந்து தாவரங்களைக் கொண்டுள்ளன."],
  1759: ["இவற்றுள் எது யுகேயின் மிகப்பெரிய தேசியப் பூங்கா அல்ல?", "Snowdonia|The Cairngorms|Scotlandஇல் அமைந்துள்ள ஒரு தேசியப் பூங்கா|பரப்பளவில் யுகேயின் மிகப்பெரிய தேசியப் பூங்கா", "Scotlandஇல் உள்ள Cairngorms யுகேயின் மிகப்பெரிய தேசியப் பூங்கா — Walesஇல் உள்ள Snowdonia மிகப்பெரியது அல்ல."],
  1762: ["ஒரு நண்பர் யுகேயில் தமது முதல் வீட்டுக்குக் குடிபெயர்ந்து நேரலை TV பார்க்கத் திட்டமிடுகிறார். அவர் முதலில் எதை ஏற்பாடு செய்ய வேண்டும்?", "ஒரு TV licence|உள்ளாட்சியில் பதிவு|BBC உறுப்பினர்ப் பதிவு|Ofcom ஒப்புதல்", "நேரலை தொலைக்காட்சி பார்க்கும் அல்லது BBC iPlayer பயன்படுத்தும் ஒவ்வொரு குடும்பத்திற்கும் TV licence தேவை."],
  1767: ["National Lottery டிக்கெட் வாங்குவதற்கான சரியான குறைந்தபட்ச வயது இவற்றுள் எது அல்ல?", "16|18|மது வாங்கும் அதே வயது|betting shopஇல் சூதாடும் அதே வயது", "National Lottery பொருட்களுக்கான குறைந்தபட்ச வயது 18, மது வாங்குவது அல்லது சூதாடுவது போலவே — 16 அல்ல."],
  1770: ["ஒரு நண்பர் தொண்டுப் பணியில் ஈடுபட விரும்புகிறார். இவற்றுள் எவை இரண்டு உண்மையில் ஒரு தொண்டு நிறுவனத்திற்கு உதவும்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "தொண்டு நிறுவனக் கடையில் தன்னார்வத் தொண்டு|நிதி திரட்டும் முயற்சிக்கு நன்கொடை|எந்த வரியும் செலுத்த மறுப்பது|தேர்தல் நாளில் வீட்டில் தங்குவது", "National Trust, Comic Relief போன்ற தொண்டு நிறுவனங்கள் தன்னார்வலர்களையும் நன்கொடைகளையும் பெரிதும் நம்பியுள்ளன."],
  1774: ["மன்னர் அரசுத் தலைவராக இருந்தும் நாட்டை நடத்தாத யுகேயின் ஆட்சி முறையை எவ்வாறு விவரிப்பது என நண்பர் கேட்கிறார். அதன் பெயர் என்ன?", "நாடாளுமன்ற ஜனநாயகத்துடன் கூடிய அரசியலமைப்பு முடியாட்சி|முழுமையான முடியாட்சி|கூட்டாட்சிக் குடியரசு|ஒரு கட்சி ஆட்சி", "யுகே நாடாளுமன்ற ஜனநாயகத்துடன் கூடிய அரசியலமைப்பு முடியாட்சி — மன்னர் அரசுத் தலைவர், ஆனால் தேர்ந்தெடுக்கப்பட்ட அரசே நாட்டை நடத்துகிறது."],
  1779: ["House of Commonsஇன் MPs பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர்கள் 129 பேர்|அவர்கள் 650 பேர்|ஒவ்வொருவரும் ஒரு தொகுதியைப் பிரதிநிதித்துவப்படுத்துகிறார்|அவர்கள் House of Commonsஇல் அமர்கிறார்கள்", "House of Commonsஇல் 650 MPs உள்ளனர் — 129 என்பது Scottish Parliament உறுப்பினர்களின் எண்ணிக்கை."],
  1782: ["House of Commonsஇல் விவாதங்களுக்குத் தலைமை தாங்கி, அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டியவர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "The Speaker|The Prime Minister|The Lord Chancellor|The Leader of the Opposition", "Speaker என்பவர் மற்ற MPsஆல் இரகசிய வாக்கெடுப்பில் தேர்ந்தெடுக்கப்படும் MP, அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டும்."],
  1787: ["House of Lords உறுப்பினர்கள் பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவர்கள் அனைவரும் பொதுமக்களால் தேர்ந்தெடுக்கப்படுகிறார்கள்|பெரும்பாலானோர் life peers|Lordsஇல் சில ஆயர்களும் உள்ளனர்|Lordsஇல் சில hereditary peersஉம் உள்ளனர்", "House of Lords உறுப்பினர்கள் பொதுமக்களால் தேர்ந்தெடுக்கப்படுவதில்லை — பெரும்பாலானோர் life peersஆக நியமிக்கப்படுகின்றனர், ஆயர்கள், சில hereditary peersஉடன்."],
  1790: ["யுகே குறைந்தபட்சம் எத்தனை காலத்திற்கு ஒருமுறை பொதுத் தேர்தல் நடத்த வேண்டும் என நண்பர் கேட்கிறார். பதில் என்ன?", "குறைந்தது ஐந்தாண்டுகளுக்கு ஒருமுறை|குறைந்தது மூன்றாண்டுகளுக்கு ஒருமுறை|குறைந்தது ஏழாண்டுகளுக்கு ஒருமுறை|இரண்டாண்டுகளுக்கு ஒருமுறை", "பொதுத் தேர்தல் குறைந்தது ஐந்தாண்டுகளுக்கு ஒருமுறை நடத்தப்பட வேண்டும்."],
  1795: ["யுகே பொதுத் தேர்தல்களில் பயன்படுத்தப்படும் first past the post முறை பற்றி இவற்றுள் எது உண்மை அல்ல?", "இடங்கள் தேசிய வாக்குப் பங்கின் விகிதத்தில் கண்டிப்பாக ஒதுக்கப்படுகின்றன|தொகுதியில் அதிக வாக்குகள் பெறும் வேட்பாளர் வெல்கிறார்|இது யுகே பொதுத் தேர்தல்களுக்குப் பயன்படுத்தப்படுகிறது|ஒவ்வொரு தொகுதியும் ஒரு MPஐத் தேர்ந்தெடுக்கிறது", "first past the post இடங்களைத் தேசிய வாக்குப் பங்கின் விகிதத்தில் ஒதுக்குவதில்லை — ஒவ்வொரு தொகுதியிலும் அதிக வாக்குகள் பெறும் வேட்பாளர் அந்த இடத்தை வெல்கிறார்."],
  1798: ["Prime Ministerஇன் அதிகாரப்பூர்வ London இல்லம் எந்த முகவரி என நண்பர் கேட்கிறார். எந்த முகவரி?", "10 Downing Street|11 Downing Street|Buckingham Palace|Chequers", "Prime Minister 10 Downing Streetஇல் வசிக்கிறார், Chequers எனும் கிராமப்புற இல்லமும் உள்ளது."],
  1803: ["இவற்றுள் எது Chancellor of the Exchequerஇன் பொறுப்பு அல்ல?", "காவல்துறையும் குடியேற்றமும்|பொருளாதாரம்|11 Downing Streetஇல் வசிப்பது|நிதி மற்றும் நிதிநிலை விவகாரங்கள்", "Chancellor of the Exchequer பொருளாதாரத்தைக் கையாள்கிறார் — காவல்துறையும் குடியேற்றமும் Home Secretaryஇன் பொறுப்பு."],
  1806: ["குற்றம், காவல்துறை, குடியேற்றம் அடங்கிய Home Officeஐ நடத்தும் அமைச்சர் யார் என நண்பர் கேட்கிறார். அவர் யார்?", "The Home Secretary|The Foreign Secretary|The Chancellor of the Exchequer|The Justice Secretary", "Home Secretary Home Officeஐ நடத்துகிறார், அது குற்றம், காவல்துறை, குடியேற்றத்திற்குப் பொறுப்பானது."],
  1811: ["House of Commonsஇல் எதிர்க்கட்சி பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதன் தலைவருக்கு எந்த முறையான பங்கும் இல்லை|அது இரண்டாவது பெரிய கட்சி|அதன் தலைவர் நிழல் அமைச்சரவையை நியமிக்கிறார்|அதன் பங்கு அரசை எதிர்கொள்வது", "Leader of the Oppositionக்கு முறையான, அங்கீகரிக்கப்பட்ட பங்கு உள்ளது — அரசை எதிர்கொள்ள நிழல் அமைச்சரவையை நியமிப்பது — பங்கே இல்லாதது அல்ல."],
  1814: ["civil servants ஆளும் கட்சியைச் சேர்ந்தவர்களாக இருக்க வேண்டுமா என நண்பர் கேட்கிறார். சரியான பதில் என்ன?", "இல்லை — அவர்கள் அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டும், தகுதியின் அடிப்படையில் நியமிக்கப்படுகின்றனர்|ஆம் — அவர்கள் ஆளும் கட்சியைச் சேர்ந்தவர்களாக இருக்க வேண்டும்|ஆம், ஆனால் மூத்த civil servants மட்டும்|இல்லை — ஆனால் அவர்களைப் பொதுமக்கள் தேர்ந்தெடுக்கின்றனர்", "civil servants அரசியல் ரீதியாக நடுநிலையாக இருக்கவும் தகுதியின் அடிப்படையில் நியமிக்கப்படவும் வேண்டும் — தமது சொந்தக் கருத்துகள் எதுவாயினும் அப்போதைய அரசை ஆதரிக்கின்றனர்."],
  1819: ["Scottish Parliament பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதில் 90 உறுப்பினர்கள் உள்ளனர்|அதில் 129 உறுப்பினர்கள் உள்ளனர்|அதன் உறுப்பினர்கள் MSPs எனப்படுகின்றனர்|அது Edinburghஇல் உள்ள Holyroodஐ மையமாகக் கொண்டது", "Scottish Parliamentஇல் 129 உறுப்பினர்கள் உள்ளனர் — 90 என்பது Northern Ireland Assembly உறுப்பினர்களின் (MLAs) எண்ணிக்கை."],
  1822: ["90 MLAs கொண்ட Northern Ireland Assembly எங்கே அமைந்துள்ளது என நண்பர் கேட்கிறார். அது எங்கே?", "Stormont, Belfast|Holyrood, Edinburgh|Cardiff Bay|Westminster", "Stormont, Belfastஇல் அமைந்துள்ள Northern Ireland Assemblyஇல் 90 உறுப்பினர்கள் (MLAs) உள்ளனர், அது அதிகாரப் பகிர்வு அடிப்படையில் செயல்படுகிறது."],
  1827: ["Hansard பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது இடைக்கால நில உரிமையைப் பதிவு செய்கிறது|அது நாடாளுமன்ற விவாதங்களைப் பதிவு செய்கிறது|அது தினமும் வெளியிடப்படுகிறது|அது இணையத்தில் கிடைக்கிறது", "Hansard நாடாளுமன்ற விவாதங்களைப் பதிவு செய்கிறது — இடைக்கால நில உரிமையைப் பதிவு செய்வது மிகப் பழைய Domesday Bookஇன் நோக்கமாக இருந்தது."],
  1828: ["மன்னர் பற்றிய இக்கூற்றுகளில் எது சரியானது?", "மன்னர் அரசியல் ரீதியாக நடுநிலையானவர், அரசியலில் யாருக்கும் ஆதரவாக இல்லை|நாடாளுமன்றம் எந்தச் சட்டங்களை இயற்றும் என்பதை மன்னர் தேர்வு செய்கிறார்|மன்னர் அனைத்து MPsஐயும் நியமிக்கிறார்|மன்னர் மிகப்பெரிய அரசியல் கட்சியை வழிநடத்துகிறார்", "மன்னர் அரசுத் தலைவர், ஆனால் கட்சி அரசியலுக்கு அப்பாற்பட்டவர், ஆலோசனையும் எச்சரிக்கையும் வழங்க Prime Ministerஐ வழக்கமாகச் சந்திக்கிறார்."],
  1835: ["State Opening of Parliamentஇல் மன்னர் வாசிக்கும் உரை பற்றி இவற்றுள் எது உண்மை அல்ல?", "மன்னர் அதைத் தாமே எழுதுகிறார்|அரசு அதை எழுதுகிறது|அது வரும் ஆண்டுக்கான அரசுக் கொள்கையை விவரிக்கிறது|அது State Openingஇல் வழங்கப்படுகிறது", "State Openingஇல் மன்னர் வாசிக்கும் உரையை அரசு எழுதுகிறது, மன்னர் தாமே அல்ல."],
  1838: ["17 வயதாகும் நண்பர் அடுத்த பொதுத் தேர்தலில் வாக்களிக்க முடியுமா எனக் கேட்கிறார். என்ன சொல்வீர்கள்?", "இல்லை — அவர் 18 வயதாகும் வரை காத்திருக்க வேண்டும்|ஆம் — வாக்களிக்கும் வயது 17|ஆம், ஆனால் உள்ளாட்சித் தேர்தல்களில் மட்டும்|இல்லை — வாக்களிக்கும் வயது 21", "பொதுத் தேர்தலில் வாக்களிக்க 18 வயது அல்லது அதற்கு மேல் இருக்க வேண்டும், electoral registerஇல் பெயர் இருக்க வேண்டும்."],
  1843: ["யுகே வாக்குச்சாவடி நேரம் பற்றி இவற்றுள் எது உண்மை அல்ல?", "அவை மாலை 5 மணிக்கு மூடப்படுகின்றன|அவை காலை 7 மணிக்குத் திறக்கின்றன|அவை இரவு 10 மணிக்கு மூடப்படுகின்றன|தேர்தல் நாளில் அவை 15 மணி நேரம் திறந்திருக்கும்", "வாக்குச்சாவடிகள் இரவு 10 மணிக்கு மூடப்படுகின்றன, மாலை 5 மணிக்கு அல்ல — காலை 7 முதல் இரவு 10 வரை, அதாவது 15 மணி நேரம் திறந்திருக்கும்."],
  1846: ["மன்னர் தலைமையிலான தன்னார்வக் கூட்டமைப்பான Commonwealthஇல் எத்தனை நாடுகள் உள்ளன என நண்பர் கேட்கிறார். எத்தனை?", "54|27|15|100", "Commonwealth என்பது 54 நாடுகளின் தன்னார்வக் கூட்டமைப்பு; மன்னர் அதன் தலைவர், உறுப்பினர்கள் மீது அதற்கு அதிகாரம் இல்லை."],
  1851: ["UN Security Councilஇல் யுகேயின் நிலை பற்றி இவற்றுள் எது உண்மை அல்ல?", "யுகே ஒரு தற்காலிக, சுழற்சி உறுப்பினர் மட்டுமே|யுகே ஒரு நிரந்தர உறுப்பினர்|யுகே முன்மொழிவுகளுக்கு veto செய்ய முடியும்|மொத்தம் ஐந்து நிரந்தர உறுப்பினர்கள் உள்ளனர்", "யுகே UN Security Councilஇன் நிரந்தர உறுப்பினர், தற்காலிக சுழற்சி உறுப்பினர் அல்ல, முன்மொழிவுகளுக்கு veto செய்ய முடியும்."],
  1854: ["NATO உறுப்பினர்களில் ஒருவர் தாக்கப்பட்டால் மற்றவர்கள் என்ன செய்ய உறுதியளிக்கின்றனர் என நண்பர் கேட்கிறார். பதில் என்ன?", "கூட்டுப் பாதுகாப்பின் ஒரு பகுதியாக ஒருவருக்கொருவர் உதவுவது|கூட்டு வர்த்தக விதிகளை வகுப்பது|ஒரு பொது நாணயத்தை நிர்வகிப்பது|எதுவும் இல்லை — NATOக்குப் பாதுகாப்புப் பங்கு இல்லை", "NATOஇன் முக்கிய நோக்கம் கூட்டுப் பாதுகாப்பு — தாக்குதலுக்கு உள்ளானால் ஒருவருக்கொருவர் உதவ உறுப்பினர்கள் ஒப்புக்கொள்கின்றனர்."],
  1859: ["Council of Europe பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதற்குத் தன் உறுப்பினர்களுக்குக் கட்டுப்படுத்தும் சட்டங்களை இயற்றும் அதிகாரம் உள்ளது|அது மனித உரிமைகளைப் பாதுகாக்கிறது|அது European Convention on Human Rightsஐ மேற்பார்வையிடுகிறது|அதற்குச் சட்டமியற்றும் அதிகாரம் இல்லை", "Council of Europeக்குத் தெளிவாகச் சட்டமியற்றும் அதிகாரம் இல்லை — அது European Convention on Human Rights மூலம் மனித உரிமைகளைப் பாதுகாக்கிறது."],
  1862: ["England, Walesஇல் சிறு குற்றங்களை எந்த நீதிமன்றம் கையாள்கிறது, அங்கு ஊதியமற்ற தன்னார்வலர்கள் நடுவர் குழு இன்றி விசாரிக்கின்றனர் என நண்பர் கேட்கிறார். எந்த நீதிமன்றம்?", "The Magistrates' Court|The Crown Court|The County Court|The High Court", "Magistrates' Court England, Walesஇல் சிறு குற்றங்களைக் கையாள்கிறது; magistrates ஊதியமற்ற தன்னார்வலர்கள், நடுவர் குழு இன்றி விசாரிக்கின்றனர்."],
  1867: ["Scotlandஇல் சிறு குற்றவியல் வழக்குகள் பற்றி இவற்றுள் எது உண்மை அல்ல?", "England, Wales போலவே அவை Magistrates' Courtஇல் விசாரிக்கப்படுகின்றன|அவை பொதுவாக Justice of the Peace Courtஇல் விசாரிக்கப்படுகின்றன|Scotlandக்குத் தனி சட்ட அமைப்பு உள்ளது|Sheriff Courtsஉம் ஸ்காட்டிஷ் அமைப்பின் பகுதி", "Scotland Magistrates' Courts பயன்படுத்துவதில்லை — அது England, Walesஇன் அமைப்பு. Scotland அதற்குப் பதிலாக Justice of the Peace Courts, Sheriff Courts பயன்படுத்துகிறது."],
  1870: ["England, Wales அல்லது Northern Irelandஇல் Crown Court வழக்கில் எத்தனை jurors அமர்கின்றனர் என நண்பர் கேட்கிறார். எத்தனை?", "12|15|10|8", "England, Wales, Northern Irelandஇல் நடுவர் குழுவில் 12 உறுப்பினர்கள், Scotlandஇல் 15."],

  /* ---------- DOUBLES — CHAPTER 5 ---------- */
  1875: ["யுகேயில் குற்றவியல் பொறுப்பு வயது பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது யுகேயின் ஒவ்வொரு பகுதியிலும் ஒன்றே|England, Wales, Northern Irelandஇல் அது 10|Scotlandஇல் அது 12|அது Scotlandக்கும் மற்ற யுகேக்கும் இடையே வேறுபடுகிறது", "குற்றவியல் பொறுப்பு வயது யுகே முழுவதும் வேறுபடுகிறது — England, Wales, Northern Irelandஇல் 10, ஆனால் Scotlandஇல் 12."],
  1878: ["ஒரு நண்பருக்குச் செலுத்தப்படாத கடன் தொடர்பாகச் சிறு உரிமைத் தகராறு உள்ளது. England அல்லது Walesஇல் எந்த நீதிமன்றம் அதைக் கையாள வேண்டும்?", "The County Court|The Crown Court|The Magistrates' Court|The High Court", "County Courts கடன், தனிநபர் காயம், ஒப்பந்த மீறல் போன்ற உரிமையியல் விவகாரங்களைக் கையாள்கின்றன."],
  1883: ["Citizens Advice பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது ஓர் அரசுத் துறை|அது தொண்டு நிறுவனங்களின் வலையமைப்பு|அது இலவச ஆலோசனை வழங்குகிறது|அது இரகசியமானது", "Citizens Advice தொண்டு நிறுவனங்களின் வலையமைப்பு, அரசுத் துறை அல்ல."],
  1886: ["ஒரு நண்பர் கட்டாயத் திருமணத்தை ஏற்பாடு செய்யப்பட்ட திருமணத்துடன் குழப்புகிறார். இவற்றுள் எவை இரண்டு உண்மையில் யுகேயில் சட்டவிரோதமானவை? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "கட்டாயத் திருமணம்|பெண் பிறப்புறுப்புச் சிதைவு|முழு சம்மதத்துடன் ஏற்பாடு செய்யப்பட்ட திருமணம்|மத ஆடை அணிதல்", "கட்டாயத் திருமணமும் FGMஉம் கடுமையான குற்றங்கள். இருவரும் சம்மதிக்கும் ஏற்பாடு செய்யப்பட்ட திருமணம் சட்டப்பூர்வமானது."],
  1891: ["National Insurance இவற்றுள் எதற்கு நிதியளிப்பதில்லை?", "கார் விபத்துக் காப்பீட்டுக் கோரிக்கைகள்|அரசு நலன்கள்|அரசு ஓய்வூதியம்|ஏறக்குறைய ஒவ்வொரு தொழிலாளியும் பங்களிக்கும் திட்டங்கள்", "National Insurance அரசு நலன்களுக்கும் அரசு ஓய்வூதியத்திற்கும் நிதியளிக்கிறது — கார் விபத்துக் காப்பீடு மோட்டார் காப்பீட்டின் தனி, தனியார் விவகாரம்."],
  1894: ["ஊதியப் பணி தொடங்கும் நண்பர் PAYE முறையில் தமது வருமான வரியைக் கழிப்பது யார் எனக் கேட்கிறார். யார் செய்கிறார்?", "அவரது முதலாளி|அவரே self-assessment மூலம் செய்ய வேண்டும்|அவரது உள்ளாட்சி|அவரது வங்கி", "PAYE (Pay As You Earn) முறையில் முதலாளி ஊதியத்திலிருந்து வருமான வரியைக் கழிக்கிறார்; சுயதொழில் செய்வோர் பொதுவாக self-assessment மூலம் செலுத்துகின்றனர்."],
  1899: ["self-assessment வரிப் படிவ இறுதித் தேதிகள் பற்றி இவற்றுள் எது உண்மை அல்ல?", "காகித இறுதித் தேதி ஆன்லைன் இறுதித் தேதிக்குப் பிந்தையது|ஆன்லைன் இறுதித் தேதி 31 January|காகித இறுதித் தேதி 31 October|காகிதப் படிவங்கள் ஆன்லைனை விட முன்பே தாக்கல் செய்யப்பட வேண்டும்", "காகித இறுதித் தேதி (31 October) ஆன்லைன் இறுதித் தேதிக்கு (31 January) முன்பே வருகிறது, பின்பு அல்ல."],
  1902: ["17 வயதாகும் நண்பர் இப்போது சட்டப்படி கார் ஓட்ட முடியுமா எனக் கேட்கிறார். என்ன சொல்வீர்கள்?", "ஆம் — கார் ஓட்டுவதற்கான சட்டப்பூர்வ வயது 17|இல்லை — சட்டப்பூர்வ வயது 18|இல்லை — சட்டப்பூர்வ வயது 21|ஆம், ஆனால் ஏற்கெனவே முழு உரிமம் இருந்தால் மட்டும்", "யுகேயில் 17 வயதில் கார் அல்லது மோட்டார் சைக்கிள் ஓட்டலாம், 16 வயதில் moped."],
  1907: ["MOT சோதனை பற்றி இவற்றுள் எது உண்மை அல்ல?", "புத்தம் புதிய கார்களுக்கு வாங்கிய நாளிலேயே அது தேவை|கார்களுக்கு முதல் சோதனை மூன்று வயதில் தேவை|அதன் பிறகு MOT சோதனைகள் ஆண்டுதோறும் தேவை|வாகனம் சாலைக்கு உகந்ததா எனச் சோதனை சரிபார்க்கிறது", "புத்தம் புதிய காருக்கு உடனடியாக MOT தேவையில்லை — கார் மூன்று வயதை அடைந்தபோதுதான் முதல் சோதனை தேவைப்படுகிறது."],
  1910: ["ஒரு நண்பர் உள்ளூரில் மேலும் ஈடுபட விரும்புகிறார். இவற்றுள் எவை இரண்டு உண்மையில் சமூகப் பங்கேற்பாகக் கருதப்படும்? (இரண்டு பதில்களைத் தேர்வு செய்யவும்)", "school governor ஆவது|ஒரு தொண்டு நிறுவனத்திற்குத் தன்னார்வத் தொண்டு|அழைக்கப்படும்போது jury serviceஐ மறுப்பது|உள்ளாட்சித் தேர்தல்களைத் தவிர்ப்பது", "neighbourhood watchஇல் சேரலாம், magistrate அல்லது special constable ஆகலாம், அல்லது உள்ளூர் மருத்துவமனையில் உதவலாம்."],
  1915: ["jury service தகுதி பற்றி இவற்றுள் எது உண்மை அல்ல?", "பயிற்சி பெற்ற வழக்கறிஞர்கள் மட்டுமே நடுவர் குழுவில் இருக்க முடியும்|மக்கள் electoral registerஇலிருந்து சீரற்ற முறையில் தேர்ந்தெடுக்கப்படுகின்றனர்|தகுதியான வயது வரம்பு தோராயமாக 18 முதல் 70 வரை|jury service ஒரு குடிமைக் கடமை", "jurors பொது மக்கள், electoral registerஇலிருந்து சீரற்ற முறையில் தேர்ந்தெடுக்கப்படுகின்றனர் — வழக்கறிஞர்கள் சிறப்பு அல்லது தேவையான பிரிவு அல்ல."],
  1918: ["உரிமம், road tax தவிர யுகே சாலைகளில் கார் ஓட்டுவதற்கு முன் சட்டப்படி வேறு என்ன தேவை என நண்பர் கேட்கிறார். வேறு என்ன தேவை?", "மோட்டார் காப்பீடு|பல்கலைக்கழகப் பட்டம்|குடியிருப்பு அனுமதி|வாகன நிறுத்த அனுமதி", "அனைத்து ஓட்டுநர்களுக்கும் மோட்டார் காப்பீடு இருக்க வேண்டும்; அது இன்றி ஓட்டுவது குற்றம், செல்லுபடியாகும் உரிமமும் road taxஉம் தேவை."],
  1923: ["காவல்துறை உங்களை அநீதியாக நடத்தியதாக உணர்ந்தால், இவற்றுள் எது நியாயமான பதிலளிப்பு அல்ல?", "அதன் பிறகு காவல்துறையின் சட்டப்பூர்வ உத்தரவுகளைக் கடைப்பிடிக்க மறுப்பது|காவல்துறையிடம் முறையான புகார் அளிப்பது|ஒரு சுயாதீன அமைப்பிடம் புகார் அளிப்பது|முறையான புகார் நடைமுறையைப் பயன்படுத்துவது", "சட்டப்பூர்வ உத்தரவுகளைக் கடைப்பிடிக்க மறுப்பது நியாயமான பதிலளிப்பு அல்ல — சரியான வழி காவல்துறையிடமோ சுயாதீன அமைப்பிடமோ முறையான புகார் அளிப்பது."],
  1926: ["England, Walesஇல் உள்ளூர் காவல்துறையைப் பொறுப்புக்கூறச் செய்ய பொதுமக்கள் யாரைத் தேர்ந்தெடுக்கின்றனர் என நண்பர் கேட்கிறார். அப்பதவியின் பெயர் என்ன?", "ஒரு Police and Crime Commissioner|ஒரு மூத்த காவல் அதிகாரி|ஒரு Home Office civil servant|ஒரு magistrate", "England, Walesஇல் உள்ளூர் காவல்துறையைப் பொறுப்புக்கூறச் செய்ய Police and Crime Commissioners (PCCs) பொதுமக்களால் தேர்ந்தெடுக்கப்படுகின்றனர்."],
  1928: ["உள்ளாட்சி நிதி பற்றிய இக்கூற்றுகளில் எது சரியானது?", "உள்ளாட்சி அமைப்புகளுக்கு மத்திய அரசும் உள்ளூர் council taxஉம் நிதியளிக்கின்றன|உள்ளாட்சி அமைப்புகளுக்கு நன்கொடைகள் மட்டுமே நிதியளிக்கின்றன|உள்ளாட்சி அமைப்புகளுக்கு அரசுப் பணம் கிடைப்பதில்லை|உள்ளாட்சி அமைப்புகளுக்கு மன்னர் நிதியளிக்கிறார்", "Councils குப்பை சேகரிப்பு, நூலகங்கள், பள்ளிகள் போன்ற சேவைகளை வழங்குகின்றன."],
  1935: ["யுகேயின் அரசுத் தலைவர், அரசாங்கத் தலைவர் பற்றி இவற்றுள் எது உண்மை அல்ல?", "Prime Minister அரசுத் தலைவர்|மன்னர் அரசுத் தலைவர்|Prime Minister அரசாங்கத் தலைவர்|இவை இரு தனித்தனிப் பொறுப்புகள்", "மன்னர் அரசுத் தலைவர், Prime Minister அல்ல — Prime Minister அரசாங்கத் தலைவர்."],
  1938: ["ஒரு MP பிரதிநிதித்துவப்படுத்தும் புவியியல் பகுதியை விவரிக்கும் சொல் என்ன என நண்பர் கேட்கிறார். அச்சொல் என்ன?", "ஒரு தொகுதி (constituency)|ஓர் அரசியல் கட்சி|ஓர் அரசுத் துறை|ஒரு council ward", "தொகுதி என்பது ஒரு MP பிரதிநிதித்துவப்படுத்தும் பகுதி; 650 தொகுதிகள் உள்ளன, ஒவ்வொன்றும் ஒரு MPஐத் தேர்ந்தெடுக்கிறது."],
  1943: ["by-election பற்றி இவற்றுள் எது உண்மை அல்ல?", "அது பொதுத் தேர்தல் போல நிலையான ஐந்தாண்டு இடைவெளியில் திட்டமிடப்படுகிறது|ஓர் இடம் காலியாகும்போது அது நடத்தப்படுகிறது|ஓர் MPஇன் பதவி விலகலுக்குப் பிறகு அது வரலாம்|ஓர் MPஇன் மரணத்திற்குப் பிறகு அது வரலாம்", "by-election நிலையான இடைவெளியில் திட்டமிடப்படுவதில்லை — ஓர் இடம் எதிர்பாராமல் காலியாகும்போதெல்லாம் நடக்கிறது, பொதுத் தேர்தல்களின் வழக்கமான ஐந்தாண்டு சுழற்சியைப் போல் அல்ல."],
  1946: ["சுற்றுச்சூழல் போன்ற ஒரே பிரச்சினையில் பிரச்சாரம் செய்யும் குழு பொதுவாக என்ன அழைக்கப்படுகிறது, அது என்ன செய்கிறது என நண்பர் கேட்கிறார். பதில் என்ன?", "ஒரு pressure group, அது அரசுக் கொள்கையைச் செல்வாக்கு செலுத்த முயல்கிறது|ஒரு election commission, அது தேர்தல்களை நடத்துகிறது|ஒரு வரி ஆணையம், அது வரி வசூலிக்கிறது|ஒரு நீதிக்குழு, அது நீதிபதிகளை நியமிக்கிறது", "pressure group ஒரு குறிப்பிட்ட பிரச்சினையில் அரசுக் கொள்கையைச் செல்வாக்கு செலுத்த முயல்கிறது, அக்காரணத்தில் பிரிட்டிஷ் குடிமக்களின் கருத்துகளைப் பிரதிநிதித்துவப்படுத்துகிறது."],
  1951: ["இவற்றுள் எது யுகே சட்டத்தின் இரு முக்கிய ஆதாரங்களில் ஒன்று அல்ல?", "மன்னரால் தனிப்பட்ட முறையில் வழங்கப்படும் அரச ஆணைகள்|Acts of Parliament|Case law|common law ஆகத் திரளும் நீதிபதிகளின் விளக்கங்கள்", "யுகே சட்டம் Acts of Parliament, case lawஇலிருந்து வருகிறது — இன்று மன்னர் தனிப்பட்ட முறையில் சட்டம் உருவாக்கும் கட்டுப்படுத்தும் அரச ஆணைகளை வழங்குவதில்லை."],
  1954: ["கடுமையான குற்றச்சாட்டை எதிர்கொள்ளும் நண்பர் வழக்கறிஞரை நியமிக்க இயலவில்லை. அவருக்கு என்ன ஆதரவு கிடைக்கக்கூடும்?", "Legal aid, அது solicitor அல்லது barristerக்குப் பணம் அளிக்கிறது|ஒரு காவல் அதிகாரி அவரைப் பிரதிநிதித்துவப்படுத்துவார்|ஒரு magistrate அவரைப் பிரதிநிதித்துவப்படுத்துவார்|எந்த ஆதரவும் கிடைக்காது", "உங்கள் சூழல்களையும் வழக்கையும் பொறுத்து Legal aid solicitor அல்லது barristerக்குப் பணம் அளிக்கக்கூடும்."],
  1959: ["Scotlandஇல் கடுமையான குற்றவியல் வழக்குகள் பற்றி இவற்றுள் எது உண்மை அல்ல?", "England போலவே அவை Crown Courtஇல் விசாரிக்கப்படுகின்றன|அவை High Court of Justiciary அல்லது Sheriff Courtஇல் விசாரிக்கப்படுகின்றன|Scotlandக்குத் தனி சட்ட அமைப்பு உள்ளது|Scotlandஇன் நீதிமன்றங்கள் England, Walesஇலிருந்து வேறுபடுகின்றன", "Scotland Crown Court பயன்படுத்துவதில்லை — அது England, Wales, Northern Irelandஇல் பயன்படுத்தப்படும் அமைப்பு. Scotlandக்கு அதற்குப் பதிலாகத் தனி நீதிமன்றங்கள் உள்ளன."],
  1962: ["ஒரு நண்பருக்குத் தாம் பணம் செலுத்திய குறைபாடுள்ள பொருள் தொடர்பாக ஒரு நிறுவனத்துடன் தகராறு உள்ளது. அதைத் தொடர சரியான வழி என்ன?", "County Court அல்லது small claims நடைமுறை|காவல்துறையிடம் புகார் அளிப்பது|நேரடியாக நாடாளுமன்றத்திடம் மேல்முறையீடு செய்வது|The Crown Court", "பணம் செலுத்திய பொருட்கள் அல்லது சேவைகள் தொடர்பான small claims England, Wales, Northern Irelandஇல் County Courtsஇலும் Scotlandஇல் Sheriff Courtsஇலும் கையாளப்படுகின்றன."],
  1967: ["Equality Act கீழ் இவற்றுள் எது சட்டவிரோதமான பாகுபாடு அல்ல?", "அதிக அனுபவமுள்ள ஊழியர்களுக்கு அதிக ஊதியம் வழங்குவது|இனத்தின் அடிப்படையிலான பாகுபாடு|இயலாமையின் அடிப்படையிலான பாகுபாடு|மதத்தின் அடிப்படையிலான பாகுபாடு", "அதிக அனுபவத்திற்கு அதிக ஊதியம் வழங்குவது நியாயமான ஊதிய முடிவு, பாகுபாடு அல்ல — Equality Act இனம், இயலாமை, மதம் போன்ற அடிப்படைகளில் பாகுபாட்டிலிருந்து பாதுகாக்கிறது."],
  1970: ["யுகேயில் புதிதாக வந்த நண்பர் காவல்துறை, தீயணைப்பு அல்லது ஆம்புலன்ஸ் தேவைப்படும் உண்மையான அவசரநிலையில் எந்த எண்ணை அழைக்க வேண்டும் எனக் கேட்கிறார். எந்த எண்?", "999 அல்லது 112|911|101|111", "யுகேயில் அவசர எண்கள் 999 அல்லது 112; 101, 111 அவசரமற்ற விவகாரங்களுக்கு."],
  1975: ["Englandஇல் அவசரமற்ற மருத்துவ ஆலோசனைக்கு இவற்றுள் எது சரியான எண் அல்ல?", "999|111|NHS உதவி எண்|நிலைமை உயிருக்கு ஆபத்தானதாக இல்லாதபோது அழைக்கும் எண்", "999 உண்மையான அவசரநிலைக்கானது — அவசரமற்ற மருத்துவ ஆலோசனை NHS 111 மூலம் கிடைக்கிறது."],
  1978: ["புதிய பகுதிக்குக் குடிபெயர்ந்த நண்பர் அங்கே மருத்துவரிடம் எப்படிப் பதிவு செய்வது எனக் கேட்கிறார். அவர் என்ன செய்ய வேண்டும்?", "உள்ளூர் GP surgeryஇல் பெயர் பதிவு செய்ய வேண்டும்|Home Officeக்கு விண்ணப்பிக்க வேண்டும்|முதலாளியிடம் பதிவு செய்யச் சொல்ல வேண்டும்|மருத்துவமனை சிகிச்சை தேவைப்படும் வரை காத்திருக்க வேண்டும்", "உள்ளூர் GP surgeryஇல் பெயர் பதிவு செய்து மருத்துவரிடம் பதிவு செய்யலாம்; அவசரமற்ற உடல்நலப் பிரச்சினைகளுக்கு GPs பொதுவாக முதல் தொடர்பு புள்ளி."],
  1983: ["இவற்றுள் யார் MPஆக நிற்கத் தகுதியிழக்கவில்லை?", "18 வயது அல்லது மேற்பட்ட தகுதியுள்ள Commonwealth குடிமகன்|ஆயுதப் படையின் பணியிலுள்ள உறுப்பினர்|பணியிலுள்ள civil servant|தண்டனை அனுபவிக்கும் கைதி", "18 வயது அல்லது மேற்பட்ட தகுதியுள்ள Commonwealth குடிமகன் MPஆக நிற்கலாம் — ஆயுதப் படை உறுப்பினர்கள், civil servants, கைதிகள் தகுதியிழக்கின்றனர்."],
  1986: ["ஒரு நண்பர் சமூகப் பங்கேற்பின் ஒரு வடிவமாகத் தமது உள்ளூர்ப் பள்ளியுடன் இணைய விரும்புகிறார். அவர் எந்த ஊதியமற்ற பொறுப்பை ஏற்கலாம்?", "School governor|Head teacher|உள்ளாட்சி ஊழியர்|அரசு ஆய்வாளர்", "school governor ஆவது ஒரு பள்ளியை நடத்த உதவவும் உங்கள் சமூகத்தில் பங்கேற்கவும் ஒரு தன்னார்வ வழி."],
  1991: ["jury service பற்றி இவற்றுள் எது உண்மை அல்ல?", "ஹாஜராவதைத் தவிர்க்க வெறுமனே கட்டணம் செலுத்தலாம்|அது ஒரு பொதுக் கடமை|செல்லுபடியான காரணத்திற்கு விலக்கு பெறலாம்|jurors electoral registerஇலிருந்து சீரற்ற முறையில் தேர்ந்தெடுக்கப்படுகின்றனர்", "jury serviceஐத் தவிர்க்க வெறுமனே கட்டணம் செலுத்த முடியாது — அது ஒரு பொதுக் கடமை, செல்லுபடியான காரணம் மட்டுமே ஹாஜராவதிலிருந்து விலக்களிக்க முடியும்."],
  1994: ["House of Commonsஇன் Speaker தேர்ந்தெடுக்கப்பட்ட பிறகு தமது தொகுதியைப் பிரதிநிதித்துவப்படுத்துவதை நிறுத்துகிறாரா என நண்பர் கேட்கிறார். பதில் என்ன?", "இல்லை — Speaker MPஆகத் தமது வாக்காளர்களைப் பிரதிநிதித்துவப்படுத்தத் தொடர்கிறார்|ஆம் — Speaker தமது தொகுதியை முற்றிலும் விட்டுவிடுகிறார்|ஆம் — Speaker அதற்குப் பதிலாக அரசைப் பிரதிநிதித்துவப்படுத்துகிறார்|இல்லை — ஆனால் Speaker விவாதங்களுக்கு மட்டும் தலைமை தாங்குகிறார், வேறொன்றும் இல்லை", "Speaker தொகுதி MPஆகவே இருந்து தமது வாக்காளர்களைப் பிரதிநிதித்துவப்படுத்தத் தொடர்கிறார், ஆனால் Commons அவையில் அரசியல் ரீதியாக நடுநிலையாக இருக்க வேண்டும்."],
  1999: ["சட்டங்களை ஆய்வு செய்வதில் House of Lordsஇன் பங்கு பற்றி இவற்றுள் எது உண்மை அல்ல?", "அதன் முடிவுகளை Commons ஒருபோதும் மீற முடியாது|அது மசோதாக்களில் திருத்தங்களை முன்மொழியலாம்|அது Commonsஇலிருந்து வரும் சட்டங்களை ஆய்வு செய்கிறது|Commons இறுதியில் அதை மீறலாம்", "Commons இறுதியில் House of Lordsஐ மீறலாம் — சட்டங்கள் குறித்த Lordsஇன் முடிவுகள் இறுதியானவையோ சவால் செய்ய முடியாதவையோ அல்ல."],
  2002: ["ஒரு நண்பர் தமது council tax கட்டணத்தைச் செலுத்தாமலே இருக்க நினைக்கிறார். அதன் விளைவாக அவருக்கு என்ன நேரலாம்?", "அவர் நீதிமன்றத்திற்கு அழைத்துச் செல்லப்பட்டு கூடுதல் செலவுகளை எதிர்கொள்ளலாம்|எதுவும் இல்லை — அது முற்றிலும் தன்னார்வமானது|அவரது கடவுச்சீட்டு பறிக்கப்படலாம்|அவர் நாடு கடத்தப்படலாம்", "council tax செலுத்தாவிட்டால் நீதிமன்றத்திற்கு அழைத்துச் செல்லப்பட்டு கூடுதல் செலவுகளை எதிர்கொள்ள நேரிடலாம் — அது தன்னார்வக் கட்டணம் அல்ல."],
  2007: ["இவற்றுள் எது devolved powerஇன் எடுத்துக்காட்டு அல்ல?", "மன்னரால் தனிப்பட்ட முறையில் வைத்திருக்கப்படும் அதிகாரங்கள்|சுகாதாரம் போன்ற துறைகளில் Scotlandஇன் கட்டுப்பாடு|கல்வி போன்ற துறைகளில் Walesஇன் கட்டுப்பாடு|Northern Irelandஇன் devolved நிர்வாக அதிகாரங்கள்", "devolved அதிகாரங்கள் மத்திய அரசிடமிருந்து Scottish Parliament போன்ற அமைப்புகளுக்கு மாற்றப்படுகின்றன — அவை மன்னரால் தனிப்பட்ட முறையில் வைத்திருக்கப்படும் அதிகாரங்கள் அல்ல."],
  2010: ["யுகேயில் தமது முதல் வேலையைத் தொடங்கும் நண்பர் ஒரு தொழிலாளியாக இப்போது தமது நிதிப் பொறுப்பு என்ன எனக் கேட்கிறார். அது என்ன?", "வருமான வரியும் National Insuranceஉம் செலுத்துவது|ஒரு தொழிற்சங்கத்தில் சேருவது|ஒவ்வொரு தேர்தலிலும் வாக்களிப்பது|magistrateஆகப் பணியாற்றுவது", "வேலை செய்யும் ஒவ்வொரு யுகே குடியிருப்பாளருக்கும் வருமான வரியும் National Insuranceஉம் செலுத்தும் பொறுப்பு உள்ளது, அவை சாலைகள், பள்ளிகள், NHS போன்ற பொதுச் சேவைகளுக்குப் பணம் அளிக்கின்றன."],
};
